
CREATE TABLE AUTH.USER_COMPANY_SCOPE (ID NUMBER(11, 0) NOT NULL, COMPANY_ID NUMBER(11, 0) NOT NULL, PERMISSION_ID NUMBER(11, 0) NOT NULL, SDP_ACCESS NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT USERCOMPANYSCOPE_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.USER_SERVICE_SCOPE (ID NUMBER(11, 0) NOT NULL, SERVICE_ID NUMBER(11, 0) NOT NULL, PERMISSION_ID NUMBER(11, 0) NOT NULL, SDP_ACCESS NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT USERSERVICESCOPE_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.PROFILE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, IS_AUTOMATIC NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT PROFILE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.SERVICE (ID NUMBER(10, 0) NOT NULL, SERVICE_TYPE_ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, SERVICE_LEVEL_ID NUMBER(10, 0) NOT NULL, SUGGESTED_ADDRESS_ID NUMBER(10, 0), PUBLIC_COMMENTS VARCHAR2(32767 BYTE), PRIVATE_COMMENTS VARCHAR2(32767 BYTE), COMPANY_UNIT_ID NUMBER(10, 0), INSTALLATION_COMMENTS VARCHAR2(2000 BYTE), CONFIGURATION_GROUP_ID NUMBER(10, 0), PATH_SELECTION_PROFILE_ID NUMBER(10, 0), PLATFORM_TYPE_ID NUMBER(10, 0) DEFAULT 1 NOT NULL, CLOUD_REGION_INSTANCE_ID NUMBER(10, 0), PLATFORM_DEPLOYMENT_ENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, CONSTRAINT SERVICE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.SERVICE.INSTALLATION_COMMENTS IS 'Comment on the current installation state of the service. Is displayed in the MCA task overview.';
COMMENT ON COLUMN MSS.SERVICE.CONFIGURATION_GROUP_ID IS 'Links to the config group';

CREATE TABLE AUTH.LOGIN2PROFILE (LOGIN_ID NUMBER(11, 0) NOT NULL, PROFILE_ID NUMBER(11, 0) NOT NULL, CONSTRAINT LOGIN2PROFILE_PK PRIMARY KEY (LOGIN_ID, PROFILE_ID));

CREATE TABLE AUTH.USER_PERMISSION (ID NUMBER(11, 0) NOT NULL, USER_ROLE_ID NUMBER(11, 0) NOT NULL, PROFILE_ID NUMBER(11, 0) NOT NULL, CONSTRAINT USERPERMISSION_PK PRIMARY KEY (ID));

CREATE TABLE STOP.COMPANY (ID NUMBER(22, 0) NOT NULL, NAME VARCHAR2(50 BYTE), SHORT VARCHAR2(10 BYTE), MAIN_FAX VARCHAR2(50 BYTE), MAIN_PHONE VARCHAR2(50 BYTE), URL VARCHAR2(2048 BYTE), ADDRESS_ID NUMBER(10, 0), DEFAULT_COMPANY_UNIT_ID NUMBER(10, 0), ALIASES VARCHAR2(2000 BYTE), MANAGING_COMPANY_ID NUMBER(22, 0), COMPANY_SECTOR_ID NUMBER(10, 0), SIGN_OFF_COMMENTS VARCHAR2(2000 BYTE), SIGN_OFF_NOT_BY_REQUESTER NUMBER(1, 0) DEFAULT 0 NOT NULL, CONNECTIVITY_SLA NUMBER(1, 0) DEFAULT 0 NOT NULL, SUBPROCESSOR_CONSENT NUMBER(1, 0) DEFAULT 0 NOT NULL, API_ENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, SWISS_ONLY_OPS NUMBER(1, 0) DEFAULT 0 NOT NULL, PREFIX VARCHAR2(10 BYTE), CONSTRAINT COMPANY_PK PRIMARY KEY (ID));
COMMENT ON COLUMN STOP.COMPANY.ADDRESS_ID IS 'main address';
COMMENT ON COLUMN STOP.COMPANY.DEFAULT_COMPANY_UNIT_ID IS 'Company unit for escalations or changes when service does not provide a company unit';
COMMENT ON COLUMN STOP.COMPANY.ALIASES IS 'Holds new-line separated company alias names';
COMMENT ON COLUMN STOP.COMPANY.SIGN_OFF_NOT_BY_REQUESTER IS 'Boolean to indicate whether a change request can be signed-off by the requester or not.';
COMMENT ON COLUMN STOP.COMPANY.CONNECTIVITY_SLA IS 'Indicates whether connectivity SLA reporting is done for this company or not.';
COMMENT ON COLUMN STOP.COMPANY.SUBPROCESSOR_CONSENT IS 'Indicates whether customer has signed the sub-processor agreement.';
COMMENT ON COLUMN STOP.COMPANY.API_ENABLED IS 'Indicates whether customer has API usage enabled.';
COMMENT ON COLUMN STOP.COMPANY.SWISS_ONLY_OPS IS 'Can only be accessed by admins in MC center EMEA/Zurich.';

CREATE TABLE AUTH.USER_COMPANY_UNIT_SCOPE (ID NUMBER(11, 0) NOT NULL, COMPANY_UNIT_ID NUMBER(11, 0) NOT NULL, PERMISSION_ID NUMBER(11, 0) NOT NULL, SDP_ACCESS NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT USERCOMPANYUNITSCOPE_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.USER_UNIT (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, TOKEN_POOL_ID NUMBER(10, 0), DEFAULT_UNIT NUMBER(1, 0) NOT NULL, DESCRIPTION VARCHAR2(512 BYTE), CONSTRAINT USERUNIT_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.USER_UNIT_SCOPE (ID NUMBER(11, 0) NOT NULL, USER_UNIT_ID NUMBER(11, 0) NOT NULL, PERMISSION_ID NUMBER(11, 0) NOT NULL, SDP_ACCESS NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT USERUNITSCOPE_PK PRIMARY KEY (ID));

CREATE TABLE MCDB_MONITOR.LAST_CONSISTENCY_CHECK_RESULTS (CHECK_ID VARCHAR2(50 BYTE) NOT NULL, CHECK_GROUP VARCHAR2(50 BYTE), MESSAGE VARCHAR2(4000 BYTE), XML_MESSAGE CLOB, LOGLEVEL VARCHAR2(20 BYTE), LAST_RUN TIMESTAMP(6), CONSTRAINT LAST_CONSISTENCY_CHECK_RESULTS_PK PRIMARY KEY (CHECK_ID));

CREATE TABLE MCDB_CHECKS.CONSISTENCY_CHECK_RUN (ID NUMBER NOT NULL, CHECK_KEY VARCHAR2(100 BYTE), LAST_RUN TIMESTAMP(6) DEFAULT SYSDATE, LAST_RESULT_HASH RAW(20), CONSTRAINT CONSISTENCY_CHECK_RUN_PK PRIMARY KEY (ID));

CREATE TABLE MCDB_CHECKS.CONSISTENCY_CHECKS (ID NUMBER NOT NULL, CHECK_KEY VARCHAR2(100 BYTE), CHECK_GROUP VARCHAR2(100 BYTE) DEFAULT 'default', STATEMENT VARCHAR2(4000 BYTE), MESSAGE VARCHAR2(4000 BYTE), PLOGLEVEL NUMBER DEFAULT 5, SLOGLEVEL VARCHAR2(20 BYTE) DEFAULT 'WARN', CONSTRAINT SYS_C0020061 PRIMARY KEY (ID));

CREATE TABLE MSS.HOST (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, OPERATING_SYSTEM_ID NUMBER(10, 0) NOT NULL, SERVICE_COMPANY_ID NUMBER(10, 0) NOT NULL, ADDRESS_ID NUMBER(10, 0), HARDWARE_ID NUMBER(10, 0), REPLACEMENT_HARDWARE_ID NUMBER(10, 0), MONITORED NUMBER(1, 0) DEFAULT 1 NOT NULL, ACTIVE NUMBER(1, 0) DEFAULT 0 NOT NULL, ESCALATION_TIMEOUT NUMBER(10, 0), UNSTABLE NUMBER(1, 0) DEFAULT 0 NOT NULL, MAINTENANCE_STATUS_ID NUMBER(10, 0), COMMENTS VARCHAR2(1024 BYTE), DESCRIPTION VARCHAR2(128 BYTE), AUTHOR VARCHAR2(64 BYTE) NOT NULL, IPSEC_PUBKEY VARCHAR2(1024 BYTE), SSH_PUBKEY VARCHAR2(1024 BYTE), OPENVPN_CERT VARCHAR2(4000 BYTE), SSH_CERT VARCHAR2(4000 BYTE), SSH_CERT_TIMESTAMP NUMBER(10, 0), LOGFORWARDING_CERT VARCHAR2(32767 BYTE), FW_POLICY_ID NUMBER(10, 0), SSH_RSA_PUBKEY VARCHAR2(32767 BYTE), SSH_ED25519_PUBKEY VARCHAR2(32767 BYTE), SSH_RSA_CERT VARCHAR2(32767 BYTE), SSH_ED25519_CERT VARCHAR2(32767 BYTE), SSH_RSA_CERT_TIMESTAMP NUMBER(10, 0), SSH_ED25519_CERT_TIMESTAMP NUMBER(10, 0), OPENVPN_SERVER_CERT VARCHAR2(32767 BYTE), CLUSTER_PRIORITY NUMBER(1, 0), OSPF_ROUTERID_OVERRIDE NUMBER(10, 0), CONSTRAINT HOST_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.HOST.UNSTABLE IS 'Host is in a unreliable environment (frequent power interruptions or unreliable layer 2 infrastructure). Certain GUMA events will be suppressed.';
COMMENT ON COLUMN MSS.HOST.MAINTENANCE_STATUS_ID IS 'Maintenance status of the host (active, inactive, maintenance, unknown) as determined by according DB job';

CREATE TABLE MSS.HARDWARE (ID NUMBER(10, 0) NOT NULL, HARDWARE_TYPE_ID NUMBER(10, 0) NOT NULL, BARCODE VARCHAR2(32 BYTE), SERIAL_NUMBER VARCHAR2(256 BYTE), MAC_ADDRESS VARCHAR2(128 BYTE), HARDWARE_IDENTIFIER VARCHAR2(128 BYTE), PURCHASE_DATE date, DISPOSAL_DATE date, HARDWARE_DISPOSAL_REASON_ID NUMBER(10, 0), HARDWARE_DISPOSAL_COMMENTS VARCHAR2(512 BYTE), HARDWARE_DISPOSAL_CONTACT_ID NUMBER(10, 0), HARDWARE_DEPLOY_REASON_ID NUMBER(10, 0), COMMENTS VARCHAR2(4000 BYTE), HARDWARE_LIFECYCLE_ITEM_ID NUMBER(10, 0), CONSTRAINT HARDWARE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.HARDWARE.HARDWARE_DISPOSAL_REASON_ID IS 'link to the hardware_disposal_reason table';
COMMENT ON COLUMN MSS.HARDWARE.HARDWARE_DISPOSAL_COMMENTS IS 'comments on hardware disposal (if any)';
COMMENT ON COLUMN MSS.HARDWARE.HARDWARE_DISPOSAL_CONTACT_ID IS 'contact of the OSAG person who did the disposal action';
COMMENT ON COLUMN MSS.HARDWARE.HARDWARE_DEPLOY_REASON_ID IS 'reason for the deployement, null if the hardware is not assigned to a host at the moment';
COMMENT ON COLUMN MSS.HARDWARE.HARDWARE_LIFECYCLE_ITEM_ID IS 'The latest (and therefore active) hardware lifecycle item';

CREATE TABLE MSS.HARDWARE_LIFECYCLE_ITEM (ID NUMBER(10, 0) NOT NULL, HARDWARE_ID NUMBER(10, 0) NOT NULL, HARDWARE_LC_STATE_ID NUMBER(10, 0) NOT NULL, HARDWARE_LC_LOCATION_ID NUMBER(10, 0) NOT NULL, HARDWARE_LC_TRANSIT_STATE_ID NUMBER(10, 0), HARDWARE_LC_TRANSIT_INFO_ID NUMBER(10, 0), CREATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, CREATOR NUMBER(10, 0), ACTIVATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT HARDWARELIFECYCLEITEM_PK PRIMARY KEY (ID));

CREATE TABLE MSS.SERVICE_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, INTERNAL_CODE VARCHAR2(16 BYTE), DEPRECATED NUMBER(1, 0) DEFAULT 0 NOT NULL, INTERNAL NUMBER(1, 0) DEFAULT 0 NOT NULL, DESCRIPTION VARCHAR2(2000 BYTE), CONSTRAINT SERVICETYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.HARDWARE_HISTORY (ID NUMBER(10, 0) NOT NULL, COMPANY_SHORT VARCHAR2(10 BYTE) NOT NULL, HOST_NAME VARCHAR2(32 BYTE) NOT NULL, SERVICE_TYPE_INTERNAL_CODE VARCHAR2(32 BYTE), PURCHASE_DATE date NOT NULL, DISPOSAL_DATE date NOT NULL, HISTORY_DATE date NOT NULL, MAC_ADDRESS VARCHAR2(128 BYTE), SERIAL_NUMBER VARCHAR2(256 BYTE), BARCODE VARCHAR2(32 BYTE), HARDWARE_DISPOSAL_COMMENTS VARCHAR2(1024 BYTE), LOG VARCHAR2(2000 BYTE), HARDWARE_DISPOSAL_REASON_ID NUMBER(10, 0) NOT NULL, HARDWARE_DISPOSAL_CONTACT_ID NUMBER(10, 0) NOT NULL, HARDWARE_TYPE_ID NUMBER(10, 0) NOT NULL, HARDWARE_DEPLOY_REASON_ID NUMBER(10, 0), CONSTRAINT HARDWAREHISTORY_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.COMPANY_SHORT IS 'the company where the host/hardware belonged to';
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.HOST_NAME IS 'the name of the host where the hardware belonged to';
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.SERVICE_TYPE_INTERNAL_CODE IS 'the internal code of the service type which ran on the host';
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.PURCHASE_DATE IS 'purchase date of the hardware';
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.DISPOSAL_DATE IS 'disposal date of the hardware';
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.HISTORY_DATE IS 'the date when the history record was created';
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.MAC_ADDRESS IS 'the hardware''s ''primary'' (?) MAC address';
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.SERIAL_NUMBER IS 'serial number of the hardware';
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.BARCODE IS 'barcode of the hardware';
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.HARDWARE_DISPOSAL_COMMENTS IS 'comments';
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.LOG IS 'contains "selected information" related to this host in order to preserve it when related objects are deleted,
f.e. the company and host where this hardware belonged to might be deleted.';
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.HARDWARE_DISPOSAL_REASON_ID IS 'link to the hardware_disposal_reason table';
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.HARDWARE_DISPOSAL_CONTACT_ID IS 'contact of the OSAG person who did the disposal action';
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.HARDWARE_TYPE_ID IS 'link to the hardware_type table';
COMMENT ON COLUMN MSS.HARDWARE_HISTORY.HARDWARE_DEPLOY_REASON_ID IS 'The reason why the hardware was deployed for this entry';

CREATE TABLE STOP.CONTACT (ID NUMBER(22, 0) NOT NULL, LASTNAME VARCHAR2(50 BYTE), FIRSTNAME VARCHAR2(50 BYTE), SHORT VARCHAR2(10 BYTE), COMPANY_ID NUMBER(22, 0), DIRECT VARCHAR2(30 BYTE), EMAIL VARCHAR2(250 BYTE), FAX VARCHAR2(30 BYTE), FUNCTION VARCHAR2(250 BYTE), HOME VARCHAR2(30 BYTE), MCC_RANK NUMBER(2, 0) DEFAULT 0 NOT NULL, MOBILE VARCHAR2(30 BYTE), OFFICE VARCHAR2(30 BYTE), CREATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, MODIFIED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, COMMENTS VARCHAR2(200 BYTE), CONSTRAINT CONTACT_PK PRIMARY KEY (ID));

CREATE TABLE MSS.HARDWARE_DISPOSAL_REASON (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(512 BYTE), OBSOLETE NUMBER(1, 0) NOT NULL, CONSTRAINT HARDWAREDISPOSALREASON_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.HARDWARE_DISPOSAL_REASON.NAME IS 'short descriptive name of the disposal reason';
COMMENT ON COLUMN MSS.HARDWARE_DISPOSAL_REASON.DESCRIPTION IS 'description of the disposal reason';
COMMENT ON COLUMN MSS.HARDWARE_DISPOSAL_REASON.OBSOLETE IS 'when != 0, this reason is obsolete and may not be selected any more.
it is preserved for being referenced by the hardware_history table.';

CREATE TABLE MSS.HARDWARE_TYPE (ID NUMBER(10, 0) NOT NULL, SHORT VARCHAR2(16 BYTE) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, PROFORMA_NAME VARCHAR2(256 BYTE), PROFORMA_WEIGHT NUMBER(10, 0), PROFORMA_PRICE NUMBER(10, 0), PROFORMA_ORIGIN_COUNTRY VARCHAR2(256 BYTE), MAC_ADDRESS_REQUIRED NUMBER(1, 0) DEFAULT 1 NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), PROFORMA_DESCRIPTION VARCHAR2(2000 BYTE), EOL NUMBER(1, 0) DEFAULT 0 NOT NULL, PACKAGE_WEIGHT NUMBER(10, 0), MANUFACTURER_ADDRESS VARCHAR2(1024 BYTE), COMMENTS VARCHAR2(4000 BYTE), VIRTUAL NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT HARDWARETYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.HOST2SERVICE (HOST_ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT HOST2SERVICE_PK PRIMARY KEY (HOST_ID, SERVICE_ID));

CREATE TABLE STOP.COMPANY_UNIT (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(256 BYTE) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, CONTACT_HANDLING_ID NUMBER(10, 0) NOT NULL, UPGRADE_SLOT_COMMENTS VARCHAR2(2000 BYTE), SLA_COMMENTS VARCHAR2(2000 BYTE), CONSTRAINT COMPANYUNIT_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.LOGIN (ID NUMBER(11, 0) NOT NULL, LOGIN VARCHAR2(250 BYTE) DEFAULT '', CONTACT_ID NUMBER(22, 0) DEFAULT 0 NOT NULL, ENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, LOCKED NUMBER(1, 0) DEFAULT 0 NOT NULL, COMPANY_ID NUMBER(11, 0) NOT NULL, MODIFIED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, CREATIONDATE TIMESTAMP(6) WITH TIME ZONE, OIDC_ZITADEL_ID VARCHAR2(128 BYTE), OIDC_FEDERATED NUMBER(1, 0) DEFAULT 0 NOT NULL, OIDC_ZITADEL_USERNAME VARCHAR2(250 BYTE), OIDC_UPN VARCHAR2(250 BYTE), SOC_ANALYST NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT LOGIN_PK PRIMARY KEY (ID));
COMMENT ON COLUMN AUTH.LOGIN.CREATIONDATE IS 'The date when a user entry was created, i.e., the first AD sync or the time of user creation in the portal';

CREATE TABLE AUTH.USER_ROLE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE) NOT NULL, IS_INTERNAL NUMBER(1, 0) DEFAULT 0 NOT NULL, USER_ROLE_SCOPE_TYPE_ID NUMBER(11, 0) NOT NULL, CONSTRAINT USERROLE_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.TOKEN (ID NUMBER(11, 0) NOT NULL, COMPANY_ID NUMBER(11, 0), ENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, EXPIRYDATE date, SEED VARCHAR2(50 BYTE), SERIAL VARCHAR2(20 BYTE) NOT NULL, SECIDDRIFT NUMBER(4, 0) DEFAULT 0, ACTERCOUNT NUMBER(22, 0) DEFAULT 0, DPBLOB VARCHAR2(256 BYTE), TOKENFORM_ID NUMBER(11, 0) NOT NULL, TOKENTYPE_ID NUMBER(11, 0) NOT NULL, TOKEN_POOL_ID NUMBER(11, 0), VALIDFROM date, ACTIVATED NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT TOKEN_PK PRIMARY KEY (ID));
COMMENT ON COLUMN AUTH.TOKEN.COMPANY_ID IS 'The company to which this token has been sold.
If NULL, the token is available for Token Shop sales.
If the company is Open Systems, the token is either for internal
use or is not in use yet and can be transferred to a specific company
when the token is sold.';

CREATE TABLE MAIL.DMARC_REPORT_RECORD (ID NUMBER(10, 0) NOT NULL, DMARC_REPORT_ID NUMBER(10, 0) NOT NULL, IP_ADDRESS_HIGH NUMBER(20, 0), IP_ADDRESS_LOW NUMBER(20, 0) NOT NULL, PTR VARCHAR2(100 BYTE), COUNTRY VARCHAR2(100 BYTE), COUNT NUMBER(10, 0) NOT NULL, HEADER_FROM VARCHAR2(400 BYTE), DMARC_DISPOSITION_ID NUMBER(10, 0) NOT NULL, SPF VARCHAR2(10 BYTE) NOT NULL, DKIM VARCHAR2(10 BYTE) NOT NULL, REASON VARCHAR2(200 BYTE), REASON_COMMENT VARCHAR2(400 BYTE), SPF_DOMAIN VARCHAR2(400 BYTE), DMARC_SPF_RESULT_ID NUMBER(10, 0) NOT NULL, DKIM_DOMAIN VARCHAR2(400 BYTE), DMARC_DKIM_RESULT_ID NUMBER(10, 0) NOT NULL, CONSTRAINT DMARCREPORTRECORD_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MAIL.DMARC_REPORT_RECORD.IP_ADDRESS_HIGH IS '64 highest bits of IP address (is NULL for IPv4)';
COMMENT ON COLUMN MAIL.DMARC_REPORT_RECORD.IP_ADDRESS_LOW IS '64 lowest bits of IP address';

CREATE TABLE MAIL.DMARC_REPORT (ID NUMBER(10, 0) NOT NULL, REPORT_ID VARCHAR2(200 BYTE) NOT NULL, DMARC_REPORT_ORG_ID NUMBER(10, 0) NOT NULL, DMARC_REPORT_DOMAIN_ID NUMBER(10, 0) NOT NULL, START_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, END_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, POLICY_ASPF VARCHAR2(10 BYTE), POLICY_ADKIM VARCHAR2(10 BYTE), POLICY_P VARCHAR2(10 BYTE), POLICY_SP VARCHAR2(10 BYTE), POLICY_PCT NUMBER(3, 0), CONSTRAINT DMARCREPORT_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MAIL.DMARC_REPORT.DMARC_REPORT_ORG_ID IS 'The organization ID this report belongs to.';

CREATE TABLE AUTH.ROLE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(50 BYTE) NOT NULL, DESCRIPTION VARCHAR2(500 BYTE) DEFAULT '', CONSTRAINT ROLE_PK PRIMARY KEY (ID));

CREATE TABLE GUMA2.SYSLOG_MESSAGE (ID NUMBER(10, 0) NOT NULL, APPLICATION_TYPE_ID NUMBER(10, 0) NOT NULL, DB_DATE date NOT NULL, LOG_DATE date NOT NULL, MESSAGE CLOB NOT NULL, MS_EVENT_ID NUMBER(10, 0), PRIORITY VARCHAR2(3 BYTE) DEFAULT '0', PROTECTED_HOST_ID NUMBER(10, 0) NOT NULL, SENSOR_HOST_ID NUMBER(10, 0) NOT NULL, SIGNATURE_ID NUMBER(10, 0) NOT NULL, SYSLOG_FACILITY_ID NUMBER(10, 0) NOT NULL, SYSLOG_MESSAGE_TYPE_ID NUMBER(10, 0) NOT NULL, SYSLOG_SEVERITY_ID NUMBER(10, 0) NOT NULL, TAG VARCHAR2(64 BYTE), CONSTRAINT SYSLOGMESSAGE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN GUMA2.SYSLOG_MESSAGE.SYSLOG_MESSAGE_TYPE_ID IS 'Type of the syslog message';

CREATE TABLE MCAUDIT.RECORD (ID NUMBER(10, 0) NOT NULL, APPLICATION_ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0), COMPONENT_ID NUMBER(10, 0) NOT NULL, CONTACT_ID NUMBER(10, 0), DETAILS CLOB, MESSAGE VARCHAR2(2000 BYTE) NOT NULL, OBJECT_ID NUMBER(10, 0), OBJECT_TYPE_ID NUMBER(10, 0), RECORD_TYPE_ID NUMBER(10, 0) NOT NULL, SEVERITY_ID NUMBER(10, 0) DEFAULT 30 NOT NULL, TICKET_ID NUMBER(10, 0), TIMESTAMP TIMESTAMP(6) WITH TIME ZONE NOT NULL, TRANSACTION_ID NUMBER(18, 0) NOT NULL, ZITADEL_USER_ID VARCHAR2(128 BYTE), ZITADEL_USER_NAME VARCHAR2(128 BYTE), ZITADEL_USER_COMPANY_ID NUMBER(22, 0), CONSTRAINT RECORD_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MCAUDIT.RECORD.COMPANY_ID IS 'the company where the object referenced by object_id / object_type_id belongs to. this is
also the company whose users/admins may view this record.';
COMMENT ON COLUMN MCAUDIT.RECORD.CONTACT_ID IS 'who did this (may be NULL for system scripts, synchronization etc.)';
COMMENT ON COLUMN MCAUDIT.RECORD.DETAILS IS 'detailed record message (XML)';
COMMENT ON COLUMN MCAUDIT.RECORD.MESSAGE IS 'short, descriptive message of what was done';
COMMENT ON COLUMN MCAUDIT.RECORD.OBJECT_ID IS 'id of the referenced object of type (object_type_id)';
COMMENT ON COLUMN MCAUDIT.RECORD.OBJECT_TYPE_ID IS 'object type of the referenced object (see mss.object_type)';
COMMENT ON COLUMN MCAUDIT.RECORD.TRANSACTION_ID IS 'a transaction id which is equal for records which belong together';
COMMENT ON COLUMN MCAUDIT.RECORD.ZITADEL_USER_ID IS 'Zitadel ID (Sub) of the User who made this change (human or service user)';
COMMENT ON COLUMN MCAUDIT.RECORD.ZITADEL_USER_NAME IS 'Name at the time of the change of the Zitadel user who made this change (kept it for audit purposes in case of changes in Zitadel)';
COMMENT ON COLUMN MCAUDIT.RECORD.ZITADEL_USER_COMPANY_ID IS 'Company ID of the Zitadel User who made the change, stored here to see without additional fetching if change was made by Open Systems (MC) or the customer.';

CREATE TABLE MCAUDIT.APPLICATION (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, SHORT VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(500 BYTE), CONSTRAINT APPLICATION_PK PRIMARY KEY (ID));

CREATE TABLE MCAUDIT.RECORD_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, SHORT VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(500 BYTE), SYSTEM_ID NUMBER(10, 0), CONSTRAINT RECORDTYPE_PK PRIMARY KEY (ID));

CREATE TABLE MCAUDIT.SEVERITY (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, SHORT VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(512 BYTE) NOT NULL, CONSTRAINT SEVERITY_PK PRIMARY KEY (ID));
COMMENT ON TABLE MCAUDIT.SEVERITY IS 'log level';

CREATE TABLE MC.MON_SERVER_CONNECTION (HOST_ID NUMBER(10, 0) NOT NULL, MON_SERVER_ID NUMBER(10, 0) NOT NULL, CON_TIMESTAMP NUMBER(10, 0), DELAY NUMBER(9, 0), DETAILS VARCHAR2(2024 BYTE), ENTRY_DATE TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, STATUS NUMBER(22, 0), IPV4_ADDRESS NUMBER(10, 0), IPV6_ADDRESS_1 NUMBER(20, 0), IPV6_ADDRESS_2 NUMBER(20, 0), IS_OPENVPN NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT MONSERVERCONNECTION_PK PRIMARY KEY (HOST_ID, MON_SERVER_ID));
COMMENT ON COLUMN MC.MON_SERVER_CONNECTION.IPV6_ADDRESS_1 IS 'The most significant 64 bits of the IPv6 address.';
COMMENT ON COLUMN MC.MON_SERVER_CONNECTION.IPV6_ADDRESS_2 IS 'The least significant 64 bits of the IPv6 address.';

CREATE TABLE TT.EVENT (ID NUMBER(22, 0) NOT NULL, TYPE_ID NUMBER(22, 0) NOT NULL, PUBLIC_EVENT NUMBER(1, 0) DEFAULT 1 NOT NULL, TICKET_ID NUMBER(22, 0) NOT NULL, COMPANY_ID NUMBER(22, 0), EVENTDATE date DEFAULT SYSDATE NOT NULL, CONTACT_ID NUMBER(22, 0), HOST_ID NUMBER(22, 0), SIGN_OFF_OK NUMBER(1, 0), DEMOTED NUMBER(1, 0) DEFAULT 0 NOT NULL, DB_DATE date DEFAULT SYSDATE NOT NULL, PEER_CONTACT_ID NUMBER(22, 0), DETAILS_PRIVATE VARCHAR2(32767 BYTE), DETAILS_PUBLIC VARCHAR2(32767 BYTE), DELETED_HOST_ID NUMBER(22, 0), PINNED NUMBER(1, 0), ORG_TICKET_ID NUMBER, CONTACT_ZITADEL_ID VARCHAR2(128 BYTE), PEER_CONTACT_ZITADEL_ID VARCHAR2(128 BYTE), CONSTRAINT EVENT_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TT.EVENT.SIGN_OFF_OK IS 'This is one of the few legitimate places to define a "nullable ''boolean''",
cause for older events, the sticky signoff status is just not known, and we
need to know that.';

CREATE TABLE MC.ISP_LINK_HISTORY (ID NUMBER(22, 0) NOT NULL, ISP_LINK_ID NUMBER(10, 0) NOT NULL, REPORTING_HOST_ID NUMBER(10, 0), OLD_ISP_LINK_STATUS_TYPE_ID NUMBER(10, 0) NOT NULL, NEW_ISP_LINK_STATUS_TYPE_ID NUMBER(10, 0) NOT NULL, CHANGE_DATE date NOT NULL, EVENT_ID NUMBER(22, 0), CONSTRAINT ISPLINKHISTORY_PK PRIMARY KEY (ID));

CREATE TABLE MC.ISP_LINK_STATUS_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(25 BYTE), DESCRIPTION VARCHAR2(200 BYTE), CONSTRAINT ISPLINKSTATUSTYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.ISP_LINK (ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0), MC_CUSTOMER_ID NUMBER(10, 0), ACCOUNT_NUMBER VARCHAR2(256 BYTE), LINE_NUMBER VARCHAR2(256 BYTE), BANDWIDTH_DOWN NUMBER(10, 0), BANDWIDTH_UP NUMBER(10, 0), SLA_AVAILABILITY NUMBER, MTU NUMBER(10, 0), ROUTER_IP_ADDRESS1 NUMBER(10, 0) NOT NULL, COMMENTS VARCHAR2(2000 BYTE), ACCOUNT_MANAGER_ID NUMBER(10, 0), SUPPORT_ID NUMBER(10, 0), EVENT_TYPE_ID NUMBER(22, 0) NOT NULL, PRODUCT_NAME VARCHAR2(256 BYTE), CONTRACT_DURATION NUMBER(10, 0), CANCELLATION_PERIOD NUMBER(10, 0), LAST_REVIEW_DATE date, MONITORING_MTTR NUMBER(10, 0), CURRENCY_ID NUMBER(10, 0) NOT NULL, LINK_INSTALLATION_FEE NUMBER, LINK_RECURRING_FEE NUMBER, COST_COMMENTS VARCHAR2(2000 BYTE), WAN_MANAGED NUMBER(1, 0) DEFAULT 0 NOT NULL, ISP_NOTIFICATION NUMBER(1, 0) DEFAULT 0 NOT NULL, CONTRACT_END_DATE date, ROUTER_NUMBER VARCHAR2(50 BYTE), MEASURED_DOWNLOAD NUMBER(10, 0), DISABLE_OSAG_ISP_MONITORING NUMBER(1, 0) DEFAULT 0 NOT NULL, MEASURED_UPLOAD NUMBER(10, 0), ISP_LINK_STATUS_TYPE_ID NUMBER(10, 0), PING_IP_GROUP_ID NUMBER(10, 0), MAINTENANCE_STATUS_ID NUMBER(10, 0), USAGE_INTERFACE_ID NUMBER(10, 0), IPSEC_INTERNAL_FRAGMENTATION NUMBER(1, 0) DEFAULT 1 NOT NULL, ROUTER_IPV6_ADDRESS_ID NUMBER(10, 0), WAN_MANAGED_IGNORE_MISMATCH NUMBER(1, 0) DEFAULT 0 NOT NULL, WAN_MANAGED_IGNORE_REASON VARCHAR2(400 BYTE), ISP_LINK_SOURCING_TYPE_ID NUMBER(10, 0) NOT NULL, VARIABLE_BANDWIDTH NUMBER(1, 0) DEFAULT 0 NOT NULL, VARIABLE_BANDWIDTH_IDENTIFIER VARCHAR2(100 BYTE), VARIABLE_BANDWIDTH_DOWN NUMBER(10, 0), VARIABLE_BANDWIDTH_UP NUMBER(10, 0), VARIABLE_BANDWIDTH_QOS_DOWN NUMBER(10, 0), VARIABLE_BANDWIDTH_QOS_UP NUMBER(10, 0), LEAD_TIME_IN_WEEKS NUMBER(10, 0), LOCAL_LOOP VARCHAR2(200 BYTE), ISP_LINK_TRANSPORT_MEDIA_ID NUMBER(10, 0), SITE_ID VARCHAR2(256 BYTE), OSAM_ID VARCHAR2(256 BYTE), HANDOFF_PORT VARCHAR2(256 BYTE), CONSTRAINT ISPLINK_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.ISP_LINK.COMPANY_ID IS 'the ISP company (usually different from the host company)';
COMMENT ON COLUMN MSS.ISP_LINK.MC_CUSTOMER_ID IS 'The customer to which this isp link belongs to';
COMMENT ON COLUMN MSS.ISP_LINK.BANDWIDTH_DOWN IS 'provided downstream bandwidth [kbit/s]';
COMMENT ON COLUMN MSS.ISP_LINK.BANDWIDTH_UP IS 'provided upstream bandwidth [kbit/s]';
COMMENT ON COLUMN MSS.ISP_LINK.SLA_AVAILABILITY IS 'Service Level Agreement availability of this link [%](0-100)';
COMMENT ON COLUMN MSS.ISP_LINK.MTU IS 'Maximum Transmission Unit [Bytes], maximum size of packets which this link supports';
COMMENT ON COLUMN MSS.ISP_LINK.ROUTER_IP_ADDRESS1 IS 'IPv4 address of the router from the ISP';
COMMENT ON COLUMN MSS.ISP_LINK.ACCOUNT_MANAGER_ID IS 'if set, denotes the person that is responsible for this account/line';
COMMENT ON COLUMN MSS.ISP_LINK.SUPPORT_ID IS 'if set, denotes the (24h) support helpdesk of the ISP';
COMMENT ON COLUMN MSS.ISP_LINK.EVENT_TYPE_ID IS 'event type to generate when an ISP outage happens for this line';
COMMENT ON COLUMN MSS.ISP_LINK.PRODUCT_NAME IS 'how the ISP entitles this product';
COMMENT ON COLUMN MSS.ISP_LINK.CONTRACT_DURATION IS 'denotes the duration period of the contract [month]';
COMMENT ON COLUMN MSS.ISP_LINK.CANCELLATION_PERIOD IS 'denotes the cancellation period of the contract [month]';
COMMENT ON COLUMN MSS.ISP_LINK.LAST_REVIEW_DATE IS 'denotes the date of the last review/update of ISP contract data from this link
this is set automatically for new links, but manually for edited links';
COMMENT ON COLUMN MSS.ISP_LINK.MONITORING_MTTR IS 'if MONITORING is set this denotes the MTTR, mean time to repair/recover [minutes]';
COMMENT ON COLUMN MSS.ISP_LINK.CURRENCY_ID IS 'currency that applies to all fees for this isp link';
COMMENT ON COLUMN MSS.ISP_LINK.LINK_INSTALLATION_FEE IS 'local loop cost';
COMMENT ON COLUMN MSS.ISP_LINK.ISP_NOTIFICATION IS 'boolean: denotes if notifications are sent to the ISP when ''ISP outage'' events occur';
COMMENT ON COLUMN MSS.ISP_LINK.ROUTER_NUMBER IS 'Non-OSAG ID of the router used for this ISP link';
COMMENT ON COLUMN MSS.ISP_LINK.MEASURED_DOWNLOAD IS 'Sliding window average of download traffic on the link interface in kilobits per second';
COMMENT ON COLUMN MSS.ISP_LINK.DISABLE_OSAG_ISP_MONITORING IS 'Disable availability monitoring for this ISP link (affects OSAGlinkmon)';
COMMENT ON COLUMN MSS.ISP_LINK.MEASURED_UPLOAD IS 'Sliding window average of upload traffic on the link interface in kilobits per second';
COMMENT ON COLUMN MSS.ISP_LINK.ISP_LINK_STATUS_TYPE_ID IS 'Reference to the status type that describes current state of ISP link';
COMMENT ON COLUMN MSS.ISP_LINK.PING_IP_GROUP_ID IS 'Reference to the IP Group that will be used as ping targets for linkmon';
COMMENT ON COLUMN MSS.ISP_LINK.MAINTENANCE_STATUS_ID IS 'Maintenance status of the host (active, inactive, maintenance, unknown) as determined by according DB job';
COMMENT ON COLUMN MSS.ISP_LINK.USAGE_INTERFACE_ID IS 'Interface that has been used to compute the measurements for download and upload usage';
COMMENT ON COLUMN MSS.ISP_LINK.IPSEC_INTERNAL_FRAGMENTATION IS 'Internal fragmentation for IPSEC tunnels';
COMMENT ON COLUMN MSS.ISP_LINK.ROUTER_IPV6_ADDRESS_ID IS 'Reference to the IPv6 address of the ISP router';
COMMENT ON COLUMN MSS.ISP_LINK.WAN_MANAGED_IGNORE_MISMATCH IS 'Should we exclude this ISP line from the check against the service option?';
COMMENT ON COLUMN MSS.ISP_LINK.WAN_MANAGED_IGNORE_REASON IS 'Reason for excluding the line from the service option check (WAN_MANAGED_IGNORE_MISMATCH)';
COMMENT ON COLUMN MSS.ISP_LINK.ISP_LINK_SOURCING_TYPE_ID IS 'Denotes who is responsible for managing this ISP link';
COMMENT ON COLUMN MSS.ISP_LINK.VARIABLE_BANDWIDTH IS 'Is this ISP link enabled for variable bandwidth?';
COMMENT ON COLUMN MSS.ISP_LINK.VARIABLE_BANDWIDTH_IDENTIFIER IS 'Free-text ID that is used to map this link to the provider''s link ID';
COMMENT ON COLUMN MSS.ISP_LINK.VARIABLE_BANDWIDTH_DOWN IS 'Provided downstream bandwidth [kbit/s] of this variable bandwidth-enabled link';
COMMENT ON COLUMN MSS.ISP_LINK.VARIABLE_BANDWIDTH_UP IS 'Provided upstream bandwidth [kbit/s] of this variable bandwidth-enabled link';
COMMENT ON COLUMN MSS.ISP_LINK.VARIABLE_BANDWIDTH_QOS_DOWN IS 'Downstream QoS bandwidth [kbit/s] of this variable bandwidth-enabled link';
COMMENT ON COLUMN MSS.ISP_LINK.VARIABLE_BANDWIDTH_QOS_UP IS 'Upstream QoS bandwidth [kbit/s] of this variable bandwidth-enabled link';
COMMENT ON COLUMN MSS.ISP_LINK.SITE_ID IS 'Contains the Customer Site ID Registry + Location ID';
COMMENT ON COLUMN MSS.ISP_LINK.OSAM_ID IS 'Contains the Site ID, Location ID, first or second line and version of line offer';
COMMENT ON COLUMN MSS.ISP_LINK.HANDOFF_PORT IS 'Provided by the ISP, lists the ports that are still available to use';

CREATE TABLE NIDS.NIDS_EVENT (ID NUMBER(11, 0) NOT NULL, DB_DATE TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, LOG_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, SENSOR_HOST_ID NUMBER(11, 0) NOT NULL, SENDER_HOST_ID NUMBER(11, 0) NOT NULL, LOCAL_EVENT_ID NUMBER(11, 0) NOT NULL, TT_EVENT_ID NUMBER(11, 0), SIGNATURE_ID NUMBER(11, 0), DIRECTION_ID NUMBER(2, 0) NOT NULL, IP_SOURCE_ADDRESS NUMBER(11, 0), IP_SOURCE_PORT NUMBER(5, 0), IP_DESTINATION_ADDRESS NUMBER(11, 0), IP_DESTINATION_PORT NUMBER(5, 0), IP_PROTOCOL NUMBER(3, 0), SUPPRESSED NUMBER(11, 0) NOT NULL, CONSTRAINT NIDSEVENT_PK PRIMARY KEY (ID));
COMMENT ON TABLE NIDS.NIDS_EVENT IS 'Events reported by the NIDS correlator host to be escalated as
Tickets via the MC transport layer. These are the events that were found
positives by the "escalation rules". Note that most fields of this table
are not used directly by MC, since we mostly use the database on the host
itself (HostDB). It is currently used only to map between Ticket and NIDS
Event and vice versa (LOCAL_EVENT_ID, TT_EVENT_ID). The other fields are
here for future statistical analysis.';
COMMENT ON COLUMN NIDS.NIDS_EVENT.DB_DATE IS 'Timestamp when this event was entered in the database.';
COMMENT ON COLUMN NIDS.NIDS_EVENT.LOG_DATE IS 'Original timestamp of the event';
COMMENT ON COLUMN NIDS.NIDS_EVENT.SENSOR_HOST_ID IS 'Host-ID of the sensor that reported this event to the correlator.';
COMMENT ON COLUMN NIDS.NIDS_EVENT.SENDER_HOST_ID IS 'Host-ID of the NIDS correlator that sent this event via MC transport layer';
COMMENT ON COLUMN NIDS.NIDS_EVENT.LOCAL_EVENT_ID IS 'Event-ID in the Host-DB (database on the correlator)';
COMMENT ON COLUMN NIDS.NIDS_EVENT.SUPPRESSED IS 'Number of other events with same source and signature that were
not separately reported.';

CREATE TABLE NIDS.SIGNATURE (ID NUMBER(11, 0) NOT NULL, SID NUMBER(11, 0) NOT NULL, GID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE), SIGNATURE_CLASS_ID NUMBER(11, 0) NOT NULL, PRIORITY NUMBER(1, 0), REVISION NUMBER(6, 0), COMPANY_ID NUMBER(11, 0), PATTERN CLOB, CONSTRAINT SIGNATURE_PK PRIMARY KEY (ID));

CREATE TABLE TT.TICKET (ID NUMBER(22, 0) NOT NULL, TYPE_ID NUMBER(22, 0), STATUS_ID NUMBER(22, 0) DEFAULT 1, SUBJECT VARCHAR2(200 BYTE), HOST_ID NUMBER(22, 0), MSS_SERVICE_ID NUMBER(22, 0), COMPANY_ID NUMBER(22, 0), OPEN_DATE date DEFAULT SYSDATE, CLOSE_DATE date, LAST_RESOLVED_DATE date, LAST_STATUS_CHANGE_DATE date, STATUS_VALID_UNTIL_DATE date, CONTACT_ID NUMBER(22, 0), EVENT_NOTIFY_COUNT NUMBER(22, 0), EVENT_NOTIFY_COUNT_OSAG NUMBER(22, 0), PRIORITY NUMBER(22, 0) DEFAULT 1, WORKER_ID NUMBER(22, 0), CUSTOMER_REFERENCE VARCHAR2(64 BYTE), PARTNER_REFERENCE VARCHAR2(50 BYTE), SUMMARY_PRIVATE VARCHAR2(32767 BYTE), LAST_SUMMARY_UPDATE date, SUMMARY_PUBLIC VARCHAR2(32767 BYTE), EMERGENCY NUMBER(1, 0) DEFAULT 0 NOT NULL, ALWAYS_VISIBLE NUMBER(1, 0) DEFAULT 0 NOT NULL, HANDLED_BY_MCC NUMBER(1, 0) DEFAULT 1 NOT NULL, ESCALATION_STATUS_ID NUMBER(22, 0) DEFAULT 0 NOT NULL, LAST_ESCALATION_DATE date, CUSTOMER_TICKET_RATING_ID NUMBER(22, 0), ENGINEER_TICKET_RATING_ID NUMBER(22, 0), TYPE_CONFIRMED NUMBER(1, 0) DEFAULT 0 NOT NULL, SERVICE_CONFIRMED NUMBER(1, 0) DEFAULT 0 NOT NULL, FAST_RESOLVABLE NUMBER(1, 0) DEFAULT 0 NOT NULL, LAST_PUBLIC_EVENT_ID NUMBER(22, 0), RECOVERABLE_STATUS_ID NUMBER(22, 0), SUMMARY_RELEVANT_EVENTS_COUNT NUMBER(10, 0) DEFAULT 0 NOT NULL, LAST_DEFERRAL_DATE date, LAST_DEFERRAL_ESCALATED NUMBER(1, 0) DEFAULT 0 NOT NULL, UPDATE_TIMESTAMP TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSDATE NOT NULL, WAS_EMERGENCY NUMBER(1, 0) DEFAULT 0 NOT NULL, STEPS_TOTAL NUMBER(10, 0) DEFAULT 0 NOT NULL, STEPS_COMPLETED NUMBER(10, 0) DEFAULT 0 NOT NULL, TODO_RELEVANT_EVENTS_COUNT NUMBER(10, 0) DEFAULT 0 NOT NULL, UX_TIMEOUT TIMESTAMP(6) WITH TIME ZONE, UX_TIMEOUT_START TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSDATE NOT NULL, DELETED_HOST_ID NUMBER(22, 0), SERVICE_COMPONENT_ID NUMBER(10, 0), MERGED_INTO_TICKET_ID NUMBER(10, 0), LABEL_ID NUMBER(11, 0), CONTACT_ZITADEL_ID VARCHAR2(128 BYTE), WORKER_ZITADEL_ID VARCHAR2(128 BYTE), CONSTRAINT TICKET_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TT.TICKET.EVENT_NOTIFY_COUNT IS 'counts automatic events notified in this ticket (based on the event_notification table)';
COMMENT ON COLUMN TT.TICKET.EVENT_NOTIFY_COUNT_OSAG IS 'counts automatic events notified in this ticket for OSAG admins';
COMMENT ON COLUMN TT.TICKET.CUSTOMER_REFERENCE IS 'a string that is prefixed to all outgoing notifications';
COMMENT ON COLUMN TT.TICKET.PARTNER_REFERENCE IS 'used for partner tickets associated with this ticket';
COMMENT ON COLUMN TT.TICKET.EMERGENCY IS 'boolean: 1 means that this is an emergency ticket, 0 that it is not';
COMMENT ON COLUMN TT.TICKET.ALWAYS_VISIBLE IS 'boolean: 1 means that this ticket is shown on top of all customer pages, 0 that it is not';
COMMENT ON COLUMN TT.TICKET.HANDLED_BY_MCC IS 'boolean: 1 means that this ticket is processed by MCC';
COMMENT ON COLUMN TT.TICKET.ESCALATION_STATUS_ID IS 'escalation status of the ticket';
COMMENT ON COLUMN TT.TICKET.LAST_ESCALATION_DATE IS 'date of last escalation of the ticket';
COMMENT ON COLUMN TT.TICKET.CUSTOMER_TICKET_RATING_ID IS 'The newest customer rating regarding the ticket handling of this ticket';
COMMENT ON COLUMN TT.TICKET.ENGINEER_TICKET_RATING_ID IS 'The newest engineer rating regarding the ticket handling of this ticket';
COMMENT ON COLUMN TT.TICKET.TYPE_CONFIRMED IS 'Boolean: Whether the ticket type has been confirmed';
COMMENT ON COLUMN TT.TICKET.SERVICE_CONFIRMED IS 'Boolean: Whether the service has been confirmed';
COMMENT ON COLUMN TT.TICKET.FAST_RESOLVABLE IS 'Boolean: 1 means the ticket can be resolved without adding an event';
COMMENT ON COLUMN TT.TICKET.LAST_PUBLIC_EVENT_ID IS 'The ID of the last public event of this ticket (non-history, non-notification)';
COMMENT ON COLUMN TT.TICKET.RECOVERABLE_STATUS_ID IS 'The ID of the recoverable ticket status (if any)';
COMMENT ON COLUMN TT.TICKET.SUMMARY_RELEVANT_EVENTS_COUNT IS 'Counter for the number of events since the last summary update.';
COMMENT ON COLUMN TT.TICKET.LAST_DEFERRAL_DATE IS 'The date of the last deferral/waiting/third-party change (yes, reused).';
COMMENT ON COLUMN TT.TICKET.LAST_DEFERRAL_ESCALATED IS 'True means "escalate after deferral" was set when the ticket was deferred the last time.';
COMMENT ON COLUMN TT.TICKET.UPDATE_TIMESTAMP IS 'Tells when the row was last updated. This column is updated by the trigger tt.ticket_update_trg.';
COMMENT ON COLUMN TT.TICKET.WAS_EMERGENCY IS 'boolean: 1 means that this ticket had the emergency flag set at least once, 0 that it never was an emergency';
COMMENT ON COLUMN TT.TICKET.STEPS_TOTAL IS 'The total number of steps in the Todo List of this ticket.';
COMMENT ON COLUMN TT.TICKET.STEPS_COMPLETED IS 'The number of completed steps in the Todo List of this ticket.';
COMMENT ON COLUMN TT.TICKET.TODO_RELEVANT_EVENTS_COUNT IS 'Counter for the number of relevant events since the last todo list update.';
COMMENT ON COLUMN TT.TICKET.UX_TIMEOUT IS 'The timeout until which MC should update the ticket with an event.';
COMMENT ON COLUMN TT.TICKET.UX_TIMEOUT_START IS 'Defines the time from which the ux timeout should start.';
COMMENT ON COLUMN TT.TICKET.MERGED_INTO_TICKET_ID IS 'Specifies the ticket this ticket was merged into. Requires status to be set to merged (110)';

CREATE TABLE MC.MC_FILE (ID NUMBER(22, 0) NOT NULL, CREATED date DEFAULT SYSDATE, UPLOADER_ID NUMBER(22, 0) NOT NULL, DISPLAY_NAME VARCHAR2(100 BYTE) NOT NULL, DESCRIPTION VARCHAR2(256 BYTE) NOT NULL, FILE_CONTENTS BLOB DEFAULT EMPTY_BLOB(), FILENAME VARCHAR2(256 BYTE) NOT NULL, FILESIZE NUMBER(22, 0), MIME_TYPE VARCHAR2(256 BYTE) NOT NULL, MC_FILE_TYPE_ID NUMBER(22, 0) NOT NULL, CONSTRAINT MCFILE_PK PRIMARY KEY (ID));

CREATE TABLE TT.TICKET_REQUEST_CLASSIFICATION (ID NUMBER(11, 0) NOT NULL, TICKET_ID NUMBER(11, 0) NOT NULL, CLASSIFICATION NUMBER(2, 0) DEFAULT 0 NOT NULL, CONSTRAINT TICKETREQUESTCLASSIFICATION_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TT.TICKET_REQUEST_CLASSIFICATION.CLASSIFICATION IS 'The classification value: 1 = very precise, 2 = standard, 3 = imprecise';

CREATE TABLE MCAUDIT.COMPONENT (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, SHORT VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(500 BYTE), SYSTEM_ID NUMBER(10, 0) NOT NULL, CONSTRAINT COMPONENT_PK PRIMARY KEY (ID));

CREATE TABLE MCAUDIT.SYSTEM (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, SHORT VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(500 BYTE), CONSTRAINT SYSTEM_PK PRIMARY KEY (ID));

CREATE TABLE MC.CONNECTION_INTERRUPT_OPEN (ID NUMBER(22, 0) NOT NULL, HOST_ID NUMBER(10, 0) NOT NULL, TYPE_ID NUMBER(22, 0), DOWN_DATE date, UP_DATE date, MINUTES NUMBER(22, 0), ACTIVE NUMBER(1, 0) DEFAULT 1 NOT NULL, EVENT_ID NUMBER(22, 0), ISP_ESCALATED NUMBER(1, 0) DEFAULT 0 NOT NULL, DETAILS VARCHAR2(2000 BYTE), INTERRUPT_REVIEW_STATUS_ID NUMBER(10, 0), CONSTRAINT CONNECTIONINTERRUPTOPEN_PK PRIMARY KEY (ID));
COMMENT ON TABLE MC.CONNECTION_INTERRUPT_OPEN IS 'If there is some outage, ISP outage or connection down, there will be an entry in this table.
The entry is removed when the outage is over, and replaced when the type of the outage changes.
I.e. this table reflects the current connection status of a host.';

CREATE TABLE MC.CONNECTION_INTERRUPT_CLOSED (ID NUMBER(22, 0) NOT NULL, HOST_ID NUMBER(10, 0) NOT NULL, TYPE_ID NUMBER(22, 0), DOWN_DATE date, UP_DATE date, MINUTES NUMBER(22, 0), ACTIVE NUMBER(1, 0) DEFAULT 1 NOT NULL, EVENT_ID NUMBER(22, 0), DETAILS VARCHAR2(2000 BYTE), INTERRUPT_REVIEW_STATUS_ID NUMBER(10, 0), CONSTRAINT CONNECTIONINTERRUPTCLOSED_PK PRIMARY KEY (ID));

CREATE TABLE MSS.INTERFACE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(16 BYTE) NOT NULL, VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, HOST_ID NUMBER(10, 0) NOT NULL, IP_ADDRESS NUMBER(10, 0) DEFAULT 1, MGMTACCESS NUMBER(1, 0) DEFAULT 0 NOT NULL, MTU NUMBER(10, 0), EXTERNAL NUMBER(1, 0) DEFAULT 0 NOT NULL, NETWORK_ID NUMBER(10, 0) DEFAULT 1, QOS_BWIN NUMBER(10, 0), QOS_BWOUT NUMBER(10, 0), OSPF_AREA NUMBER(10, 0), OSPF_AUTHKEY VARCHAR2(1024 BYTE), OSPF_COST NUMBER(10, 0), OSPF_DONT_PROPAGATE_ROUTE NUMBER(1, 0) DEFAULT 0 NOT NULL, OSPF_HELLOINTERVAL NUMBER(10, 0) DEFAULT 10 NOT NULL, OSPF_DEADINTERVAL NUMBER(10, 0) DEFAULT 40 NOT NULL, INTERFACE_RIP_MODE_ID NUMBER(10, 0) DEFAULT 0 NOT NULL, INTERFACE_RIP_AUTHKEY VARCHAR2(64 BYTE), INTERFACE_SPEED_ID NUMBER(10, 0) DEFAULT 1 NOT NULL, ANTI_SPOOFING_IP_GROUP_ID NUMBER(10, 0), DISABLE_ANTI_SPOOFING_CHECKS NUMBER(1, 0) DEFAULT 0 NOT NULL, INHERIT_TOS NUMBER(1, 0) DEFAULT 1 NOT NULL, AUTHOR VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(256 BYTE) NOT NULL, COMMENTS VARCHAR2(1024 BYTE), OSPF6_AREA NUMBER(10, 0), OSPF6_COST NUMBER(10, 0), OSPF6_HELLOINTERVAL NUMBER(10, 0) DEFAULT 10 NOT NULL, OSPF6_DEADINTERVAL NUMBER(10, 0) DEFAULT 40 NOT NULL, INTERFACE_RIPNG_MODE_ID NUMBER(10, 0) DEFAULT 0 NOT NULL, DYNAMIC_IPV4 NUMBER(1, 0) DEFAULT 0 NOT NULL, HIDING_NAT NUMBER(1, 0) DEFAULT 0 NOT NULL, NAT_ADDRESS_ID NUMBER(10, 0), BANDWIDTH_CONTROL_PROFILE_ID NUMBER(10, 0), IS_CLUSTER_MANAGED NUMBER(1, 0) DEFAULT 0 NOT NULL, PATH_SELECTION_LINK_CLASS_ID NUMBER(10, 0), OSPF_P2MP NUMBER(1, 0) DEFAULT 0 NOT NULL, PATH_SELECTION_DISABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, PUBLIC_NAT_IP NUMBER(10, 0), OSPF_PRIORITY NUMBER(10, 0), OSPF_DIGESTKEY NUMBER(10, 0) DEFAULT 1, CONSTRAINT INTERFACE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.INTERFACE.EXTERNAL IS 'Flag that indicates whether this interface leads to an external or an internal address space';
COMMENT ON COLUMN MSS.INTERFACE.DISABLE_ANTI_SPOOFING_CHECKS IS 'Flag for disabling anti spoofing security/consistency checks and magic of external interfaces during chenerator rule generation.
               This flag is enabled in the ChE interface editor GUI.';
COMMENT ON COLUMN MSS.INTERFACE.INHERIT_TOS IS 'Flag that indicates whether DiffServ/TOS field is copied from GRE to IPSec packets on this interface';
COMMENT ON COLUMN MSS.INTERFACE.HIDING_NAT IS 'Should hiding NAT be done when traffic leaves through this interface?';
COMMENT ON COLUMN MSS.INTERFACE.PATH_SELECTION_LINK_CLASS_ID IS 'DEPRECATED: This column is deprecated as of 29.08.2025. Use table APPID.PATH_SELECTION_LINK_CLASS instead.';
COMMENT ON COLUMN MSS.INTERFACE.PUBLIC_NAT_IP IS 'Public IPv4 address under which this host is reachable from the Internet if it is placed behind a NAT box';
COMMENT ON COLUMN MSS.INTERFACE.OSPF_PRIORITY IS 'Set priority, relevant for DR election';
COMMENT ON COLUMN MSS.INTERFACE.OSPF_DIGESTKEY IS 'Set id of message digest key, relevant for OSPF authentication';

CREATE TABLE MSS.TIME_ZONE_DATA (ID NUMBER(10, 0) NOT NULL, SHORT VARCHAR2(512 BYTE) NOT NULL, NAME VARCHAR2(2000 BYTE), UTC_OFFSET_STD NUMBER(18, 0) NOT NULL, UTC_OFFSET_DST NUMBER(18, 0), DST_START_UTC TIMESTAMP(6) WITH TIME ZONE, DST_END_UTC TIMESTAMP(6) WITH TIME ZONE, LAST_MODIFIED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, CONSTRAINT TIMEZONEDATA_PK PRIMARY KEY (ID));

CREATE TABLE MSS.CONFIGURATION_GROUP (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(30 BYTE) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, DESCRIPTION VARCHAR2(200 BYTE) NOT NULL, CONSTRAINT CONFIGURATIONGROUP_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.NIDS_ENTITY_GROUP (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE), AUTOMATIC NUMBER(1, 0) DEFAULT 0 NOT NULL, COMMENTS VARCHAR2(1024 BYTE), COMPANY_ID NUMBER(11, 0), CONSTRAINT NIDSENTITYGROUP_PK PRIMARY KEY (ID));
COMMENT ON TABLE NIDS.NIDS_ENTITY_GROUP IS 'group of entity objects';
COMMENT ON COLUMN NIDS.NIDS_ENTITY_GROUP.AUTOMATIC IS 'The boolean property "automatic" defines whether this group has been automatically created or if it was created by a user.';

CREATE TABLE NIDS.NIDS_ENTITY (ID NUMBER(11, 0) NOT NULL, ENTITY_GROUP_ID NUMBER(11, 0) NOT NULL, MEMBER_ENTITY_GROUP_ID NUMBER(11, 0), NIDS_ENTITY_TYPE_ID NUMBER(11, 0) NOT NULL, IP_ADDRESS_ID NUMBER(11, 0), NETWORK_ID NUMBER(11, 0), IPV6_ADDRESS_ID NUMBER(11, 0), IPV6_PREFIX_ID NUMBER(11, 0), DEVICE_ID NUMBER(11, 0), USER_ID NUMBER(11, 0), FILE_ID NUMBER(11, 0), CONSTRAINT NIDSENTITY_PK PRIMARY KEY (ID));

CREATE TABLE FYI.MESSAGE_HISTORY (ID NUMBER(10, 0) NOT NULL, MESSAGE_ID VARCHAR2(128 BYTE) NOT NULL, NOTIFICATION_TYPE_ID NUMBER(10, 0) NOT NULL, NOTIFICATION_EVENT_ID NUMBER(10, 0) NOT NULL, SUBJECT VARCHAR2(128 BYTE), BODY VARCHAR2(32767 BYTE) NOT NULL, CONTACT_ID NUMBER(10, 0), RECIPIENT VARCHAR2(64 BYTE) NOT NULL, LAST_NAME VARCHAR2(64 BYTE), FIRST_NAME VARCHAR2(64 BYTE), SENT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT MESSAGEHISTORY_PK PRIMARY KEY (ID));

CREATE TABLE FYI.NOTIFICATION_EVENT (ID NUMBER(10, 0) NOT NULL, EVENT_TIME TIMESTAMP(6) WITH TIME ZONE NOT NULL, NOTIFY_TIME TIMESTAMP(6) WITH TIME ZONE NOT NULL, SENSOR_HOST_ID NUMBER(10, 0) NOT NULL, TOPIC_ID NUMBER(10, 0) NOT NULL, TARGET_ID NUMBER(10, 0) NOT NULL, TARGET_STATE VARCHAR2(64 BYTE), SUBJECT VARCHAR2(128 BYTE) NOT NULL, FORMATTED_TEXT VARCHAR2(32767 BYTE) NOT NULL, IS_PUBLIC NUMBER(1, 0) DEFAULT 0 NOT NULL, ADDITIONAL_DATA VARCHAR2(32767 BYTE), TICKET_ID NUMBER(10, 0), CONSTRAINT NOTIFICATIONEVENT_PK PRIMARY KEY (ID));

CREATE TABLE FYI.AFFECTED_HOST (NOTIFICATION_EVENT_ID NUMBER(10, 0) NOT NULL, HOST_ID NUMBER(10, 0) NOT NULL, CONSTRAINT AFFECTEDHOST_PK PRIMARY KEY (NOTIFICATION_EVENT_ID, HOST_ID));

CREATE TABLE FYI.LAST_SEEN (TOPIC_ID NUMBER(10, 0) NOT NULL, TARGET_ID NUMBER(10, 0) NOT NULL, LAST_SEEN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, ID NUMBER(10, 0) NOT NULL, IS_PUBLIC NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT LASTSEEN_PK PRIMARY KEY (ID));

CREATE TABLE FYI.TARGET (ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, HOST_ID NUMBER(10, 0), TARGET_NAME_ID NUMBER(10, 0), CONSTRAINT TARGET_PK PRIMARY KEY (ID));

CREATE TABLE REPORT.CHANNELVALUE (ID NUMBER(11, 0) NOT NULL, CHANNELKEY_ID NUMBER(11, 0) NOT NULL, TIMESTAMP date NOT NULL, VALUE VARCHAR2(2000 BYTE), CONSTRAINT CHANNELVALUE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN REPORT.CHANNELVALUE.ID IS 'Unique id for this value.';
COMMENT ON COLUMN REPORT.CHANNELVALUE.CHANNELKEY_ID IS 'foreign key to REPORT.CHANNELKEY.ID.';
COMMENT ON COLUMN REPORT.CHANNELVALUE.TIMESTAMP IS 'A timestamp in Oracle format that records when this value was entered.';
COMMENT ON COLUMN REPORT.CHANNELVALUE.VALUE IS 'The value recorded at TIMESTAMP for the tag referred to by CHANNELKEY_ID.';

CREATE TABLE REPORT.CHANNELKEY (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(30 BYTE) NOT NULL, EXECDAY NUMBER(11, 0), EXECHOUR NUMBER(11, 0), EXECMINUTE NUMBER(11, 0), EXECINTERVAL NUMBER(11, 0), HISTORYSIZE NUMBER(11, 0) NOT NULL, LASTUPDATED date, LAST_VALUE_ID NUMBER(11, 0), SQLQUERY VARCHAR2(2000 BYTE) NOT NULL, DESCRIPTION VARCHAR2(2000 BYTE), CONSTRAINT CHANNELKEY_PK PRIMARY KEY (ID));
COMMENT ON COLUMN REPORT.CHANNELKEY.NAME IS 'The name of this tag, that can be used as a parameter in "value name="tagname"';
COMMENT ON COLUMN REPORT.CHANNELKEY.EXECDAY IS 'The day of the week on which the query in SQLQUERY should be executed. If this value is set to NULL
        the query will be executed every day. Days of the week are numbered from 0 to 6.
        0 is Monday, 6 is Sunday. If either EXECMINUTE or EXECHOUR are set to NULL, EXECDAY will be ignored.';
COMMENT ON COLUMN REPORT.CHANNELKEY.EXECHOUR IS 'The hour at which the query in field SQLQUERY should be executed. If this value is set to NULL
        the query will be executed once every hour at the minute specified in the EXECMINUTE field.';
COMMENT ON COLUMN REPORT.CHANNELKEY.EXECMINUTE IS 'The minute at which the query in field SQLQUERY should be executed. If this value is set to NULL
        the query will be executed once every minute. If both values are NULL
        then EXECMINUTE takes precedence and the query shall be executed once per minute.';
COMMENT ON COLUMN REPORT.CHANNELKEY.EXECINTERVAL IS 'The execution interval in minutes. This value takes precedence over EXECMINUTE,
        EXECHOUR and EXECDAY if it is set. The query in SQLQUERY will be executed,
        if SYSDATE >= LASTUPDATED + EXECINTERVAL.';
COMMENT ON COLUMN REPORT.CHANNELKEY.HISTORYSIZE IS 'The number of history values that are kept for this tag.';
COMMENT ON COLUMN REPORT.CHANNELKEY.LASTUPDATED IS 'The last time this query has been executed.';
COMMENT ON COLUMN REPORT.CHANNELKEY.LAST_VALUE_ID IS 'The last value written for this key';
COMMENT ON COLUMN REPORT.CHANNELKEY.SQLQUERY IS 'The query that provides the value for this tag.';
COMMENT ON COLUMN REPORT.CHANNELKEY.DESCRIPTION IS 'A description of what the tag records.';

CREATE TABLE REPORT.HOST_COUNT (ID NUMBER(11, 0) NOT NULL, DATE_COUNTED TIMESTAMP(6) WITH TIME ZONE NOT NULL, HOSTCOUNT NUMBER(11, 0) NOT NULL, CONSTRAINT HOSTCOUNT_PK PRIMARY KEY (ID));
COMMENT ON TABLE REPORT.HOST_COUNT IS 'Table to hold monthly host counts (active hosts). "Temporary" solution until this is fixed in influx.';
COMMENT ON COLUMN REPORT.HOST_COUNT.ID IS 'Unique id for a host count.';
COMMENT ON COLUMN REPORT.HOST_COUNT.DATE_COUNTED IS 'Date on which the count was recorded';
COMMENT ON COLUMN REPORT.HOST_COUNT.HOSTCOUNT IS 'The actual host count';

CREATE TABLE AUTH.CONSENTED_TERM (ID NUMBER(11, 0) NOT NULL, CONSENTED_TERM_TYPE_ID NUMBER(11, 0) NOT NULL, LOGIN_ID NUMBER(11, 0) NOT NULL, LAST_CONSENT_DATE date NOT NULL, CONSTRAINT CONSENTEDTERM_PK PRIMARY KEY (ID));

CREATE TABLE MSS.NEWS_ENTRY_2_LOGIN (ID NUMBER(10, 0) NOT NULL, NEWS_ENTRY_ID NUMBER(10, 0) NOT NULL, LOGIN_ID NUMBER(10, 0) NOT NULL, NEWS_ENTRY_2_LOGIN_TYPE_ID NUMBER(10, 0) NOT NULL, TIME TIMESTAMP(6) WITH TIME ZONE, CONSTRAINT NEWSENTRY2LOGIN_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.USER_SERVICE_TYPE_SCOPE (ID NUMBER(11, 0) NOT NULL, SERVICE_TYPE_ID NUMBER(11, 0) NOT NULL, PERMISSION_ID NUMBER(11, 0) NOT NULL, SDP_ACCESS NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT USERSERVICETYPESCOPE_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.JUMPHOST (DB_HOST VARCHAR2(64 BYTE) NOT NULL, JUMP_HOST VARCHAR2(64 BYTE) NOT NULL);

CREATE TABLE ESP.SPECIAL_DAY (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, LEGAL_HOLIDAY NUMBER(1, 0) NOT NULL, DAY_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT "BIN$3T5JGNrJavTgU1junNVNtQ==$0" PRIMARY KEY (ID));
COMMENT ON TABLE ESP.SPECIAL_DAY IS 'Defines days where a certain day template should be used instead of the default day template of that day.
        A common example are legal holidays or rollout days with additional engineers in MC.';
COMMENT ON COLUMN ESP.SPECIAL_DAY.NAME IS 'Name of the special day - this is displayed in the schedule.';
COMMENT ON COLUMN ESP.SPECIAL_DAY.LEGAL_HOLIDAY IS 'Whether this is a legal holiday (influences off-hour surcharge calculation).';
COMMENT ON COLUMN ESP.SPECIAL_DAY.DAY_DATE IS 'The date of this special day (only the date part matters).';

CREATE TABLE FW.CONFIG_LOCK (ID NUMBER(10, 0) NOT NULL, CONTACT_ID NUMBER(10, 0) NOT NULL, LOCKED_SINCE TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSDATE NOT NULL, LAST_ACTION TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSDATE NOT NULL, CHANGES NUMBER(10, 0) NOT NULL, POLICY_ID NUMBER(10, 0), CONSTRAINT CONFIGLOCK_PK PRIMARY KEY (ID));

CREATE TABLE STOP.COMPANY_TAM (ID NUMBER(11, 0) NOT NULL, PRIORITY NUMBER(6, 0) NOT NULL, COMPANY_ID NUMBER(11, 0) NOT NULL, CONTACT_ID NUMBER(11, 0) NOT NULL, CONSTRAINT COMPANYTAM_PK PRIMARY KEY (ID));

CREATE TABLE STOP.COMPANY_AM (ID NUMBER(11, 0) NOT NULL, PRIORITY NUMBER(6, 0) NOT NULL, COMPANY_ID NUMBER(11, 0) NOT NULL, CONTACT_ID NUMBER(11, 0) NOT NULL, CONSTRAINT COMPANYAM_PK PRIMARY KEY (ID));

CREATE TABLE GUMA2.PATTERN (ID NUMBER(10, 0) NOT NULL, APPLICATION_TYPE_ID NUMBER(10, 0) NOT NULL, POSITION NUMBER(10, 0) NOT NULL, REGEXP VARCHAR2(256 BYTE) NOT NULL, IGNORE_CASE NUMBER(1, 0) DEFAULT 0 NOT NULL, NEGATE NUMBER(1, 0) DEFAULT 0 NOT NULL, AUTHOR VARCHAR2(64 BYTE) NOT NULL, SIGNATURE_ID NUMBER(10, 0) NOT NULL, SYSLOG_FACILITY_ID NUMBER(10, 0) NOT NULL, SYSLOG_SEVERITY_ID NUMBER(10, 0) NOT NULL, COMMENTS VARCHAR2(1024 BYTE), LAST_UPDATED date NOT NULL, CONSTRAINT PATTERN_PK PRIMARY KEY (ID));

CREATE TABLE GUMA2.SIGNATURE (ID NUMBER(10, 0) NOT NULL, SHORT_NAME VARCHAR2(64 BYTE) NOT NULL, ACTION VARCHAR2(1 BYTE) NOT NULL, AGGREGATE NUMBER(3, 0) DEFAULT 999 NOT NULL, AUTHOR VARCHAR2(64 BYTE) NOT NULL, CMD_TRIGGER VARCHAR2(256 BYTE), EVENT_TYPE_ID NUMBER(10, 0), TICKET_TYPE_ID NUMBER(10, 0), UNSTABLE NUMBER(1, 0) DEFAULT 0 NOT NULL, NOQUARANTINE NUMBER(1, 0) DEFAULT 0 NOT NULL, DESCRIPTION VARCHAR2(2048 BYTE) NOT NULL, DESCRIPTION_PRIV VARCHAR2(2048 BYTE), COMMENTS VARCHAR2(1024 BYTE), SERVICE_COMPONENT_ID NUMBER(10, 0), LAST_TIME_SEEN TIMESTAMP(6) WITH TIME ZONE, MIGRATED NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT SIGNATURE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN GUMA2.SIGNATURE.UNSTABLE IS 'Flag that indicates whether these events are normal for hosts with mss.host.unstable=1 (e.g. ''SYSTEM:BOOT:UNEXPECTED'')';
COMMENT ON COLUMN GUMA2.SIGNATURE.NOQUARANTINE IS 'Flag that indicates whether these events are excluded from our GUMA event quarantine. (e.g. "1" => never quarantine that signature)';
COMMENT ON COLUMN GUMA2.SIGNATURE.MIGRATED IS 'end of 2023 guma migration to loki pipeline; disables guma pipeline when set to 1';

CREATE TABLE GUMA2.SUPPRESSED_SIGNATURE (ID NUMBER(10, 0) NOT NULL, HOST_ID NUMBER(10, 0) NOT NULL, SIGNATURE_ID NUMBER(10, 0) NOT NULL, DATE_START TIMESTAMP(6) WITH TIME ZONE NOT NULL, DATE_END TIMESTAMP(6) WITH TIME ZONE NOT NULL, TICKET_ID NUMBER(11, 0), CONSTRAINT SUPPRESSEDSIGNATURE_PK PRIMARY KEY (ID));
COMMENT ON TABLE GUMA2.SUPPRESSED_SIGNATURE IS 'Events matching this signature, host and date, will be suppressed by gumaserver';

CREATE TABLE MSS.INTERFACE2ISP_LINK (INTERFACE_ID NUMBER(10, 0) NOT NULL, ISP_LINK_ID NUMBER(10, 0) NOT NULL, CONSTRAINT INTERFACE2ISPLINK_PK PRIMARY KEY (INTERFACE_ID, ISP_LINK_ID));

CREATE TABLE MSS.OBJECT_TYPE (ID NUMBER(10, 0) NOT NULL, TABLE_NAME VARCHAR2(64 BYTE) NOT NULL, JAVA_CLASS_NAME VARCHAR2(512 BYTE) NOT NULL, CONSTRAINT OBJECTTYPE_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.OBJECT_TYPE IS 'stores the relation of table names and java class names (filled/maintained by the mapping2table script. IDs are guaranteed to stay the same
for existing object types.)';
COMMENT ON COLUMN MSS.OBJECT_TYPE.TABLE_NAME IS 'canonical name of the table which stores objects of type java_class_name (schema.table)';
COMMENT ON COLUMN MSS.OBJECT_TYPE.JAVA_CLASS_NAME IS 'canonical java class name of objects stored in the table table_name (package.classname)';

CREATE TABLE TT.CUST_MAINTENANCE_WINDOW (ID NUMBER(22, 0) NOT NULL, SERVICE_WINDOW_ID NUMBER(22, 0) NOT NULL, DISABLE_EVENTS NUMBER(1, 0) DEFAULT 0 NOT NULL, COLLECT_EVENTS NUMBER(1, 0) DEFAULT 0 NOT NULL, DISABLE_GUMA_ESCALATION NUMBER(1, 0) DEFAULT 0 NOT NULL, DISABLE_CONN_ESCALATION NUMBER(1, 0) DEFAULT 0 NOT NULL, DISABLE_NOTIFICATION NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT CUSTMAINTENANCEWINDOW_PK PRIMARY KEY (ID));
COMMENT ON TABLE TT.CUST_MAINTENANCE_WINDOW IS 'A service window extension for type customer maintenance window.';
COMMENT ON COLUMN TT.CUST_MAINTENANCE_WINDOW.DISABLE_EVENTS IS 'If set to 1 all events that belong to this node (and the ticket''s company) and not explicitly added to a ticket (tt.event_interface.addevent())
          but with tt.event_interface.newevent() will be dropped. This causes no escalation actions or notifications to be processed for
          those events during the service window period. Of course the upcoming event must provide a host (service id), otherwise it is not possible
          to determine, if there is a service window. This function is implemented in tt.event_interface.newevent().';
COMMENT ON COLUMN TT.CUST_MAINTENANCE_WINDOW.COLLECT_EVENTS IS 'If set to 1 all upcoming events not explicitly added to another ticket will get collected into this ticket until the end of the
          service window if it belongs to this host (service id) and this company. Any event that is not dropped (either because
          the specified service is not active or a service window requests event dropping (see above) for this service) will be
          collected into that  ticket with the highest id specifying a matching service window. This functionality is also implemented
          in tt.event_interface.newticket().';
COMMENT ON COLUMN TT.CUST_MAINTENANCE_WINDOW.DISABLE_GUMA_ESCALATION IS 'If set to 1 any escalation to mcc, the customer and the isp caused by GUMA events is turned off during the service
          window. Only for these GUMA events escalation is suppressed: id alert, hardware error, application failure, system failure.
          If an escalation is to be suppressed is determined in event_interface.exec_event_type_actions() by calling the function tt.event_interface.is_esc_supp_active().
          The following conditions must be met for an escalation to be suppressed:
          (1) for the host (service_id the event belongs to a currently open service window must exist, which has the disable_conn_escalation flag set to 1
          (2) the tt.event_type.id must be one out of these 10002 (id alert), 10005 (hardware error), 10007 (application failure) or 10009 (system failure)
          When the escalation is to be suppressed, no action will be carried out by tt.event_interface.exec_event_type_actions().';
COMMENT ON COLUMN TT.CUST_MAINTENANCE_WINDOW.DISABLE_CONN_ESCALATION IS 'If set to 1 any escalation to mcc, the customer and the isp caused by connection down (TT.EVENT_ACTION.ID is 2) is turned off during the service window.
          If an escalation is to be suppressed is determined in event_interface.exec_event_type_actions() by calling the function tt.event_interface.is_esc_supp_active().
          The following conditions must be met for an escalation to be suppressed:
          (1) for the host (service_id the event belongs to a currently open service window must exist, which has the disable_conn_escalation flag set to 1
          (2) the tt.event_action.id must be either 2 (connection down escalation)
          When the escalation is to be suppressed, no action will be carried out by tt.event_interface.exec_event_type_actions().';
COMMENT ON COLUMN TT.CUST_MAINTENANCE_WINDOW.DISABLE_NOTIFICATION IS 'If set to 1 notification for any added event to this ticket is turned off during the service window.
          However the notification ticket bound events (resolved, manual event added and waiting) and test notifications
          will not be affected.
          Implementation is in tt.osag_notify.is_notify_suppressor_active() which checks if there is a service window open for the ticket that has
          the disable_notification flag set to 1. If so the procedure notify.event_notify() leaves out any registered notifications for this event tpye.
          It does handle the ticket specific notifications anyway.';

CREATE TABLE TT.MAINTENANCE_WINDOW (ID NUMBER(22, 0) NOT NULL, SERVICE_WINDOW_ID NUMBER(22, 0) NOT NULL, DISABLE_EVENTS NUMBER(1, 0) DEFAULT 0 NOT NULL, COLLECT_EVENTS NUMBER(1, 0) DEFAULT 0 NOT NULL, DISABLE_GUMA_ESCALATION NUMBER(1, 0) DEFAULT 0 NOT NULL, DISABLE_CONN_ESCALATION NUMBER(1, 0) DEFAULT 0 NOT NULL, DISABLE_NOTIFICATION NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT MAINTENANCEWINDOW_PK PRIMARY KEY (ID));
COMMENT ON TABLE TT.MAINTENANCE_WINDOW IS 'A service window extension for type maintenance window.';
COMMENT ON COLUMN TT.MAINTENANCE_WINDOW.DISABLE_EVENTS IS 'If set to 1 all events that belong to this node (and the ticket''s company) and not explicitly added to a ticket (tt.event_interface.addevent())
          but with tt.event_interface.newevent() will be dropped. This causes no escalation actions or notifications to be processed for
          those events during the service window period. Of course the upcoming event must provide a host (service id), otherwise it is not possible
          to determine, if there is a service window. This function is implemented in tt.event_interface.newevent().';
COMMENT ON COLUMN TT.MAINTENANCE_WINDOW.COLLECT_EVENTS IS 'If set to 1 all upcoming events not explicitly added to another ticket will get collected into this ticket until the end of the
          service window if it belongs to this host (service id) and this company. Any event that is not dropped (either because
          the specified service is not active or a service window requests event dropping (see above) for this service) will be
          collected into that  ticket with the highest id specifying a matching service window. This functionality is also implemented
          in tt.event_interface.newticket().';
COMMENT ON COLUMN TT.MAINTENANCE_WINDOW.DISABLE_GUMA_ESCALATION IS 'If set to 1 any escalation to mcc, the customer and the isp caused by GUMA events is turned off during the service
          window. Only for these GUMA events escalation is suppressed: id alert, hardware error, application failure, system failure.
          If an escalation is to be suppressed is determined in event_interface.exec_event_type_actions() by calling the function tt.event_interface.is_esc_supp_active().
          The following conditions must be met for an escalation to be suppressed:
          (1) for the host (service_id the event belongs to a currently open service window must exist, which has the disable_conn_escalation flag set to 1
          (2) the tt.event_type.id must be one out of these 10002 (id alert), 10005 (hardware error), 10007 (application failure) or 10009 (system failure)
          When the escalation is to be suppressed, no action will be carried out by tt.event_interface.exec_event_type_actions().';
COMMENT ON COLUMN TT.MAINTENANCE_WINDOW.DISABLE_CONN_ESCALATION IS 'If set to 1 any escalation to mcc, the customer and the isp caused by connection down (TT.EVENT_ACTION.ID is 2) is turned off during the service window.
          If an escalation is to be suppressed is determined in event_interface.exec_event_type_actions() by calling the function tt.event_interface.is_esc_supp_active().
          The following conditions must be met for an escalation to be suppressed:
          (1) for the host (service_id the event belongs to a currently open service window must exist, which has the disable_conn_escalation flag set to 1
          (2) the tt.event_action.id must be either 2 (connection down escalation)
          When the escalation is to be suppressed, no action will be carried out by tt.event_interface.exec_event_type_actions().';
COMMENT ON COLUMN TT.MAINTENANCE_WINDOW.DISABLE_NOTIFICATION IS 'If set to 1 notification for any added event to this ticket is turned off during the service window.
          However the notification ticket bound events (resolved, manual event added and waiting) and test notifications
          will not be affected.
          Implementation is in tt.osag_notify.is_notify_suppressor_active() which checks if there is a service window open for the ticket that has
          the disable_notification flag set to 1. If so the procedure notify.event_notify() leaves out any registered notifications for this event tpye.
          It does handle the ticket specific notifications anyway.';

CREATE TABLE TT.HOST2SERVICE_WINDOW (HOST_ID NUMBER(10, 0) NOT NULL, SERVICE_WINDOW_ID NUMBER(10, 0) NOT NULL, CONSTRAINT HOST2SERVICEWINDOW_PK PRIMARY KEY (HOST_ID, SERVICE_WINDOW_ID));

CREATE TABLE TT.SERVICE_WINDOW (ID NUMBER(22, 0) NOT NULL, TICKET_ID NUMBER(22, 0) NOT NULL, START_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, END_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, TITLE VARCHAR2(200 BYTE), DESCRIPTION CLOB, COMPANY_ID NUMBER(22, 0) NOT NULL, CONSTRAINT SERVICEWINDOW_PK PRIMARY KEY (ID));
COMMENT ON TABLE TT.SERVICE_WINDOW IS 'A service window for a ticket. A ticket can only have one service window.';
COMMENT ON COLUMN TT.SERVICE_WINDOW.START_DATE IS 'The date when the service window begins in UTC (as a convention all dates should be stored in UTC).';
COMMENT ON COLUMN TT.SERVICE_WINDOW.END_DATE IS 'The date when the service window ends in UTC (as a convention all dates should be stored in UTC).';

CREATE TABLE MC.HOST_CONNECTION_STATUS (HOST_ID NUMBER(10, 0) NOT NULL, CON_TIMESTAMP NUMBER(10, 0) NOT NULL, DETAILS VARCHAR2(2024 BYTE), CON_INT_TYPE_ID NUMBER(10, 0), CONSTRAINT HOSTCONNECTIONSTATUS_PK PRIMARY KEY (HOST_ID));

CREATE TABLE MC.HOST_MAINTENANCE_HISTORY (ID NUMBER(10, 0) NOT NULL, HOST_ID NUMBER(10, 0) NOT NULL, CHANGE_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, NEW_MAINTENANCE_STATUS_ID NUMBER(10, 0) NOT NULL, OLD_MAINTENANCE_STATUS_ID NUMBER(10, 0) NOT NULL, TICKET_ID NUMBER(10, 0), CONSTRAINT HOSTMAINTENANCEHISTORY_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MC.HOST_MAINTENANCE_HISTORY.TICKET_ID IS 'Ticket of the service window, in case new status is maintenance';

CREATE TABLE MC.ISP_LINK_MAINTENANCE_HISTORY (ID NUMBER(10, 0) NOT NULL, ISP_LINK_ID NUMBER(10, 0) NOT NULL, CHANGE_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, NEW_MAINTENANCE_STATUS_ID NUMBER(10, 0) NOT NULL, OLD_MAINTENANCE_STATUS_ID NUMBER(10, 0) NOT NULL, TICKET_ID NUMBER(10, 0), CONSTRAINT ISPLINKMAINTENANCEHISTORY_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MC.ISP_LINK_MAINTENANCE_HISTORY.TICKET_ID IS 'Ticket of the service window, in case new status is maintenance';

CREATE TABLE MC.MAINTENANCE_STATUS (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(25 BYTE), DESCRIPTION VARCHAR2(200 BYTE), CONSTRAINT MAINTENANCESTATUS_PK PRIMARY KEY (ID));
COMMENT ON TABLE MC.MAINTENANCE_STATUS IS 'Describes the maintenance status of an entity (host, isp_link)';

CREATE TABLE MSS.VALUE (ID NUMBER(10, 0) NOT NULL, KEY_ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0), VPN_ID NUMBER(10, 0), HOST_ID NUMBER(10, 0), COMPANY_ID NUMBER(10, 0), STRING_VALUE VARCHAR2(4000 BYTE), COMMENTS VARCHAR2(4000 BYTE), CONFIGURATION_GROUP_ID NUMBER(10, 0), CONSTRAINT VALUE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.KEY (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, KEY_TYPE_ID NUMBER(10, 0) NOT NULL, STRING_DEFAULT VARCHAR2(2000 BYTE), FILE_DEFAULT BLOB, REGEXP VARCHAR2(2000 BYTE), SERVICE_OPTION_TYPE_ID NUMBER(10, 0), OPERATING_SYSTEM_ID NUMBER(10, 0), DESCRIPTION VARCHAR2(2000 BYTE), CONSTRAINT KEY_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.KEY.FILE_DEFAULT IS 'Deprecated: always NULL now';

CREATE TABLE MSS.SOFTWARE_RELEASE (ID NUMBER(10, 0) NOT NULL, MAJOR_SOFTWARE_RELEASE_ID NUMBER(10, 0), RELEASE_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, RELEASE_NOTES VARCHAR2(32767 BYTE) NOT NULL, RELEASE_NUMBER VARCHAR2(32 BYTE) NOT NULL, RELEASE_CARTRIDGE VARCHAR2(32 BYTE) NOT NULL, SECURITY_UPDATE NUMBER(1, 0) DEFAULT 0 NOT NULL, PERFORMANCE_UPDATE NUMBER(1, 0) DEFAULT 0 NOT NULL, FEATURE_UPDATE NUMBER(1, 0) DEFAULT 0 NOT NULL, PUBLISHED NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT SOFTWARERELEASE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.SOFTWARE_RELEASE.MAJOR_SOFTWARE_RELEASE_ID IS 'Reference to major release, null means it''s a major release.';
COMMENT ON COLUMN MSS.SOFTWARE_RELEASE.RELEASE_DATE IS 'Availability date';
COMMENT ON COLUMN MSS.SOFTWARE_RELEASE.RELEASE_NUMBER IS 'Major release number of this release.';
COMMENT ON COLUMN MSS.SOFTWARE_RELEASE.RELEASE_CARTRIDGE IS 'Minor release number of this release.';
COMMENT ON COLUMN MSS.SOFTWARE_RELEASE.SECURITY_UPDATE IS 'Does this release contain security updates?';
COMMENT ON COLUMN MSS.SOFTWARE_RELEASE.PERFORMANCE_UPDATE IS 'Does this release contain performance updates';
COMMENT ON COLUMN MSS.SOFTWARE_RELEASE.FEATURE_UPDATE IS 'Does this release contain feature updates?';
COMMENT ON COLUMN MSS.SOFTWARE_RELEASE.PUBLISHED IS 'Only published software releases are visible in the MC portal.';

CREATE TABLE MSS.RELEASE_INSTALLATION (ID NUMBER(10, 0) NOT NULL, SOFTWARE_RELEASE_ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, INSTALL_START_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, INSTALL_COMPLETE_DATE TIMESTAMP(6) WITH TIME ZONE, INSTALL_END_DATE TIMESTAMP(6) WITH TIME ZONE, INSTALL_COUNT NUMBER(10, 0) NOT NULL, CONSTRAINT RELEASEINSTALLATION_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.RELEASE_INSTALLATION.SOFTWARE_RELEASE_ID IS 'Reference to the release this entry is related.';
COMMENT ON COLUMN MSS.RELEASE_INSTALLATION.COMPANY_ID IS 'Reference to the customer this affects.';
COMMENT ON COLUMN MSS.RELEASE_INSTALLATION.INSTALL_START_DATE IS 'Date of the update of the first host.';
COMMENT ON COLUMN MSS.RELEASE_INSTALLATION.INSTALL_COMPLETE_DATE IS 'Set when the installation ratio reaches 95%. The install ratio is computed from the heartbeats from OSIX LX hosts of this company as follows:
          (number of heartbeats reporting the current version)/(number of heartbeats). Only updated iff null.';
COMMENT ON COLUMN MSS.RELEASE_INSTALLATION.INSTALL_END_DATE IS 'Date when the INSTALL_COUNT dropped to 0, only updated iff null.';
COMMENT ON COLUMN MSS.RELEASE_INSTALLATION.INSTALL_COUNT IS 'Number of hosts that have the release installed, only updated iff INSTALL_END_DATE is null.';

CREATE TABLE STOP.COMP_COMPTYPE_REF (COMPANY_ID NUMBER(22, 0) NOT NULL, COMPTYPE_ID NUMBER(22, 0) NOT NULL, CONSTRAINT COMPCOMPTYPEREF_PK PRIMARY KEY (COMPANY_ID, COMPTYPE_ID));

CREATE TABLE NIDS.SIGNATURE_CLASS (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, CONSTRAINT SIGNATURECLASS_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.DIRECTION (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, CONSTRAINT DIRECTION_PK PRIMARY KEY (ID));

CREATE TABLE TT.EVENT_TYPE (ID NUMBER(22, 0) NOT NULL, NAME VARCHAR2(40 BYTE) NOT NULL, SOURCE NUMBER(22, 0) NOT NULL, IS_NOTIFIED NUMBER(1, 0) DEFAULT 0 NOT NULL, ESCALATION NUMBER(1, 0) DEFAULT 0 NOT NULL, DESCRIPTION VARCHAR2(1000 BYTE), SMS_MESSAGE_TEMPLATE_ID NUMBER(22, 0) NOT NULL, EMAIL_MESSAGE_TEMPLATE_ID NUMBER(22, 0) NOT NULL, PINNABLE NUMBER(1, 0) DEFAULT 0 NOT NULL, AUTOPIN NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT EVENTTYPE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TT.EVENT_TYPE.IS_NOTIFIED IS 'If set to 1, MC users can subscribe to event notifications for the specific event type.';
COMMENT ON COLUMN TT.EVENT_TYPE.SMS_MESSAGE_TEMPLATE_ID IS 'Specifies which event type message template is used if a SMS notification is sent for an event of this event type.';
COMMENT ON COLUMN TT.EVENT_TYPE.EMAIL_MESSAGE_TEMPLATE_ID IS 'Specifies which event type message template is used if an email notification is sent for an event of this event type.';
COMMENT ON COLUMN TT.EVENT_TYPE.PINNABLE IS 'Whether events of this type can be pinned or not.';
COMMENT ON COLUMN TT.EVENT_TYPE.AUTOPIN IS 'Whether event will be pinned when created or not';

CREATE TABLE OSAG.PLSQL_AUDIT (OWNER VARCHAR2(128 BYTE), OBJECT_TYPE VARCHAR2(13 BYTE), OBJECT_NAME VARCHAR2(128 BYTE), PROCEDURE_NAME VARCHAR2(128 BYTE), LAST_USED TIMESTAMP(6));

CREATE TABLE TT.CHANGE_REQUEST (ID NUMBER(11, 0) NOT NULL, CHANGE_REQUEST_STATE_ID NUMBER(11, 0) NOT NULL, DESCRIPTION CLOB NOT NULL, PRIVATE_DESCRIPTION CLOB, REQUESTER_ID NUMBER(11, 0), APPROVER_ID NUMBER(11, 0), CREATION_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, LAST_REQUEST_DATE TIMESTAMP(6) WITH TIME ZONE, LAST_ONHOLD_DATE TIMESTAMP(6) WITH TIME ZONE, APPROVAL_DENIAL_DATE TIMESTAMP(6) WITH TIME ZONE, COMPLETION_DATE TIMESTAMP(6) WITH TIME ZONE, TICKET_ID NUMBER(11, 0) NOT NULL, OTHER_REQUESTER CLOB, REQUESTER_ZITADEL_ID VARCHAR2(128 BYTE), APPROVER_ZITADEL_ID VARCHAR2(128 BYTE), CONSTRAINT CHANGEREQUEST_PK PRIMARY KEY (ID));
COMMENT ON TABLE TT.CHANGE_REQUEST IS 'A change request inside a change ticket.';
COMMENT ON COLUMN TT.CHANGE_REQUEST.DESCRIPTION IS 'Publicly visible description text for the change request';
COMMENT ON COLUMN TT.CHANGE_REQUEST.PRIVATE_DESCRIPTION IS 'Private description text for the change request';
COMMENT ON COLUMN TT.CHANGE_REQUEST.REQUESTER_ID IS 'The contact that requested the change';
COMMENT ON COLUMN TT.CHANGE_REQUEST.APPROVER_ID IS 'The contact that approved or rejected the request (depending on the current state)';
COMMENT ON COLUMN TT.CHANGE_REQUEST.CREATION_DATE IS 'The date and time when the change request has been created';
COMMENT ON COLUMN TT.CHANGE_REQUEST.LAST_REQUEST_DATE IS 'The date and time when the change request has been put into state ''requested'' for the last time';
COMMENT ON COLUMN TT.CHANGE_REQUEST.LAST_ONHOLD_DATE IS 'The date and time when the change request has been put into state ''on hold'' for the last time';
COMMENT ON COLUMN TT.CHANGE_REQUEST.APPROVAL_DENIAL_DATE IS 'The date and time when the change request has been put into state ''approved'' or ''rejected'' for the last time';
COMMENT ON COLUMN TT.CHANGE_REQUEST.COMPLETION_DATE IS 'The date and time when the change request has been put into state ''implemented'', ''denied'' or ''abandoned'' for the last time';
COMMENT ON COLUMN TT.CHANGE_REQUEST.TICKET_ID IS 'Reference to the related ticket';
COMMENT ON COLUMN TT.CHANGE_REQUEST.OTHER_REQUESTER IS 'Free-form text field in case the requester is not a contact.';

CREATE TABLE TT.EVENT_TYPE_ACTION (EVENT_ACTION_ID NUMBER(22, 0) NOT NULL, EVENT_TYPE_ID NUMBER(22, 0) NOT NULL, CONSTRAINT EVENTTYPEACTION_PK PRIMARY KEY (EVENT_ACTION_ID, EVENT_TYPE_ID));

CREATE TABLE TT.EVENT_ACTION (ID NUMBER(22, 0) NOT NULL, NAME VARCHAR2(50 BYTE) NOT NULL, PROCEDURE_NAME VARCHAR2(100 BYTE), PROCEDURE_KEY_ID NUMBER(10, 0), CONSTRAINT EVENTACTION_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TT.EVENT_ACTION.PROCEDURE_NAME IS 'plsql procedure that is called
(if PROCEDURE_KEY_ID is defined and a corresponding VALUE is found for the host on
which the event occured, that value is used as the procedure name instead)';
COMMENT ON COLUMN TT.EVENT_ACTION.PROCEDURE_KEY_ID IS 'db property that specifies which procedure should be called, see also PROCEDURE_NAME';

CREATE TABLE TT.EVENT_NOTIFICATION_TYPE (ID NUMBER(22, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, CONSTRAINT EVENTNOTIFICATIONTYPE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TT.EVENT_NOTIFICATION_TYPE.ID IS 'Event Notification Type ID';
COMMENT ON COLUMN TT.EVENT_NOTIFICATION_TYPE.NAME IS 'Name of notification type.';

CREATE TABLE TT.TICKET_TYPE (ID NUMBER(22, 0) NOT NULL, NAME VARCHAR2(40 BYTE) NOT NULL, CONSTRAINT TICKETTYPE_PK PRIMARY KEY (ID));

CREATE TABLE TT.EVENT_TYPE_GROUP (ID NUMBER(22, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(2000 BYTE), CONSTRAINT EVENTTYPEGROUP_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TT.EVENT_TYPE_GROUP.ID IS 'Group ID';
COMMENT ON COLUMN TT.EVENT_TYPE_GROUP.NAME IS 'Displayable name for the group.';
COMMENT ON COLUMN TT.EVENT_TYPE_GROUP.DESCRIPTION IS 'Description for the help popup window.';

CREATE TABLE TT.EVENT_TYPE2EVENT_TYPE_GROUP (EVENT_TYPE_GROUP_ID NUMBER(22, 0) NOT NULL, EVENT_TYPE_ID NUMBER(22, 0) NOT NULL, CONSTRAINT EVENTTYPE2EVENTTYPEGROUP_PK PRIMARY KEY (EVENT_TYPE_GROUP_ID, EVENT_TYPE_ID));
COMMENT ON COLUMN TT.EVENT_TYPE2EVENT_TYPE_GROUP.EVENT_TYPE_GROUP_ID IS 'Group ID';
COMMENT ON COLUMN TT.EVENT_TYPE2EVENT_TYPE_GROUP.EVENT_TYPE_ID IS 'Event type belonging to that group.';

CREATE TABLE TT.EVENT_NOTIFICATION (ID NUMBER(22, 0) NOT NULL, LOGIN_ID NUMBER(22, 0) NOT NULL, EVENT_NOTIFICATION_TYPE_ID NUMBER(22, 0) NOT NULL, COMMENTS VARCHAR2(1024 BYTE), EVENT_TYPE_ID NUMBER(22, 0), EVENT_TYPE_GROUP_ID NUMBER(22, 0), COMPANY_ID NUMBER(22, 0), SERVICE_ID NUMBER(22, 0), COMPANY_UNIT_ID NUMBER(22, 0), SERVICE_TYPE_ID NUMBER(22, 0), TICKET_ID NUMBER(22, 0), TICKET_TYPE_ID NUMBER(22, 0), REGEXP VARCHAR2(512 BYTE), ONLY_IF_WORKER NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT EVENTNOTIFICATION_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TT.EVENT_NOTIFICATION.ID IS 'Notification ID';
COMMENT ON COLUMN TT.EVENT_NOTIFICATION.LOGIN_ID IS 'Login / Contact that is notified';
COMMENT ON COLUMN TT.EVENT_NOTIFICATION.EVENT_NOTIFICATION_TYPE_ID IS 'Type of notification (e.g. SMS, email)';
COMMENT ON COLUMN TT.EVENT_NOTIFICATION.EVENT_TYPE_ID IS 'Matches kind of event (e.g. ISP outage)';
COMMENT ON COLUMN TT.EVENT_NOTIFICATION.EVENT_TYPE_GROUP_ID IS 'Matches group of events (e.g. VPN-related events)';
COMMENT ON COLUMN TT.EVENT_NOTIFICATION.COMPANY_ID IS 'Matches Company';
COMMENT ON COLUMN TT.EVENT_NOTIFICATION.SERVICE_ID IS 'Matches MSS Service (e.g. cust-prx-1, cust-prx-2)';
COMMENT ON COLUMN TT.EVENT_NOTIFICATION.COMPANY_UNIT_ID IS 'Matches Company Unit';
COMMENT ON COLUMN TT.EVENT_NOTIFICATION.SERVICE_TYPE_ID IS 'Matches Service Type (e.g. Security Gateway)';
COMMENT ON COLUMN TT.EVENT_NOTIFICATION.TICKET_ID IS 'Matches a specific Ticket';
COMMENT ON COLUMN TT.EVENT_NOTIFICATION.TICKET_TYPE_ID IS 'Matches Ticket Type (e.g. trouble ticket)';
COMMENT ON COLUMN TT.EVENT_NOTIFICATION.REGEXP IS 'Matches regular expression on event public content';
COMMENT ON COLUMN TT.EVENT_NOTIFICATION.ONLY_IF_WORKER IS 'If this is non-0, the notification is only sent if the notification owner is the
assigned worker of the associated ticket. Obviously, this is an OSAG-only feature.';

CREATE TABLE TT.EVENT_TYPE_MESSAGE (ID NUMBER(22, 0) NOT NULL, SUBJECT_TEMPLATE VARCHAR2(512 BYTE), MESSAGE_TEMPLATE CLOB, CONSTRAINT EVENTTYPEMESSAGE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TT.EVENT_TYPE_MESSAGE.ID IS 'Event type message ID';
COMMENT ON COLUMN TT.EVENT_TYPE_MESSAGE.SUBJECT_TEMPLATE IS 'Event type subject template. This subject can be used for email event notifications.';
COMMENT ON COLUMN TT.EVENT_TYPE_MESSAGE.MESSAGE_TEMPLATE IS 'Event type message template. This message template can be used for email or SMS event notifications.';

CREATE TABLE MSS.LOCAL_CONTACT_NOTIFICATION (ID NUMBER(22, 0) NOT NULL, LOCAL_CONTACT_ID NUMBER(22, 0) NOT NULL, EVENT_NOTIFICATION_TYPE_ID NUMBER(22, 0) NOT NULL, CONSTRAINT LOCALCONTACTNOTIFICATION_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.LOCAL_CONTACT_NOTIFICATION.ID IS 'The primary key ID';
COMMENT ON COLUMN MSS.LOCAL_CONTACT_NOTIFICATION.LOCAL_CONTACT_ID IS 'The local contact that has the according notification configured';
COMMENT ON COLUMN MSS.LOCAL_CONTACT_NOTIFICATION.EVENT_NOTIFICATION_TYPE_ID IS 'The event notification type (email,sms,etc.) for this notification';

CREATE TABLE MSS.ADDRESS (ID NUMBER(10, 0) NOT NULL, ADDRESS_LINES VARCHAR2(1024 BYTE), ADDRESS_SHIPPING_LINES VARCHAR2(1024 BYTE), LATITUDE_DEGREES NUMBER(2, 0), LATITUDE_MINUTES NUMBER(2, 0), LATITUDE_SECONDS NUMBER, LATITUDE_DIRECTION VARCHAR2(1 BYTE), LONGITUDE_DEGREES NUMBER(3, 0), LONGITUDE_MINUTES NUMBER(2, 0), LONGITUDE_SECONDS NUMBER, LONGITUDE_DIRECTION VARCHAR2(1 BYTE), POSTAL_CODE VARCHAR2(32 BYTE), IDENTIFIER VARCHAR2(32 BYTE), COMPANY_ID NUMBER(10, 0) NOT NULL, CITY_ID NUMBER(10, 0) NOT NULL, LOCAL_COMPANY_NAME VARCHAR2(1024 BYTE), PROFORMA_COMMENTS VARCHAR2(1024 BYTE), PHYSICAL_ACCESS_COMMENTS VARCHAR2(2000 BYTE), COMMENTS VARCHAR2(2000 BYTE), CUST_SITE_CODE VARCHAR2(10 BYTE), CONSTRAINT ADDRESS_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.ADDRESS IS 'Addresses (for coordinates see also http://www.tbs-sct.gc.ca/rpm-gbi/guides/Latlong_e.asp)';
COMMENT ON COLUMN MSS.ADDRESS.ADDRESS_LINES IS 'The address itself, typically street and number. Postal code,
city and country are stored in seperate fields.';
COMMENT ON COLUMN MSS.ADDRESS.ADDRESS_SHIPPING_LINES IS 'Used if a location wants to get sent its equipment to another location. E.g. a central
IT management location. Postal code, city and country need to be stored in this field too.';
COMMENT ON COLUMN MSS.ADDRESS.LATITUDE_DEGREES IS 'Range: 0 to 90';
COMMENT ON COLUMN MSS.ADDRESS.LATITUDE_MINUTES IS 'Range: 0 to 59';
COMMENT ON COLUMN MSS.ADDRESS.LATITUDE_SECONDS IS 'Range: 0 to 59 with optional decimals separated with a "."';
COMMENT ON COLUMN MSS.ADDRESS.LATITUDE_DIRECTION IS 'Available values are: N (North) and S (South)';
COMMENT ON COLUMN MSS.ADDRESS.LONGITUDE_DEGREES IS 'Range: 0 to 180';
COMMENT ON COLUMN MSS.ADDRESS.LONGITUDE_MINUTES IS 'Range 0 to 59';
COMMENT ON COLUMN MSS.ADDRESS.LONGITUDE_SECONDS IS 'Range: 0 to 59 with optional decimals separated with a "."';
COMMENT ON COLUMN MSS.ADDRESS.LONGITUDE_DIRECTION IS 'Available values are: E (East) or W (West) (O in some notations but we map it to W)';
COMMENT ON COLUMN MSS.ADDRESS.LOCAL_COMPANY_NAME IS 'This needs to be set if the subcompany at this addres has a different name than the belonging mother
company, e.g. a holding.';
COMMENT ON COLUMN MSS.ADDRESS.PHYSICAL_ACCESS_COMMENTS IS 'Optional field to describe procedures for gaining physical access to the devices located at this address';
COMMENT ON COLUMN MSS.ADDRESS.CUST_SITE_CODE IS 'Custom short identifier of a site';

CREATE TABLE MSS.LOCAL_CONTACT (ID NUMBER(10, 0) NOT NULL, PRIORITY NUMBER(10, 0) NOT NULL, CONTACT_ID NUMBER(10, 0), LOCAL_CONTACT_TYPE_ID NUMBER(10, 0) NOT NULL, ADDRESS_ID NUMBER(10, 0) NOT NULL, COMMENTS VARCHAR2(2000 BYTE), CONSTRAINT LOCALCONTACT_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.LOCAL_CONTACT IS 'A local contact is a contact standing in any relation with a address. The relation
is defined in mss.local_contact_type. Local contacts do have a priority.';
COMMENT ON COLUMN MSS.LOCAL_CONTACT.PRIORITY IS 'The priority orders the contacts for a certain criteria (e.g. on-site intervention local contacts in
the order they get called by mc). Priorities are assigned individual for every address and every type.
The highest priority is the one with the lowest number, starting with 1. There should not be any ''holes''
in the priority e.g.  1-2-4.';

CREATE TABLE MSS.CITY (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(256 BYTE) NOT NULL, TIME_ZONE_ID NUMBER(10, 0) NOT NULL, COUNTRY_ID NUMBER(10, 0) NOT NULL, CONTINENT_ID NUMBER(10, 0) NOT NULL, CONSTRAINT CITY_PK PRIMARY KEY (ID));

CREATE TABLE MSS.COUNTRY (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, CODE VARCHAR2(2 BYTE) NOT NULL, CONTINENT_ID NUMBER(10, 0) NOT NULL, CAPITAL VARCHAR2(128 BYTE), LARGEST_CITY VARCHAR2(128 BYTE), INTERNET_TLD VARCHAR2(16 BYTE), CALLING_CODE VARCHAR2(32 BYTE), TAXCODE_ID NUMBER(10, 0), CONSTRAINT COUNTRY_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.COUNTRY.CODE IS 'ISO 3166-1';

CREATE TABLE TT.STATUS (ID NUMBER(22, 0) NOT NULL, NAME VARCHAR2(40 BYTE) NOT NULL, CONSTRAINT STATUS_PK PRIMARY KEY (ID));

CREATE TABLE TT.LABEL (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, CONSTRAINT LABEL_PK PRIMARY KEY (ID));

CREATE TABLE MSS.SERVICE_COMPONENT (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, INTERNAL_CODE VARCHAR2(64 BYTE) NOT NULL, DEPRECATED NUMBER(1, 0) DEFAULT 0 NOT NULL, INTERNAL NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT SERVICECOMPONENT_PK PRIMARY KEY (ID));

CREATE TABLE TT.TICKET_RATING (ID NUMBER(22, 0) NOT NULL, RATING NUMBER(2, 0) NOT NULL, EVENT_ID NUMBER(22, 0) NOT NULL, CONSTRAINT TICKETRATING_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TT.TICKET_RATING.ID IS 'Ticket rating ID';
COMMENT ON COLUMN TT.TICKET_RATING.RATING IS 'The rating value, must be in {1,2,3,4,5}';
COMMENT ON COLUMN TT.TICKET_RATING.EVENT_ID IS 'The rating event to which this rating belongs';

CREATE TABLE TT.TICKET_DOCS_PAGE (ID NUMBER(22, 0) NOT NULL, TICKET_ID NUMBER(22, 0) NOT NULL, PAGE_ID NUMBER(22, 0) NOT NULL, PAGE_VERSION NUMBER(22, 0) NOT NULL, HOT_ISSUE NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT TICKETDOCSPAGE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TT.TICKET_DOCS_PAGE.ID IS 'Ticket-to-Docs page Reference ID';
COMMENT ON COLUMN TT.TICKET_DOCS_PAGE.TICKET_ID IS 'The ticket to which the Docs page is linked';
COMMENT ON COLUMN TT.TICKET_DOCS_PAGE.PAGE_ID IS 'The ID of the referenced Docs page';
COMMENT ON COLUMN TT.TICKET_DOCS_PAGE.PAGE_VERSION IS 'The version of the referenced Docs page';
COMMENT ON COLUMN TT.TICKET_DOCS_PAGE.HOT_ISSUE IS 'Boolean: Whether this page was labeled as hot issue when it was added to the ticket';

CREATE TABLE TT.TICKET2RELATED_TICKET (TICKET_ID NUMBER(11, 0) NOT NULL, RELATED_TICKET_ID NUMBER(11, 0) NOT NULL, CONSTRAINT TICKET2RELATEDTICKET_PK PRIMARY KEY (TICKET_ID, RELATED_TICKET_ID));

CREATE TABLE MC.MC_FILE_RELEASE (ID NUMBER(22, 0) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, MC_FILE_ID NUMBER(10, 0) NOT NULL, RELEASED NUMBER(1, 0) DEFAULT 0 NOT NULL, LAST_CHANGED date DEFAULT SYSDATE, SERVICE_ID NUMBER(10, 0), CONSTRAINT MCFILERELEASE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MC.MC_FILE_RELEASE.RELEASED IS 'Flag that indicates whether the download is in released or in pre-released state';

CREATE TABLE TT.TICKET2MC_FILE (TICKET_ID NUMBER(11, 0) NOT NULL, MC_FILE_ID NUMBER(11, 0) NOT NULL, CONSTRAINT TICKET2MCFILE_PK PRIMARY KEY (TICKET_ID, MC_FILE_ID));

CREATE TABLE TT.TODO_ITEM (ID NUMBER(11, 0) NOT NULL, TICKET_ID NUMBER(11, 0) NOT NULL, SEQ_NO NUMBER(11, 0) DEFAULT 0 NOT NULL, DETAILS CLOB, TODO_ITEM_STATUS_ID NUMBER(11, 0) NOT NULL, UPDATE_TIMESTAMP TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSDATE NOT NULL, IS_PUBLIC NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT TODOITEM_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TT.TODO_ITEM.SEQ_NO IS 'The sequence number of this item in its todo list';
COMMENT ON COLUMN TT.TODO_ITEM.UPDATE_TIMESTAMP IS 'Tells when the row was last updated. This column is updated by the trigger tt.todo_item_update_trg.';

CREATE TABLE TT.TODO_ITEM_STATUS (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(100 BYTE), CONSTRAINT TODOITEMSTATUS_PK PRIMARY KEY (ID));

CREATE TABLE TT.TICKET_TIME_STATISTIC (ID NUMBER(11, 0) NOT NULL, TICKET_ID NUMBER(11, 0) NOT NULL, OPEN_TIME NUMBER(11, 0) DEFAULT 0 NOT NULL, WAITING_TIME NUMBER(11, 0) DEFAULT 0 NOT NULL, THIRD_PARTY_TIME NUMBER(11, 0) DEFAULT 0 NOT NULL, DEFERRED_TIME NUMBER(11, 0) DEFAULT 0 NOT NULL, RESOLVED_TIME NUMBER(11, 0) DEFAULT 0 NOT NULL, CONSTRAINT TICKETTIMESTATISTIC_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TT.TICKET_TIME_STATISTIC.OPEN_TIME IS 'The time the ticket was in open state in seconds';
COMMENT ON COLUMN TT.TICKET_TIME_STATISTIC.WAITING_TIME IS 'The time the ticket was in waiting state in seconds';
COMMENT ON COLUMN TT.TICKET_TIME_STATISTIC.THIRD_PARTY_TIME IS 'The time the ticket was in third-party state in seconds';
COMMENT ON COLUMN TT.TICKET_TIME_STATISTIC.DEFERRED_TIME IS 'The time the ticket was in deferred state in seconds';
COMMENT ON COLUMN TT.TICKET_TIME_STATISTIC.RESOLVED_TIME IS 'The time the ticket was in resolved status in seconds';

CREATE TABLE TT.TICKET_FLOW (ID NUMBER(11, 0) NOT NULL, TICKET_ID NUMBER(11, 0) NOT NULL, FLOW_IN_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, FLOW_OUT_DATE TIMESTAMP(6) WITH TIME ZONE, OPEN_TIME NUMBER(11, 0) DEFAULT 0 NOT NULL, CONSTRAINT TICKETFLOW_PK PRIMARY KEY (ID));
COMMENT ON TABLE TT.TICKET_FLOW IS 'Ticket Flow Data that tracks in and out flow as well as queue stay in MCC';
COMMENT ON COLUMN TT.TICKET_FLOW.TICKET_ID IS 'Ticket ID for to which the flow state entry belongs to';
COMMENT ON COLUMN TT.TICKET_FLOW.FLOW_IN_DATE IS 'timestamp when the ticket entered the MCC queue, moment of in-flow';
COMMENT ON COLUMN TT.TICKET_FLOW.FLOW_OUT_DATE IS 'timestamp when the ticket left the MCC queue, moment of out-flow, may be null for tickets currently in the queue';
COMMENT ON COLUMN TT.TICKET_FLOW.OPEN_TIME IS 'the time in seconds the ticket spent in open status while it was in the queue';

CREATE TABLE PRX.PRX_POLICY_ITEM (ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0), ITEM_VALUE VARCHAR2(1000 BYTE) NOT NULL, CERTIFICATE_FINGERPRINT VARCHAR2(60 BYTE), PRX_POLICY_ITEM_TYPE_ID NUMBER(10, 0) NOT NULL, PRX_POLICY_TYPE_ID NUMBER(10, 0) NOT NULL, TICKET_ID NUMBER(10, 0), DESCRIPTION VARCHAR2(2000 BYTE), LAST_MODIFIED_TIME TIMESTAMP(6) WITH TIME ZONE, LAST_MODIFIED_CONTACT_ID NUMBER(10, 0), CUSTOMER_REFERENCE VARCHAR2(64 BYTE), CONSTRAINT PRXPOLICYITEM_PK PRIMARY KEY (ID));
COMMENT ON TABLE PRX.PRX_POLICY_ITEM IS 'Contains a proxy policy item of a item type in a policy';
COMMENT ON COLUMN PRX.PRX_POLICY_ITEM.LAST_MODIFIED_TIME IS 'The time when the entry was updated the last time';
COMMENT ON COLUMN PRX.PRX_POLICY_ITEM.LAST_MODIFIED_CONTACT_ID IS 'The contact that updated the entry the last time';
COMMENT ON COLUMN PRX.PRX_POLICY_ITEM.CUSTOMER_REFERENCE IS 'A reference to the customer''s incident/ticketing system';

CREATE TABLE TT.ATTACHMENT (ID NUMBER(22, 0) NOT NULL, UUID VARCHAR2(36 BYTE) NOT NULL, TICKET_ID NUMBER(22, 0) NOT NULL, EVENT_ID NUMBER(22, 0) NOT NULL, NAME VARCHAR2(256 BYTE) NOT NULL, TYPE VARCHAR2(256 BYTE), FILE_SIZE NUMBER(10, 0) NOT NULL, CREATION_DATE TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSDATE NOT NULL, CONSTRAINT ATTACHMENT_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TT.ATTACHMENT.NAME IS 'The files original file name how it was uploaded (after sanitizing). Used
          also as file name when attachment is downloaded.';
COMMENT ON COLUMN TT.ATTACHMENT.FILE_SIZE IS 'File size in bytes';
COMMENT ON COLUMN TT.ATTACHMENT.CREATION_DATE IS 'Timestamp of when the file was persisted.';

CREATE TABLE MSS.INSTALLATION_PROJECT_ITEM (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(150 BYTE), INSTALLATION_PROJECT_ID NUMBER(10, 0) NOT NULL, CUSTOMER_CONTACT_ID NUMBER(10, 0), OSAG_CONTACT_ID NUMBER(10, 0) NOT NULL, PROJECT_ITEM_STATUS_ID NUMBER(10, 0) NOT NULL, ADDRESS_ID NUMBER(10, 0) NOT NULL, ORIGINAL_COMPLETION_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, ESTIMATED_COMPLETION_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, COMPLETION_DATE TIMESTAMP(6) WITH TIME ZONE, ORDER_DATE TIMESTAMP(6) WITH TIME ZONE, CONFIG_RECEIVED_DATE TIMESTAMP(6) WITH TIME ZONE, SHIPMENT_DATE TIMESTAMP(6) WITH TIME ZONE, SHIPMENT_ARRIVED_DATE TIMESTAMP(6) WITH TIME ZONE, ACTIVATED_DATE TIMESTAMP(6) WITH TIME ZONE, CANCELLATION_DATE TIMESTAMP(6) WITH TIME ZONE, TICKET_ID NUMBER(10, 0), BLUEPRINT_ID NUMBER(10, 0), DELAYED NUMBER(1, 0) DEFAULT 0 NOT NULL, DELAY_REASON VARCHAR2(1024 BYTE), STATUS_COMMENT VARCHAR2(1024 BYTE), COMMENTS VARCHAR2(1024 BYTE), DELAY_DATE TIMESTAMP(6) WITH TIME ZONE, SHIPMENT_EST_ARRIVED_DATE TIMESTAMP(6) WITH TIME ZONE, PROCESSED_DATE TIMESTAMP(6) WITH TIME ZONE, LATEST_DISPATCH_DATE TIMESTAMP(6) WITH TIME ZONE, ORDER_CONTACT_ID NUMBER(10, 0), APPROVAL_CONTACT_ID NUMBER(10, 0), RUNBOOK_URL VARCHAR2(1024 BYTE), CREATION_DATE TIMESTAMP(6) WITH TIME ZONE, CONSTRAINT INSTALLATIONPROJECTITEM_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.CUSTOMER_CONTACT_ID IS 'Reference to the responsible contact on the customer side.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.OSAG_CONTACT_ID IS 'Reference to the responsible contact on OSAG side.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.PROJECT_ITEM_STATUS_ID IS 'The current state of the project item.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.ADDRESS_ID IS 'The location for this project item.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.ORIGINAL_COMPLETION_DATE IS 'The initially set target completion date.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.ESTIMATED_COMPLETION_DATE IS 'The currently estimated completion date, initialized with the ORIGINAL_COMPLETION_DATE.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.COMPLETION_DATE IS 'The date when the item was actually set to status ''completed''.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.ORDER_DATE IS 'Date when the project item''s status got changed to ''ordered''.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.CONFIG_RECEIVED_DATE IS 'Date when the project item''s status got changed to ''confirmed''.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.SHIPMENT_DATE IS 'Date when the hardware got shipped to the client.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.SHIPMENT_ARRIVED_DATE IS 'Date when the shipment of the hardware arrived at the client.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.ACTIVATED_DATE IS 'Date when the project item''s status got changed to ''activate'', former ''ready_date''.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.CANCELLATION_DATE IS 'Date when the project item''s status got changed to ''canceled''.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.DELAYED IS 'Denotes whether or not this project item is delayed.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.DELAY_DATE IS 'Date until when the item is expected to be delayed.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.SHIPMENT_EST_ARRIVED_DATE IS 'Date when the shipment of the hardware is estimated to arrive at the client.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.PROCESSED_DATE IS 'When the item was processed by service delivery. Set on ''processed'' state.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.LATEST_DISPATCH_DATE IS 'Date until when the items must be shipped.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.ORDER_CONTACT_ID IS 'Reference to the responsible contact that ordered the item.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.APPROVAL_CONTACT_ID IS 'Reference to the responsible contact that approved (=signed off) the item.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.RUNBOOK_URL IS 'Optional link to the runnbook.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT_ITEM.CREATION_DATE IS 'Creation date of the item. Nullable as this column was added with already existing items.';

CREATE TABLE NIDS.TICKET2RULE (EVENT_FILTER_RULE_ID NUMBER(11, 0) NOT NULL, TICKET_ID NUMBER(22, 0) NOT NULL, CONSTRAINT TICKET2RULE_PK PRIMARY KEY (EVENT_FILTER_RULE_ID, TICKET_ID));

CREATE TABLE FW.RULE2TICKET (RULE_ID NUMBER(10, 0) NOT NULL, TICKET_ID NUMBER(10, 0) NOT NULL, CONSTRAINT RULE2TICKET_PK PRIMARY KEY (RULE_ID, TICKET_ID));
COMMENT ON TABLE FW.RULE2TICKET IS '#MING';
COMMENT ON COLUMN FW.RULE2TICKET.RULE_ID IS 'FK to rule';
COMMENT ON COLUMN FW.RULE2TICKET.TICKET_ID IS 'FK ticket';

CREATE TABLE FW.SOURCE_NAT_RULE2TICKET (SOURCE_NAT_RULE_ID NUMBER(10, 0) NOT NULL, TICKET_ID NUMBER(10, 0) NOT NULL, CONSTRAINT SOURCENATRULE2TICKET_PK PRIMARY KEY (SOURCE_NAT_RULE_ID, TICKET_ID));
COMMENT ON TABLE FW.SOURCE_NAT_RULE2TICKET IS 'MING';
COMMENT ON COLUMN FW.SOURCE_NAT_RULE2TICKET.SOURCE_NAT_RULE_ID IS 'FK to SOURCE_NAT_RULE';
COMMENT ON COLUMN FW.SOURCE_NAT_RULE2TICKET.TICKET_ID IS 'FK to TICKET';

CREATE TABLE FW.DESTINATION_NAT_RULE2TICKET (DESTINATION_NAT_RULE_ID NUMBER(10, 0) NOT NULL, TICKET_ID NUMBER(10, 0) NOT NULL, CONSTRAINT DESTINATIONNATRULE2TICKET_PK PRIMARY KEY (DESTINATION_NAT_RULE_ID, TICKET_ID));
COMMENT ON TABLE FW.DESTINATION_NAT_RULE2TICKET IS 'MING';
COMMENT ON COLUMN FW.DESTINATION_NAT_RULE2TICKET.DESTINATION_NAT_RULE_ID IS 'FK to DESTINATION_NAT_RULE';
COMMENT ON COLUMN FW.DESTINATION_NAT_RULE2TICKET.TICKET_ID IS 'FK to TICKET';

CREATE TABLE MSS.DELETED_HOST2SERVICE_WINDOW (DELETED_HOST_ID NUMBER(10, 0) NOT NULL, SERVICE_WINDOW_ID NUMBER(10, 0) NOT NULL, CONSTRAINT DELETEDHOST2SERVICEWINDOW_PK PRIMARY KEY (DELETED_HOST_ID, SERVICE_WINDOW_ID));

CREATE TABLE VPN.TUNNEL (ID NUMBER(10, 0) NOT NULL, COMPRESSION NUMBER(1, 0) DEFAULT 0 NOT NULL, EGRESS_BW NUMBER(1, 0), INGRESS_BW NUMBER(1, 0), LAST_EVENT_ID NUMBER(10, 0), LATENCY NUMBER(10, 0), OSPF_COST NUMBER(10, 0), STATUS NUMBER(1, 0), STATUS_DATE TIMESTAMP(6) WITH TIME ZONE, TUNNELMODE NUMBER(2, 0) DEFAULT 1 NOT NULL, MEMBER_NO NUMBER(10, 0), VPN_MEMBER_ID1 NUMBER(10, 0) NOT NULL, VPN_MEMBER_ID2 NUMBER(10, 0) NOT NULL, IPV6_TUNNEL NUMBER(1, 0) DEFAULT 0 NOT NULL, AUTHOR VARCHAR2(64 BYTE), COMMENTS VARCHAR2(1024 BYTE), ACTIVE NUMBER(1, 0), OCTETS_PER_SECOND_IN NUMBER(10, 0), OCTETS_PER_SECOND_OUT NUMBER(10, 0), RTT NUMBER, LOSS NUMBER, BACKBONE NUMBER(1, 0) DEFAULT 0 NOT NULL, MTU NUMBER(6, 0), CONSTRAINT TUNNEL_PK PRIMARY KEY (ID));
COMMENT ON COLUMN VPN.TUNNEL.TUNNELMODE IS 'Any value different than 0 means the tunnel is active! The positive
value just indicates the SOURCE of the setting

 0 = disabled
 1 = enabled (source: full mesh mode in partition)
 2 = enabled (source: hub mode in partition)
 3 = enabled (source: explicitly enabled in VPN matrix)';
COMMENT ON COLUMN VPN.TUNNEL.IPV6_TUNNEL IS 'Tells whether the tunnel is an IPv6 one or not.';
COMMENT ON COLUMN VPN.TUNNEL.BACKBONE IS '1 if this WAN tunnel is built on top of the WAN Backbone';

CREATE TABLE VPN.VPN_MEMBER (ID NUMBER(10, 0) NOT NULL, PARTITION_ID NUMBER(10, 0) NOT NULL, HUB NUMBER(1, 0) DEFAULT 0 NOT NULL, INTERFACE_ID NUMBER(10, 0) NOT NULL, OSPF_COST NUMBER(10, 0), AUTHOR VARCHAR2(64 BYTE), COMMENTS VARCHAR2(1024 BYTE), BGP_HUB_PRIORITY NUMBER(10, 0), CONSTRAINT VPNMEMBER_PK PRIMARY KEY (ID));
COMMENT ON COLUMN VPN.VPN_MEMBER.BGP_HUB_PRIORITY IS 'Priority in a BGP Hub, with 1 being the highest priority.';

CREATE TABLE VPN.PARTITION (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, VPN_ID NUMBER(10, 0) NOT NULL, GUMA_INTERFACE_ID NUMBER(10, 0), NTP_INTERFACE_ID NUMBER(10, 0), OSPF_AREA NUMBER(10, 0) DEFAULT 0 NOT NULL, OSPF_COST NUMBER(10, 0) DEFAULT 10 NOT NULL, OSPF_HELLOINTERVAL NUMBER(10, 0) DEFAULT 15 NOT NULL, OSPF_DEADINTERVAL NUMBER(10, 0) DEFAULT 90 NOT NULL, ENABLE_OSPF_AUTH NUMBER(1, 0) DEFAULT 0 NOT NULL, TUNNELMODE NUMBER(2, 0) DEFAULT 1 NOT NULL, AUTHOR VARCHAR2(64 BYTE), COMMENTS VARCHAR2(1024 BYTE), DESCRIPTION VARCHAR2(1024 BYTE), BGP_CORE NUMBER(1, 0) DEFAULT 0 NOT NULL, AS_NUMBER NUMBER(10, 0), BGP_HOLD_TIME NUMBER(10, 0) DEFAULT 180, BGP_KEEPALIVE NUMBER(10, 0) DEFAULT 60, BACKBONE NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT PARTITION_PK PRIMARY KEY (ID));
COMMENT ON COLUMN VPN.PARTITION.TUNNELMODE IS '0 = no tunnels
 1 = full mesh
 2 = star topology';
COMMENT ON COLUMN VPN.PARTITION.BGP_CORE IS 'Boolean flag if this is a BGP Core partition';
COMMENT ON COLUMN VPN.PARTITION.AS_NUMBER IS 'AS Number if it is a BGP Core partition';
COMMENT ON COLUMN VPN.PARTITION.BGP_HOLD_TIME IS 'BGP Hold Time if it is a BGP Core partition.';
COMMENT ON COLUMN VPN.PARTITION.BGP_KEEPALIVE IS 'BGP Keepalive if it is a BGP Core partition.';
COMMENT ON COLUMN VPN.PARTITION.BACKBONE IS 'Indicates if this partition is a backbone partition.';

CREATE TABLE AUTH.TUNNELGROUP (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(50 BYTE) NOT NULL, AUTHSYS_ID NUMBER(11, 0) NOT NULL, DESCRIPTION VARCHAR2(500 BYTE), CONSTRAINT TUNNELGROUP_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.AUTHHOST2AUTHSYS (AUTHSYS_ID NUMBER(11, 0) NOT NULL, AUTHHOST_ID NUMBER(11, 0) NOT NULL);

CREATE TABLE AUTH.DIRTYAUTHHOST (AUTHHOST_ID NUMBER(11, 0) NOT NULL, ALIAS NUMBER(1, 0) DEFAULT 0 NOT NULL, GROUPS NUMBER(1, 0) DEFAULT 0 NOT NULL, LOGIN NUMBER(1, 0) DEFAULT 0 NOT NULL, LOGIN2GROUPS NUMBER(1, 0) DEFAULT 0 NOT NULL, TOKEN NUMBER(1, 0) DEFAULT 0 NOT NULL, TUNNELGROUP NUMBER(1, 0) DEFAULT 0 NOT NULL, LOGIN2TUNNELGROUP NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT DIRTYAUTHHOST_PK PRIMARY KEY (AUTHHOST_ID));

CREATE TABLE AUTH.PASSPORT_LOGIN (ID NUMBER(11, 0) NOT NULL, LOGIN VARCHAR2(250 BYTE) DEFAULT '', CONTACT_ID NUMBER(22, 0) DEFAULT 0 NOT NULL, TOKEN_ID NUMBER(11, 0), REPLACEMENTTOKEN_ID NUMBER(11, 0), EMAIL VARCHAR2(250 BYTE), SMSAUTHNUMBER VARCHAR2(32 BYTE), TOKENREPLACEMENTSTATE_ID NUMBER(11, 0) DEFAULT 0 NOT NULL, HOMEAUTHHOST_ID NUMBER(11, 0), ENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, LOCKED NUMBER(1, 0) DEFAULT 0 NOT NULL, MAXRETRIES NUMBER(2, 0) DEFAULT 0, LASTACCEPT date, LASTREJECT date, ANYTUNNELGROUP NUMBER(1, 0) DEFAULT 0 NOT NULL, PASSWORDEXPIRY date, COMPANY_ID NUMBER(11, 0) NOT NULL, PASSWORDTYPE_ID NUMBER(10, 0) DEFAULT 1 NOT NULL, TWOFACTORENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, USER_UNIT_ID NUMBER(10, 0), MODIFIED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, LASTTOKENREQUESTDATE TIMESTAMP(6) WITH TIME ZONE, AUTHTYPE_ID NUMBER(11, 0) NOT NULL, PWHASH VARCHAR2(64 BYTE), SALT VARCHAR2(64 BYTE), LASTPWCHANGE TIMESTAMP(6) WITH TIME ZONE, TMPPWDONLYEXPIRY TIMESTAMP(6) WITH TIME ZONE, CREATIONDATE TIMESTAMP(6) WITH TIME ZONE, LOGINTYPE_ID NUMBER(10, 0), COST_CENTER_ID NUMBER(11, 0), CONSTRAINT PASSPORT_LOGIN_PK PRIMARY KEY (ID));
COMMENT ON COLUMN AUTH.PASSPORT_LOGIN.EMAIL IS 'Email address used for authentication (as login name), if any.';
COMMENT ON COLUMN AUTH.PASSPORT_LOGIN.SMSAUTHNUMBER IS 'Mobile phone number for use with SMS authentication, if any.';
COMMENT ON COLUMN AUTH.PASSPORT_LOGIN.TOKENREPLACEMENTSTATE_ID IS 'for externally managed tokens; see table TOKENREPLACEMENTSTATE';
COMMENT ON COLUMN AUTH.PASSPORT_LOGIN.PASSWORDEXPIRY IS 'if the password expiry date has passed, the user cannot login anymore via the auth server
the password must be changed first in mission control (logging in to mc is still possible)';
COMMENT ON COLUMN AUTH.PASSPORT_LOGIN.LASTTOKENREQUESTDATE IS 'The date when the last token replacement has been requested.
This might happen explicitly in case of externally managed tokens or implicitly in case a token is disabled
and therefore a new one is required.
Note: the date should not be reset once the token is replaced that''s why it is called *last* token request date.';
COMMENT ON COLUMN AUTH.PASSPORT_LOGIN.AUTHTYPE_ID IS 'The authentication type. Historically points to 1/token and was not used in the portal; it was resurrected for
                 SMS authentication.';
COMMENT ON COLUMN AUTH.PASSPORT_LOGIN.PWHASH IS 'Hex representation of the SHA-256 hash of salt concatenated with password. The hash is calculated as sha256(salt + md5(password)).';
COMMENT ON COLUMN AUTH.PASSPORT_LOGIN.SALT IS 'Hex representation of the salt. Generate the salt using a cryptographically secure pseudo-random number generator (CSPRNG).';
COMMENT ON COLUMN AUTH.PASSPORT_LOGIN.LASTPWCHANGE IS 'The date on which the password has been changed.';
COMMENT ON COLUMN AUTH.PASSPORT_LOGIN.TMPPWDONLYEXPIRY IS 'The date when the temporary password expires';
COMMENT ON COLUMN AUTH.PASSPORT_LOGIN.CREATIONDATE IS 'The date when a user entry was created, i.e., the first AD sync or the time of user creation in the portal';
COMMENT ON COLUMN AUTH.PASSPORT_LOGIN.LOGINTYPE_ID IS 'The type of the login';

CREATE TABLE AUTH.GROUPS (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(50 BYTE) NOT NULL, AUTHSYS_ID NUMBER(11, 0), DESCRIPTION VARCHAR2(500 BYTE), CONSTRAINT GROUPS_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.AUTHHOST (ID NUMBER(11, 0) NOT NULL, HOST_ID NUMBER(11, 0) NOT NULL, BACKUPAUTHHOST_ID NUMBER(11, 0), BACKUPSTATUS NUMBER(1, 0) DEFAULT 0 NOT NULL, UPDATETIMEOUT NUMBER(11, 0) DEFAULT 20 NOT NULL, CONSTRAINT AUTHHOST_PK PRIMARY KEY (ID));
COMMENT ON COLUMN AUTH.AUTHHOST.HOST_ID IS 'the mss.host that corresponds to this auth host';
COMMENT ON COLUMN AUTH.AUTHHOST.BACKUPAUTHHOST_ID IS 'home host that is used if the main host fails';
COMMENT ON COLUMN AUTH.AUTHHOST.BACKUPSTATUS IS '0: backup is off, 1: backup is on (main host failed)';
COMMENT ON COLUMN AUTH.AUTHHOST.UPDATETIMEOUT IS 'Maximum time in seconds that is waited for this host to update its authentication data
when the backup is enabled, this time might be capped at some specific value';

CREATE TABLE FW.IP_GROUP (ID NUMBER(10, 0) NOT NULL, VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, NAME VARCHAR2(128 BYTE), NEGATE NUMBER(1, 0) DEFAULT 0 NOT NULL, AUTOMATIC NUMBER(1, 0) DEFAULT 0 NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), COMMENTS VARCHAR2(1024 BYTE), COMPANY_ID NUMBER(10, 0), CONSTRAINT IPGROUP_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.IP_GROUP IS 'group of ip-address-defining objects';
COMMENT ON COLUMN FW.IP_GROUP.AUTOMATIC IS 'The boolean property "automatic" marks ip groups which are created automatically to serve
as source- or destination-groups for firewall rules.';

CREATE TABLE FW.IP_SERVICE (ID NUMBER(10, 0) NOT NULL, VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, NAME VARCHAR2(128 BYTE), IP_PROTOCOL_ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0), PORT_FROM NUMBER(5, 0), PORT_TO NUMBER(5, 0), ICMP_TYPE_ID NUMBER(10, 0), ICMPV6_TYPE_ID NUMBER(10, 0), ICMP_CODE NUMBER(2, 0), DESCRIPTION VARCHAR2(1024 BYTE), COMMENTS VARCHAR2(1024 BYTE), CONSTRAINT IPSERVICE_PK PRIMARY KEY (ID));

CREATE TABLE FW.IP_ADDRESS (ID NUMBER(10, 0) NOT NULL, VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, IP_ADDRESS NUMBER(10, 0) NOT NULL, NAME VARCHAR2(255 BYTE), COMPANY_ID NUMBER(10, 0), DESCRIPTION VARCHAR2(1024 BYTE), COMMENTS VARCHAR2(1024 BYTE), CONSTRAINT IPADDRESS_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.IP_ADDRESS IS 'Simple IP addresses';

CREATE TABLE FW.SERVICE_GROUP (ID NUMBER(10, 0) NOT NULL, VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, AUTOMATIC NUMBER(1, 0) DEFAULT 0 NOT NULL, NAME VARCHAR2(128 BYTE), COMPANY_ID NUMBER(10, 0), DESCRIPTION VARCHAR2(1024 BYTE), COMMENTS VARCHAR2(1024 BYTE), CONSTRAINT SERVICEGROUP_PK PRIMARY KEY (ID));
COMMENT ON COLUMN FW.SERVICE_GROUP.AUTOMATIC IS 'the boolean property ''automatic'' marks service groups which are created automatically to serve
as service definitions for firewall rules.';

CREATE TABLE MSS.IPV6_ADDRESS (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(512 BYTE), COMPANY_ID NUMBER(10, 0), ADDRESS_1 NUMBER(20, 0) NOT NULL, ADDRESS_2 NUMBER(20, 0) NOT NULL, COMMENTS VARCHAR2(1000 BYTE), VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), CONSTRAINT IPV6ADDRESS_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.IPV6_ADDRESS.ID IS 'The primary key';
COMMENT ON COLUMN MSS.IPV6_ADDRESS.NAME IS 'An optional name for the IPv6 address';
COMMENT ON COLUMN MSS.IPV6_ADDRESS.COMPANY_ID IS 'A reference to the company this address belongs to. If null, the address is shared among all companies.';
COMMENT ON COLUMN MSS.IPV6_ADDRESS.ADDRESS_1 IS 'The most significant 64 bits of the address.';
COMMENT ON COLUMN MSS.IPV6_ADDRESS.ADDRESS_2 IS 'The least significant 64 bits of the address.';
COMMENT ON COLUMN MSS.IPV6_ADDRESS.COMMENTS IS 'An optional comment to the address.';

CREATE TABLE MSS.NETWORK (ID NUMBER(10, 0) NOT NULL, VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, NAME VARCHAR2(128 BYTE), IP_ADDRESS NUMBER(10, 0) NOT NULL, NETMASK NUMBER(2, 0) NOT NULL, SCOPE_COMPANY_ID NUMBER(10, 0), AUTHOR VARCHAR2(64 BYTE), COMMENTS VARCHAR2(1024 BYTE), DESCRIPTION VARCHAR2(1024 BYTE), CONSTRAINT NETWORK_PK PRIMARY KEY (ID));

CREATE TABLE MAIL.DMARC_REPORT_ORG (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(400 BYTE) NOT NULL, EMAIL VARCHAR2(400 BYTE), CONTACT_INFO VARCHAR2(400 BYTE), CONSTRAINT DMARCREPORTORG_PK PRIMARY KEY (ID));

CREATE TABLE MAIL.DMARC_REPORT_DOMAIN (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(400 BYTE) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, CONSTRAINT DMARCREPORTDOMAIN_PK PRIMARY KEY (ID));

CREATE TABLE OSIXINFO.OSIXINFO (ID NUMBER(10, 0) NOT NULL, KEY VARCHAR2(128 BYTE) NOT NULL, VALUE VARCHAR2(128 BYTE), CHANGE_TIMESTAMP TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, HARDWARE_ID NUMBER(10, 0), CONSTRAINT OSIXINFO_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.USER_ROLE_SCOPE_TYPE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE) NOT NULL, CONSTRAINT USERROLESCOPETYPE_PK PRIMARY KEY (ID));

CREATE TABLE FW.APP_GROUP (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(255 BYTE), DESCRIPTION VARCHAR2(1024 BYTE), COMMENTS VARCHAR2(1024 BYTE), COMPANY_ID NUMBER(10, 0), AUTOMATIC NUMBER(1, 0) DEFAULT 0 NOT NULL, VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, CONSTRAINT APPGROUP_PK PRIMARY KEY (ID));

CREATE TABLE FW.NAT_SECTION (ID NUMBER(10, 0) NOT NULL, NAT_SECTION_TYPE_ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0), POLICY_ID NUMBER(10, 0) NOT NULL, VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, CONSTRAINT NATSECTION_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.NAT_SECTION IS 'MING NAT section';
COMMENT ON COLUMN FW.NAT_SECTION.NAT_SECTION_TYPE_ID IS 'NAT Section Type Reference';
COMMENT ON COLUMN FW.NAT_SECTION.SERVICE_ID IS 'FK to mss.service (if type is local overrides or local exceptions, otherwise NULL)';
COMMENT ON COLUMN FW.NAT_SECTION.POLICY_ID IS 'FK to policy this NAT section belongs to';

CREATE TABLE FW.DESTINATION_NAT_RULE (ID NUMBER(10, 0) NOT NULL, NAT_SECTION_ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE), SEQ_NO NUMBER(10, 0) NOT NULL, ORIG_SRC_GROUP_ID NUMBER(10, 0), ORIG_DST_GROUP_ID NUMBER(10, 0), ORIG_SERVICE_GROUP_ID NUMBER(10, 0), NAT_ACTION_ID NUMBER(10, 0) NOT NULL, TRANS_DST_GROUP_ID NUMBER(10, 0), TRANS_SERVICE_GROUP_ID NUMBER(10, 0), LOG_TARGET_ID NUMBER(10, 0) NOT NULL, DISABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, COMMENTS VARCHAR2(1024 BYTE), LAST_UPDATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSDATE NOT NULL, LAST_UPDATER_ID NUMBER(10, 0), VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, CONSTRAINT DESTINATIONNATRULE_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.DESTINATION_NAT_RULE IS 'MING dst NAT rule';
COMMENT ON COLUMN FW.DESTINATION_NAT_RULE.NAT_SECTION_ID IS 'FK to parent section';
COMMENT ON COLUMN FW.DESTINATION_NAT_RULE.TRANS_DST_GROUP_ID IS 'only defined if action == NAT';
COMMENT ON COLUMN FW.DESTINATION_NAT_RULE.TRANS_SERVICE_GROUP_ID IS 'NULL means ORIG (can only be defined if action == NAT)';

CREATE TABLE FW.DNS_OBJECT (ID NUMBER(10, 0) NOT NULL, VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, FQDN VARCHAR2(256 BYTE) NOT NULL, COMPANY_ID NUMBER(10, 0), COMMENTS VARCHAR2(1000 BYTE), DESCRIPTION VARCHAR2(1000 BYTE), CONSTRAINT DNSOBJECT_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.DNS_OBJECT IS '#MING Holds the definition of a full qualified domain name';
COMMENT ON COLUMN FW.DNS_OBJECT.VERSION IS 'versioning used for local database in the GUI';
COMMENT ON COLUMN FW.DNS_OBJECT.FQDN IS 'DNS name';
COMMENT ON COLUMN FW.DNS_OBJECT.COMPANY_ID IS 'FK to the company, the group belongs to. Shared object if NULL.';

CREATE TABLE FW.POLICY (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), COMPANY_ID NUMBER(10, 0) NOT NULL, APP_FILTERING NUMBER(1, 0) DEFAULT 0 NOT NULL, PROCERA_ENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, CONSTRAINT POLICY_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.POLICY IS 'A MING Policy';
COMMENT ON COLUMN FW.POLICY.NAME IS 'name of the firewall policy';
COMMENT ON COLUMN FW.POLICY.DESCRIPTION IS 'description of the policy';
COMMENT ON COLUMN FW.POLICY.COMPANY_ID IS 'FK to company the policy belongs to';

CREATE TABLE FW.RULE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE), SEQ_NO NUMBER(10, 0) NOT NULL, SUB_SECTION_ID NUMBER(10, 0) NOT NULL, DISABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, SRC_IP_GROUP_ID NUMBER(10, 0), DST_IP_GROUP_ID NUMBER(10, 0), SERVICE_GROUP_ID NUMBER(10, 0), ACTION_ID NUMBER(10, 0) NOT NULL, LOG_TARGET_ID NUMBER(10, 0) NOT NULL, LAST_UPDATED TIMESTAMP(6) WITH TIME ZONE NOT NULL, LAST_UPDATER_ID NUMBER(10, 0), COMMENTS VARCHAR2(1000 BYTE), APP_GROUP_ID NUMBER(10, 0), VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, CONSTRAINT RULE_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.RULE IS '#MING Represents a rule that is part of a subsection';
COMMENT ON COLUMN FW.RULE.NAME IS 'optional name';
COMMENT ON COLUMN FW.RULE.SEQ_NO IS 'sequence number of the rule';
COMMENT ON COLUMN FW.RULE.SUB_SECTION_ID IS 'FK to the parent subsection';
COMMENT ON COLUMN FW.RULE.DISABLED IS 'disabled flag';
COMMENT ON COLUMN FW.RULE.SRC_IP_GROUP_ID IS 'FK to source IP group, NULL is any';
COMMENT ON COLUMN FW.RULE.DST_IP_GROUP_ID IS 'FK to dst IP group, NULL is any';
COMMENT ON COLUMN FW.RULE.SERVICE_GROUP_ID IS 'FK to srv group, NULL is any';
COMMENT ON COLUMN FW.RULE.ACTION_ID IS 'FK to action';
COMMENT ON COLUMN FW.RULE.LOG_TARGET_ID IS 'FK to log target';
COMMENT ON COLUMN FW.RULE.LAST_UPDATED IS 'timestamp of last update';
COMMENT ON COLUMN FW.RULE.LAST_UPDATER_ID IS 'FK to contact of last update action';
COMMENT ON COLUMN FW.RULE.COMMENTS IS 'optional comments';
COMMENT ON COLUMN FW.RULE.APP_GROUP_ID IS 'FK to automatic application group, NULL is any.';

CREATE TABLE FW.SCOPED_IP_GROUP (ID NUMBER(10, 0) NOT NULL, VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, COMMENTS VARCHAR2(1000 BYTE), DESCRIPTION VARCHAR2(1024 BYTE), CONSTRAINT SCOPEDIPGROUP_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.SCOPED_IP_GROUP IS '#MING';
COMMENT ON COLUMN FW.SCOPED_IP_GROUP.VERSION IS 'version information for local db sync';
COMMENT ON COLUMN FW.SCOPED_IP_GROUP.NAME IS 'name of the scoped IP group';
COMMENT ON COLUMN FW.SCOPED_IP_GROUP.COMPANY_ID IS 'FK to the company, the group belongs to. Note that there are no shared scoped groups';
COMMENT ON COLUMN FW.SCOPED_IP_GROUP.COMMENTS IS 'Optional comment';

CREATE TABLE FW.SCOPED_IP_GROUP_MEMBER (ID NUMBER(10, 0) NOT NULL, VERSION NUMBER(10, 0) NOT NULL, SCOPED_IP_GROUP_ID NUMBER(10, 0) NOT NULL, SCOPED_IP_GROUP_MEMBER_TYPE_ID NUMBER(10, 0) NOT NULL, SPECIFIC_SCOPE_SERVICE_ID NUMBER(10, 0), CONSTRAINT SCOPEDIPGROUPMEMBER_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.SCOPED_IP_GROUP_MEMBER IS '#MING';
COMMENT ON COLUMN FW.SCOPED_IP_GROUP_MEMBER.VERSION IS 'version for the local database of the GUI';
COMMENT ON COLUMN FW.SCOPED_IP_GROUP_MEMBER.SCOPED_IP_GROUP_ID IS 'FK to the scoped IP group';
COMMENT ON COLUMN FW.SCOPED_IP_GROUP_MEMBER.SCOPED_IP_GROUP_MEMBER_TYPE_ID IS 'FK to the type of scope used';
COMMENT ON COLUMN FW.SCOPED_IP_GROUP_MEMBER.SPECIFIC_SCOPE_SERVICE_ID IS 'FK to a specific service (scope type "specific")';

CREATE TABLE FW.SECTION (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE), POLICY_ID NUMBER(10, 0) NOT NULL, SRC_ZONE_ID NUMBER(10, 0) NOT NULL, DST_ZONE_ID NUMBER(10, 0) NOT NULL, SEQ_NO NUMBER(10, 0) NOT NULL, POLICY_ACTION_ID NUMBER(10, 0) NOT NULL, POLICY_LOG_TARGET_ID NUMBER(10, 0) NOT NULL, VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, CONSTRAINT SECTION_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.SECTION IS '#MING  Major part of a policy.Defines a flow by its src and dst zone and holds subsections of rules.
        Defines a policy action and a policy log target (consequently there are no explicit policy rules any longer)';
COMMENT ON COLUMN FW.SECTION.NAME IS 'optional name';
COMMENT ON COLUMN FW.SECTION.POLICY_ID IS 'FK to parent policy';
COMMENT ON COLUMN FW.SECTION.SRC_ZONE_ID IS 'FK to source zone';
COMMENT ON COLUMN FW.SECTION.DST_ZONE_ID IS 'FK to dst zone';
COMMENT ON COLUMN FW.SECTION.SEQ_NO IS 'Sequence number (GUI functionality only)';
COMMENT ON COLUMN FW.SECTION.POLICY_ACTION_ID IS 'FK to the policy action of this section';
COMMENT ON COLUMN FW.SECTION.POLICY_LOG_TARGET_ID IS 'FK to the log target for the policy action of this section';

CREATE TABLE FW.SOURCE_NAT_RULE (ID NUMBER(10, 0) NOT NULL, NAT_SECTION_ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE), SEQ_NO NUMBER(10, 0) NOT NULL, ORIG_SRC_GROUP_ID NUMBER(10, 0), ORIG_DST_GROUP_ID NUMBER(10, 0), ORIG_SERVICE_GROUP_ID NUMBER(10, 0), NAT_ACTION_ID NUMBER(10, 0) NOT NULL, TRANS_SRC_GROUP_ID NUMBER(10, 0), LOG_TARGET_ID NUMBER(10, 0) NOT NULL, DISABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, COMMENTS VARCHAR2(1024 BYTE), LAST_UPDATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSDATE NOT NULL, LAST_UPDATER_ID NUMBER(10, 0), VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, CONSTRAINT SOURCENATRULE_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.SOURCE_NAT_RULE IS 'MING src NAT rule';
COMMENT ON COLUMN FW.SOURCE_NAT_RULE.NAT_SECTION_ID IS 'FK to parent section';
COMMENT ON COLUMN FW.SOURCE_NAT_RULE.TRANS_SRC_GROUP_ID IS 'only defined if action == NAT';

CREATE TABLE MSS.IPV6_PREFIX (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(512 BYTE), COMPANY_ID NUMBER(10, 0), ADDRESS_1 NUMBER(20, 0) NOT NULL, ADDRESS_2 NUMBER(20, 0) NOT NULL, MASK NUMBER(3, 0) NOT NULL, COMMENTS VARCHAR2(1000 BYTE), VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), CONSTRAINT IPV6PREFIX_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.IPV6_PREFIX.ID IS 'The primary key';
COMMENT ON COLUMN MSS.IPV6_PREFIX.NAME IS 'An optional name for the IPv6 prefix';
COMMENT ON COLUMN MSS.IPV6_PREFIX.COMPANY_ID IS 'A reference to the company this prefix belongs to. If null, the prefix is shared among all companies.';
COMMENT ON COLUMN MSS.IPV6_PREFIX.ADDRESS_1 IS 'The higher 64bit of the prefix';
COMMENT ON COLUMN MSS.IPV6_PREFIX.ADDRESS_2 IS 'The lower 64bit of the prefix, usually 0';
COMMENT ON COLUMN MSS.IPV6_PREFIX.MASK IS 'The netmask of this prefix in CIDR notation.';
COMMENT ON COLUMN MSS.IPV6_PREFIX.COMMENTS IS 'An optional comment to the address.';

CREATE TABLE STOP.PASSPORT_CONTACT (ID NUMBER(22, 0) NOT NULL, LASTNAME VARCHAR2(50 BYTE), FIRSTNAME VARCHAR2(50 BYTE), COMPANY_ID NUMBER(22, 0), DIRECT VARCHAR2(30 BYTE), EMAIL VARCHAR2(250 BYTE), FAX VARCHAR2(30 BYTE), FUNCTION VARCHAR2(250 BYTE), HOME VARCHAR2(30 BYTE), MOBILE VARCHAR2(30 BYTE), OFFICE VARCHAR2(30 BYTE), CREATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, MODIFIED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, COMMENTS VARCHAR2(200 BYTE), CONSTRAINT PASSPORT_CONTACT_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.PASSPORT_LOGIN2GROUPS (LOGIN_ID NUMBER(11, 0) NOT NULL, GROUP_ID NUMBER(11, 0) NOT NULL, CONSTRAINT PASSPORTLOGIN2GROUPS_PK PRIMARY KEY (LOGIN_ID, GROUP_ID));

CREATE TABLE TIM.BLACKLIST_VALUE_CATEGORY (ID NUMBER(10, 0) NOT NULL, CATEGORY VARCHAR2(255 BYTE) NOT NULL, DESCRIPTION VARCHAR2(200 BYTE) NOT NULL, CONSTRAINT BLACKLISTVALUECATEGORY_PK PRIMARY KEY (ID));

CREATE TABLE TIM.BLACKLIST_ZONE_FILE (ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0), BLACKLIST_VALUE_TYPE_ID NUMBER(10, 0) NOT NULL, UPDATE_TIMESTAMP TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT BLACKLISTZONEFILE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TIM.BLACKLIST_ZONE_FILE.COMPANY_ID IS 'FK to the company. Default scope if NULL.';
COMMENT ON COLUMN TIM.BLACKLIST_ZONE_FILE.BLACKLIST_VALUE_TYPE_ID IS 'FK to BLACKLIST_VALUE_TYPE table. The actual type of the entry (IPv4, IPv6, domain).';
COMMENT ON COLUMN TIM.BLACKLIST_ZONE_FILE.UPDATE_TIMESTAMP IS 'The serial number will be calculated based on the date value in this field.';

CREATE TABLE TIM.BLACKLIST_VALUE (ID NUMBER(10, 0) NOT NULL, VALUE VARCHAR2(400 BYTE) NOT NULL, BLACKLIST_VALUE_CATEGORY_ID NUMBER(10, 0) NOT NULL, DESCRIPTION VARCHAR2(2000 BYTE), LAST_MODIFIED_TIME TIMESTAMP(6) WITH TIME ZONE, LAST_MODIFIED_CONTACT_ID NUMBER(10, 0), TICKET_ID NUMBER(10, 0), BLACKLIST_ZONE_FILE_ID NUMBER(10, 0) NOT NULL, CUSTOMER_REFERENCE VARCHAR2(64 BYTE), CONSTRAINT BLACKLISTVALUE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TIM.BLACKLIST_VALUE.BLACKLIST_VALUE_CATEGORY_ID IS 'FK to BLACKLIST_VALUE_CATEGORY table. Category for the blacklist entry (Spam, Phishing, Malware, Pup).';
COMMENT ON COLUMN TIM.BLACKLIST_VALUE.LAST_MODIFIED_TIME IS 'The time when the entry was updated the last time';
COMMENT ON COLUMN TIM.BLACKLIST_VALUE.LAST_MODIFIED_CONTACT_ID IS 'The contact that updated the entry the last time';
COMMENT ON COLUMN TIM.BLACKLIST_VALUE.BLACKLIST_ZONE_FILE_ID IS 'FK to BLACKLIST_ZONE_FILE table.';
COMMENT ON COLUMN TIM.BLACKLIST_VALUE.CUSTOMER_REFERENCE IS 'A reference to the customer''s incident/ticketing system';

CREATE TABLE MSS.CONTINENT (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, SHORT VARCHAR2(32 BYTE) NOT NULL, CONSTRAINT CONTINENT_PK PRIMARY KEY (ID));

CREATE TABLE TIM.EXCLUSION_LIST_VALUE_TYPE (ID NUMBER(10, 0) NOT NULL, TYPE VARCHAR2(30 BYTE) NOT NULL, DESCRIPTION VARCHAR2(200 BYTE) NOT NULL, CONSTRAINT EXCLUSIONLISTVALUETYPE_PK PRIMARY KEY (ID));

CREATE TABLE TIM.EXCLUSION_LIST_VALUE (ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0), EXCLUSION_LIST_VALUE_TYPE_ID NUMBER(10, 0) NOT NULL, VALUE VARCHAR2(400 BYTE) NOT NULL, DESCRIPTION VARCHAR2(2000 BYTE), LAST_MODIFIED_TIME TIMESTAMP(6) WITH TIME ZONE, LAST_MODIFIED_CONTACT_ID NUMBER(10, 0), TICKET_ID NUMBER(10, 0), CUSTOMER_REFERENCE VARCHAR2(64 BYTE), CONSTRAINT EXCLUSIONLISTVALUE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN TIM.EXCLUSION_LIST_VALUE.COMPANY_ID IS 'FK to the company. Shared scope if NULL.';
COMMENT ON COLUMN TIM.EXCLUSION_LIST_VALUE.EXCLUSION_LIST_VALUE_TYPE_ID IS 'FK to EXCLUSION_LIST_VALUE_TYPE table. The actual type of the entry (IP, email etc).';
COMMENT ON COLUMN TIM.EXCLUSION_LIST_VALUE.LAST_MODIFIED_TIME IS 'The time when the entry was updated the last time';
COMMENT ON COLUMN TIM.EXCLUSION_LIST_VALUE.LAST_MODIFIED_CONTACT_ID IS 'The contact that updated the entry the last time';
COMMENT ON COLUMN TIM.EXCLUSION_LIST_VALUE.CUSTOMER_REFERENCE IS 'A reference to the customer''s incident/ticketing system';

CREATE TABLE MSS.LOCAL_CONTACT_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, COMMENTS VARCHAR2(2000 BYTE), CONSTRAINT LOCALCONTACTTYPE_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.PASSPORT_LOGIN2TUNNELGROUP (LOGIN_ID NUMBER(11, 0) NOT NULL, TUNNELGROUP_ID NUMBER(11, 0) NOT NULL, CONSTRAINT PASSPORTLOGIN2TUNNELGROUP_PK PRIMARY KEY (LOGIN_ID, TUNNELGROUP_ID));

CREATE TABLE PRX.PRX_POLICY_TYPE (ID NUMBER(10, 0) NOT NULL, POLICY_TYPE VARCHAR2(20 BYTE) NOT NULL, CONSTRAINT PRXPOLICYTYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.SERVICE_FEATURE (ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0) NOT NULL, ENTITLEMENT_REF VARCHAR2(64 BYTE), SERVICE_OPTION_TYPE_ID NUMBER(10, 0) NOT NULL, SERVICE_FEATURE_STATE_ID NUMBER(10, 0) NOT NULL, OPERATIONAL_DATE TIMESTAMP(6) WITH TIME ZONE, APPROVED_DATE TIMESTAMP(6) WITH TIME ZONE, INSTALLATION_PROJECT_ITEM_ID NUMBER(10, 0), INITIALIZED_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT SERVICEFEATURE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.SERVICE_FEATURE.SERVICE_ID IS 'Links to the service where this feature is attached to';
COMMENT ON COLUMN MSS.SERVICE_FEATURE.ENTITLEMENT_REF IS 'Contains the entitlement id from Sitrox when the feature is linked';
COMMENT ON COLUMN MSS.SERVICE_FEATURE.SERVICE_OPTION_TYPE_ID IS 'Links to the service option type';
COMMENT ON COLUMN MSS.SERVICE_FEATURE.SERVICE_FEATURE_STATE_ID IS 'The current state of the feature, links to MSS.SERVICE_FEATURE_STATE';
COMMENT ON COLUMN MSS.SERVICE_FEATURE.OPERATIONAL_DATE IS 'The date when the feature was marked operational';
COMMENT ON COLUMN MSS.SERVICE_FEATURE.APPROVED_DATE IS 'The date when the feature was marked approved';
COMMENT ON COLUMN MSS.SERVICE_FEATURE.INSTALLATION_PROJECT_ITEM_ID IS 'Links back to the project item if the service feature was created from a blueprint.';
COMMENT ON COLUMN MSS.SERVICE_FEATURE.INITIALIZED_DATE IS 'The date when the feature was created';

CREATE TABLE MSS.STATIC_ROUTE (ID NUMBER(10, 0) NOT NULL, OSPF_DONT_PROPAGATE_ROUTE NUMBER(1, 0) DEFAULT 0 NOT NULL, NETWORK_ID NUMBER(10, 0) NOT NULL, NEXTHOP_INTERFACE_ID NUMBER(10, 0) NOT NULL, ROUTE_OWNER_HOST_ID NUMBER(10, 0) NOT NULL, PRIORITY NUMBER(3, 0) DEFAULT 1 NOT NULL, AUTHOR VARCHAR2(64 BYTE) NOT NULL, COMMENTS VARCHAR2(1024 BYTE), CONSTRAINT STATICROUTE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.STATIC_ROUTE.PRIORITY IS 'The priority for default route switching. The lower the number the higher the priority for default routes. The lowest possible value is 1. Must be 1 for all non-default routes.';

CREATE TABLE STOP.PASSPORT_CONTACT_SYNC (CONTACT_ID NUMBER(22, 0) NOT NULL, SYNCDOMAIN_ID NUMBER(10, 0) NOT NULL, DOMAIN VARCHAR2(256 BYTE), GUID VARCHAR2(32 BYTE), SID VARCHAR2(56 BYTE), SYNCTYPE_ID NUMBER(10, 0) NOT NULL, USNCHANGED NUMBER(20, 0), DISTINGUISHEDNAME VARCHAR2(2048 BYTE), CONSTRAINT PASSPORTCONTACTSYNC_PK PRIMARY KEY (CONTACT_ID));
COMMENT ON COLUMN STOP.PASSPORT_CONTACT_SYNC.GUID IS 'globally unique id';
COMMENT ON COLUMN STOP.PASSPORT_CONTACT_SYNC.SID IS 'active directory "security ID"';
COMMENT ON COLUMN STOP.PASSPORT_CONTACT_SYNC.USNCHANGED IS 'active directory "update sequence number"';
COMMENT ON COLUMN STOP.PASSPORT_CONTACT_SYNC.DISTINGUISHEDNAME IS 'active directory "distinguishedName" or "dn"';

CREATE TABLE MSS.HARDWARE_DEPLOY_REASON (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(1000 BYTE), CONSTRAINT HARDWAREDEPLOYREASON_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.HARDWARE_DEPLOY_REASON.NAME IS 'short descriptive name of the deploy reason';
COMMENT ON COLUMN MSS.HARDWARE_DEPLOY_REASON.DESCRIPTION IS 'description of the deploy reason';

CREATE TABLE AUTH.PASSPORT_ALIAS (ID NUMBER(11, 0) NOT NULL, LOGIN_ID NUMBER(11, 0) NOT NULL, ALIAS VARCHAR2(50 BYTE), CONSTRAINT PASSPORT_ALIAS_PK PRIMARY KEY (ID));

CREATE TABLE TICKETEVOLUTION.TICKEV (EVENT_ID NUMBER(*, 0) NOT NULL, TICKET_ID NUMBER(*, 0) NOT NULL, TICKET_STATUS VARCHAR2(32 BYTE), EMERGENCY_STATE VARCHAR2(32 BYTE), ASSIGNED_ENGINEER VARCHAR2(32 BYTE), MCC_STATE VARCHAR2(32 BYTE), TICKET_TYPE VARCHAR2(32 BYTE), TICKET_LABEL VARCHAR2(32 BYTE), DATE_FROM date, DATE_TO date, UPDATE_DT date DEFAULT SYSDATE NOT NULL, DELETED NUMBER(1, 0) DEFAULT 0 NOT NULL, TICKET_STATUS_ID NUMBER(22, 0));

CREATE TABLE TICKETEVOLUTION.STATE (KEY VARCHAR2(32 BYTE), VALUE_DT date NOT NULL);

CREATE TABLE AUTH.SYNCDOMAIN (ID NUMBER(10, 0) NOT NULL, SHORT VARCHAR2(64 BYTE) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, NEXTRUN TIMESTAMP(6) WITH TIME ZONE, SYNCPERIOD NUMBER(10, 0), TIMEOUT NUMBER(3, 0) DEFAULT 0 NOT NULL, AUTHSYS_ID NUMBER(10, 0) NOT NULL, DEFAULTHOMEAUTHHOST_ID NUMBER(11, 0) NOT NULL, DEFAULTLOCKED NUMBER(1, 0) DEFAULT 0 NOT NULL, DEFAULTPASSWORDTYPE_ID NUMBER(10, 0) DEFAULT 1 NOT NULL, DEFAULTTWOFACTORENABLED NUMBER(1, 0) DEFAULT 1 NOT NULL, DEFAULTSMSENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, LASTFAILURE TIMESTAMP(6) WITH TIME ZONE, LASTSUCCESS TIMESTAMP(6) WITH TIME ZONE, LASTFAILURETRANSACTION_ID NUMBER(18, 0), LASTSUCCESSTRANSACTION_ID NUMBER(18, 0), MAXDROPRATE NUMBER, DEFAULTPASSWORDEXPIRYOFFSET NUMBER(11, 0), DESCRIPTION VARCHAR2(512 BYTE) NOT NULL, DEFAULTSOFTTOKENENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, MAX_ATTEMPT NUMBER(*, 0) DEFAULT 3, RUN_ATTEMPT NUMBER(*, 0) DEFAULT 0, LAST_RESULTCODE NUMBER(*, 0) DEFAULT 0, LAST_RESULTMSG VARCHAR2(4000 BYTE), CONSTRAINT SYNCDOMAIN_PK PRIMARY KEY (ID));
COMMENT ON COLUMN AUTH.SYNCDOMAIN.SYNCPERIOD IS 'synchronization period in seconds.';
COMMENT ON COLUMN AUTH.SYNCDOMAIN.LASTFAILURETRANSACTION_ID IS 'mcaudit record transaction_id of the last failed synchronization run';
COMMENT ON COLUMN AUTH.SYNCDOMAIN.LASTSUCCESSTRANSACTION_ID IS 'mcaudit record transaction_id of the last successful synchronization run';
COMMENT ON COLUMN AUTH.SYNCDOMAIN.MAXDROPRATE IS 'The maximum rate of number_of_deleted_users/number_of_current_users which will be accepted during a sync process
(if exceeded, an exception is thrown). If left empty, the default values apply';
COMMENT ON COLUMN AUTH.SYNCDOMAIN.MAX_ATTEMPT IS 'Max number of automatic retries after failure';
COMMENT ON COLUMN AUTH.SYNCDOMAIN.RUN_ATTEMPT IS 'Number of retries done after failure';
COMMENT ON COLUMN AUTH.SYNCDOMAIN.LAST_RESULTCODE IS 'SQLCODE of last failure';
COMMENT ON COLUMN AUTH.SYNCDOMAIN.LAST_RESULTMSG IS 'SQLERRM of last failure';

CREATE TABLE AUTH.PASSWORDTYPE (ID NUMBER(10, 0) NOT NULL, SHORT VARCHAR2(64 BYTE) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, REMOTEVALIDATION NUMBER(1, 0) DEFAULT 0 NOT NULL, DESCRIPTION VARCHAR2(512 BYTE) NOT NULL, CONSTRAINT PASSWORDTYPE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN AUTH.PASSWORDTYPE.ID IS 'Primary key.';
COMMENT ON COLUMN AUTH.PASSWORDTYPE.SHORT IS 'Short identification code which never changes.';
COMMENT ON COLUMN AUTH.PASSWORDTYPE.NAME IS 'Short, descriptive name (for UI display etc)';
COMMENT ON COLUMN AUTH.PASSWORDTYPE.REMOTEVALIDATION IS 'When 1, password authentication is not handled by us and therefore the password may be NULL.';

CREATE TABLE MSS.COST_CENTER (ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, INTERNAL NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT COSTCENTER_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.AUTHTYPE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, DESCRIPTION VARCHAR2(128 BYTE), CONSTRAINT AUTHTYPE_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.AUTHSYS (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(50 BYTE) NOT NULL, COMPANY_ID NUMBER(11, 0) NOT NULL, SYNCEMAILENABLED NUMBER(1, 0) DEFAULT 1 NOT NULL, SYNCSERVICEGROUPSENABLED NUMBER(1, 0) DEFAULT 1 NOT NULL, SYNCTUNNELGROUPSENABLED NUMBER(1, 0) DEFAULT 1 NOT NULL, NOMCAUTHENTICATION NUMBER(1, 0) DEFAULT 0 NOT NULL, SMSAUTHENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, MCDISPLAY NUMBER(1, 0) DEFAULT 1 NOT NULL, ALIASESENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, PASSWORDEXPIRYENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, PASSWORDEXPIRYOFFSET NUMBER(11, 0), PASSWORDONLYALLOWED NUMBER(1, 0) DEFAULT 1 NOT NULL, TOKENSMANAGEDEXTERNALLY NUMBER(1, 0) DEFAULT 0 NOT NULL, AUTOEMAILALIASESENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, SYNCUSERUNITSENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, SYNCUSERACCOUNTCONTROLENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, AUTOMATICPASSWORDRESETENABLED NUMBER(1, 0) DEFAULT 1 NOT NULL, ALLOW_WEAK_PASSWORDS NUMBER(1, 0) DEFAULT 0 NOT NULL, DESCRIPTION VARCHAR2(2000 BYTE), SOFTTOKENENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, CUSTOM_SOFT_TOKEN_LABEL VARCHAR2(50 BYTE), TMPPWDONLYEXPIRYOFFSET NUMBER(11, 0) DEFAULT 259200 NOT NULL, USERACTIVATIONMAILSENABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, ALLOWSOFTTOKENREUSE NUMBER(1, 0) DEFAULT 0 NOT NULL, MAXRETRIES NUMBER(2, 0) DEFAULT 10 NOT NULL, NOTIFY_CONTACT_CHANGES NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT AUTHSYS_PK PRIMARY KEY (ID));
COMMENT ON COLUMN AUTH.AUTHSYS.SMSAUTHENABLED IS 'Whether SMS authentication is available on this authsystem.';
COMMENT ON COLUMN AUTH.AUTHSYS.MCDISPLAY IS 'This authsys is visible in mission control users management.';
COMMENT ON COLUMN AUTH.AUTHSYS.ALIASESENABLED IS 'Aliases can be edited in mc users management.';
COMMENT ON COLUMN AUTH.AUTHSYS.PASSWORDEXPIRYENABLED IS 'the password expiry setting can be edited in mc users management';
COMMENT ON COLUMN AUTH.AUTHSYS.PASSWORDEXPIRYOFFSET IS 'Specifies the offset from now, in seconds, that is used to calculate the default
(or next) value for the login.passwordexpiry field (e.g. when creating a new login)
a 0 or negative value means that the password expires immediately
a NULL value means that password expiry is defaulted to off
both (< 0 and NULL) prevent an automatic update of the
expiration end upon password change by the user';
COMMENT ON COLUMN AUTH.AUTHSYS.PASSWORDONLYALLOWED IS 'it is allowed to have password only authentication type';
COMMENT ON COLUMN AUTH.AUTHSYS.TOKENSMANAGEDEXTERNALLY IS 'token issuing and replacement is not managed via MC UI';
COMMENT ON COLUMN AUTH.AUTHSYS.AUTOEMAILALIASESENABLED IS 'email address are automatically listed as alias if this is switched on. (only applies to synchronized users
(currently...))';
COMMENT ON COLUMN AUTH.AUTHSYS.SYNCUSERUNITSENABLED IS 'Enable/Disable user unit synchronization over AD sync';
COMMENT ON COLUMN AUTH.AUTHSYS.SYNCUSERACCOUNTCONTROLENABLED IS 'Whether synchronizing the "locked" flag is enabled.';
COMMENT ON COLUMN AUTH.AUTHSYS.AUTOMATICPASSWORDRESETENABLED IS 'Whether passwords can be resetted via the automated link-mail process MC-2431';
COMMENT ON COLUMN AUTH.AUTHSYS.ALLOW_WEAK_PASSWORDS IS 'If true, no password strength checks are done.';
COMMENT ON COLUMN AUTH.AUTHSYS.CUSTOM_SOFT_TOKEN_LABEL IS 'If not null this label will be used in the QR code for the soft token activation.';
COMMENT ON COLUMN AUTH.AUTHSYS.TMPPWDONLYEXPIRYOFFSET IS 'value in seconds which is added to the current date to set the users AUTH.LOGIN.TMPPWDONLYEXPIRY field when ticking the checkbox.';
COMMENT ON COLUMN AUTH.AUTHSYS.ALLOWSOFTTOKENREUSE IS 'If true, resending the Software Token activation QR code is allowed.';
COMMENT ON COLUMN AUTH.AUTHSYS.MAXRETRIES IS 'Specifies the max password retry attempts one has before the account becomes locked. This value is transferred to AUTH.LOGIN.MAXRETRIES';
COMMENT ON COLUMN AUTH.AUTHSYS.NOTIFY_CONTACT_CHANGES IS 'Sends out a notification email and SMS on any account change';

CREATE TABLE AUTH.SYNCTYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, SHORT VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(512 BYTE) NOT NULL, CONSTRAINT SYNCTYPE_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.PASSPORT_RECENTPASSWORD (ID NUMBER(11, 0) NOT NULL, LOGIN_ID NUMBER(11, 0) NOT NULL, PASSWORD VARCHAR2(64 BYTE), VERSION NUMBER(11, 0) NOT NULL, SALT VARCHAR2(64 BYTE), CONSTRAINT PASSPORT_RECENTPASSWORD_PK PRIMARY KEY (ID));
COMMENT ON COLUMN AUTH.PASSPORT_RECENTPASSWORD.SALT IS 'Hex representation of the salt. If a salt is set the password (hash) has been generated using this salt.';

CREATE TABLE AUTH.PASSPORT_TEMP_ACCESS_KEY (ID NUMBER(10, 0) NOT NULL, LOGIN_ID NUMBER(10, 0) NOT NULL, KEY VARCHAR2(32 BYTE), VALID_UNTIL TIMESTAMP(6) WITH TIME ZONE, TEMP_ACCESS_TYPE_ID NUMBER(10, 0) NOT NULL, OTP VARCHAR2(255 BYTE), OTP_VALID_UNTIL TIMESTAMP(6) WITH TIME ZONE, TOKEN_ID NUMBER(11, 0), CONSTRAINT PASSPORT_TEMPACCESSKEY_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.TOKENTYPE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(50 BYTE) NOT NULL, DESCRIPTION VARCHAR2(500 BYTE), CONSTRAINT TOKENTYPE_PK PRIMARY KEY (ID));

CREATE TABLE AUTH.AUTHSECRET (AUTHSYS_ID NUMBER(11, 0) NOT NULL, SECRET VARCHAR2(50 BYTE) NOT NULL, CONSTRAINT AUTHSECRET_PK PRIMARY KEY (AUTHSYS_ID));
COMMENT ON COLUMN AUTH.AUTHSECRET.SECRET IS 'Shared secret for radius clients which want to authenticate users from this authsys';

CREATE TABLE MCDB_MONITOR.PLOG_OUTPUT (MESSAGE VARCHAR2(4000 BYTE), SEVERITY VARCHAR2(20 BYTE), LOGLEVEL NUMBER, SENDER_USER VARCHAR2(128 BYTE), SENDER_SESSION NUMBER, SENDER_PROC VARCHAR2(260 BYTE), LOG_TS TIMESTAMP(6) DEFAULT SYSDATE);

CREATE TABLE CERTS.PRIVATE_KEY (ID NUMBER(11, 0) NOT NULL, KEY VARCHAR2(32767 BYTE) NOT NULL, GENERATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, CONSTRAINT PRIVATEKEY_PK PRIMARY KEY (ID));
COMMENT ON TABLE CERTS.PRIVATE_KEY IS 'Stores private keys for certificates';
COMMENT ON COLUMN CERTS.PRIVATE_KEY.GENERATED IS 'Time when the private key was generated.';

CREATE TABLE APPID.PATH_OVERRIDE_MEMBER_LINK (ID NUMBER(10, 0) NOT NULL, MEMBER_ID NUMBER(10, 0) NOT NULL, PRIORITY NUMBER(3, 0) NOT NULL, INTERFACE_ID NUMBER(10, 0), FAILOVER_TYPE_ID NUMBER(10, 0), LINK_CLASS_ID NUMBER(10, 0), CONSTRAINT PATHOVERRIDEMEMBERLINK_PK PRIMARY KEY (ID));
COMMENT ON COLUMN APPID.PATH_OVERRIDE_MEMBER_LINK.INTERFACE_ID IS 'DEPRECATED: This column is deprecated as of 29.08.2025. Use table APPID.PATH_OVERRIDE_MEMBER_LINK.LINK_CLASS_ID instead.';
COMMENT ON COLUMN APPID.PATH_OVERRIDE_MEMBER_LINK.LINK_CLASS_ID IS 'Link ID of the override member';

CREATE TABLE APPID.INTERFACE_2_PS_LINK_CLASS (INTERFACE_ID NUMBER(10, 0) NOT NULL, LINK_CLASS_ID NUMBER(10, 0) NOT NULL, CONSTRAINT INTERFACE_2_PS_LINK_CLASS_PK PRIMARY KEY (INTERFACE_ID, LINK_CLASS_ID));

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_AUTH_USER_COMPANY_SCOPE" ("ID", "COMPANY_ID", "PERMISSION_ID", "SDP_ACCESS") AS SELECT ID,COMPANY_ID,PERMISSION_ID,SDP_ACCESS FROM AUTH.USER_COMPANY_SCOPE;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_AUTH_USER_SERVICE_SCOPE" ("ID", "SERVICE_ID", "PERMISSION_ID", "SDP_ACCESS") AS SELECT ID,SERVICE_ID,PERMISSION_ID,SDP_ACCESS FROM AUTH.USER_SERVICE_SCOPE;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_SERVICE" ("ID", "SERVICE_TYPE_ID", "COMPANY_ID", "SERVICE_LEVEL_ID", "COMPANY_UNIT_ID", "CONFIGURATION_GROUP_ID", "PATH_SELECTION_PROFILE_ID", "AQR_SLA_TARGET_ID") AS Select ID ,SERVICE_TYPE_ID ,COMPANY_ID ,SERVICE_LEVEL_ID ,COMPANY_UNIT_ID ,CONFIGURATION_GROUP_ID, PATH_SELECTION_PROFILE_ID, null as AQR_SLA_TARGET_ID FROM MSS.SERVICE;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MC_PORTAL_ROLE" ("ID", "LOGIN_ID", "USER_ROLE", "USER_ROLE_DESC", "USER_ROLE_SCOPE", "USER_ROLE_SCOPE_DESC", "IS_INTERNAL") AS SELECT
    r2p.id          as id,
    l2p.login_id    as login_id,
    r.name          as user_role,
    r.description   as user_role_desc,
    s.name          as user_role_scope,
    s.description   as user_role_scope_desc,
    r.is_internal   as is_internal
FROM AUTH.LOGIN2PROFILE   l2p
JOIN AUTH.USER_PERMISSION r2p       ON (l2p.profile_id=r2p.profile_id)
JOIN AUTH.USER_ROLE r               ON (r2p.USER_ROLE_ID=r.id)
JOIN AUTH.USER_ROLE_SCOPE_TYPE s    ON (r.USER_ROLE_SCOPE_TYPE_ID=s.id);

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_AUTH_LOGIN2PROFILE" ("LOGIN_ID", "PROFILE_ID") AS SELECT  LOGIN_ID,PROFILE_ID FROM AUTH.LOGIN2PROFILE;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_AUTH_LOGIN2PROFILE2" ("ID", "LOGIN_ID", "USER_ROLE", "USER_ROLE_DESC", "USER_ROLE_SCOPE", "USER_ROLE_SCOPE_DESC") AS Select        r2p.id          as id,
    l2p.login_id    as login_id,
    r.name          as user_role,
    r.description   as user_role_desc,
    s.name          as user_role_scope,
    s.description   as user_role_scope_desc
FROM AUTH.LOGIN2PROFILE   l2p
JOIN AUTH.USER_PERMISSION r2p       ON (l2p.profile_id=r2p.profile_id)
JOIN AUTH.USER_ROLE r               ON (r2p.USER_ROLE_ID=r.id)
JOIN AUTH.USER_ROLE_SCOPE_TYPE s    ON (r.USER_ROLE_SCOPE_TYPE_ID=s.id);

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_AUTH_USER_PERMISSION" ("ID", "USER_ROLE_ID", "PROFILE_ID") AS SELECT 
ID
,USER_ROLE_ID
,PROFILE_ID
FROM AUTH.USER_PERMISSION;

CREATE OR REPLACE FORCE VIEW "MSS"."V_CONFIGURATION_GROUP_NAME" ("ID", "NAME") AS SELECT cg.id,
  c.short
  || '-'
  || cg.name name
FROM MSS.CONFIGURATION_GROUP cg,
  STOP.COMPANY c
WHERE cg.company_id = c.id;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_STOP_COMPANY" ("ID", "NAME", "SHORT", "SUBPROCESSOR_CONSENT") AS Select ID, NAME, SHORT, SUBPROCESSOR_CONSENT FROM STOP.COMPANY;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_AUTH_USER_COMPANY_UNIT_SCOPE" ("ID", "COMPANY_UNIT_ID", "PERMISSION_ID", "SDP_ACCESS") AS SELECT 
ID
,COMPANY_UNIT_ID
,PERMISSION_ID
,SDP_ACCESS
FROM AUTH.USER_COMPANY_UNIT_SCOPE;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_AUTH_USER_UNIT_SCOPE" ("ID", "USER_UNIT_ID", "PERMISSION_ID", "SDP_ACCESS") AS SELECT ID,USER_UNIT_ID,PERMISSION_ID,SDP_ACCESS FROM AUTH.USER_UNIT_SCOPE;

CREATE OR REPLACE FORCE VIEW "MC"."V_HOST_CONNECTION_STATUS" ("HOST_ID", "STATUS", "LIVE_STATUS", "TICKET_ID") AS SELECT
host.id host_id,
(CASE WHEN host.active = 0 THEN 0 ELSE
(CASE WHEN (cio.down_date IS NOT NULL
AND ((sysdate - cio.down_date) * 24 * 60) > host.escalation_timeout)
THEN NVL(cio.type_id, -1)
ELSE -1 END) END) status,
(CASE WHEN host.active = 0 THEN 0 ELSE NVL(cio.type_id, -1) END) live_status,
(CASE WHEN cio.event_id IS NULL
THEN NULL ELSE (SELECT ticket_id FROM tt.event e WHERE e.id = cio.event_id) END) ticket_id
FROM mc.connection_interrupt_open cio, mss.host
WHERE cio.host_id(+) = host.id
WITH READ ONLY;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_HOST" ("ID", "NAME", "SERVICE_COMPANY_ID", "ADDRESS_ID", "ACTIVE", "FW_POLICY_ID", "HARDWARE_ID", "ESCALATION_TIMEOUT", "UNSTABLE", "REPLACEMENT_HARDWARE_ID") AS SELECT ID, NAME, SERVICE_COMPANY_ID, ADDRESS_ID, ACTIVE, FW_POLICY_ID, HARDWARE_ID, ESCALATION_TIMEOUT, UNSTABLE, REPLACEMENT_HARDWARE_ID FROM MSS.HOST;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_SERVICE_TYPE" ("ID", "NAME", "INTERNAL_CODE", "DEPRECATED", "INTERNAL", "DESCRIPTION") AS SELECT ID,NAME,INTERNAL_CODE,DEPRECATED,INTERNAL,DESCRIPTION FROM MSS.SERVICE_TYPE;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_HARDWARE_HISTORY" ("ID", "COMPANY_SHORT", "HOST_NAME", "SERVICE_TYPE_INTERNAL_CODE", "PURCHASE_DATE", "DISPOSAL_DATE", "HISTORY_DATE", "MAC_ADDRESS", "SERIAL_NUMBER", "BARCODE", "HARDWARE_DISPOSAL_COMMENTS", "LOG", "HARDWARE_DISPOSAL_REASON_ID", "HARDWARE_DISPOSAL_CONTACT_ID", "HARDWARE_TYPE_ID", "HARDWARE_DEPLOY_REASON_ID") AS SELECT 
ID
,COMPANY_SHORT
,HOST_NAME
,SERVICE_TYPE_INTERNAL_CODE
,PURCHASE_DATE
,DISPOSAL_DATE
,HISTORY_DATE
,MAC_ADDRESS
,SERIAL_NUMBER
,BARCODE
,HARDWARE_DISPOSAL_COMMENTS
,LOG
,HARDWARE_DISPOSAL_REASON_ID
,HARDWARE_DISPOSAL_CONTACT_ID
,HARDWARE_TYPE_ID
,HARDWARE_DEPLOY_REASON_ID
FROM MSS.HARDWARE_HISTORY;

CREATE OR REPLACE FORCE VIEW "AUTH"."V_LOGIN" ("ID", "LOGIN", "CONTACT_ID", "LOCKED", "CONTACT_FIRSTNAME", "CONTACT_LASTNAME", "CONTACT_EMAIL", "CONTACT_COMPANY_ID", "CONTACT_FAX", "CONTACT_DIRECT", "CONTACT_MOBILE", "CONTACT_HOME") AS SELECT l.id, l.login, l.contact_id, l.locked,
       c.firstname contact_firstname, c.lastname contact_lastname, c.email contact_email,
       c.company_id contact_company_id, c.fax contact_fax, c.direct contact_direct, c.mobile contact_mobile,
       c.home contact_home
FROM auth.login l, stop.contact c
WHERE l.contact_id = c.id
WITH READ ONLY;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_STOP_CONTACT" ("ID", "LASTNAME", "FIRSTNAME", "SHORT", "COMPANY_ID", "DIRECT", "EMAIL", "FAX", "FUNCTION", "HOME", "MCC_RANK", "MOBILE", "OFFICE", "CREATED", "MODIFIED") AS SELECT ID, LASTNAME, FIRSTNAME, SHORT, COMPANY_ID, DIRECT, EMAIL, FAX, FUNCTION, HOME, MCC_RANK, MOBILE, OFFICE, CAST((CREATED AT TIME ZONE 'UTC') as TIMESTAMP)  as CREATED, CAST((MODIFIED AT TIME ZONE 'UTC') as TIMESTAMP) as  MODIFIED
FROM STOP.CONTACT;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_HARDWARE_DISPOSAL_REASON" ("ID", "NAME", "DESCRIPTION", "OBSOLETE") AS SELECT ID, NAME, DESCRIPTION, OBSOLETE 
FROM MSS.HARDWARE_DISPOSAL_REASON;

CREATE OR REPLACE FORCE VIEW "AUTH"."V_S_LOGIN" ("ID", "LOGIN", "EMAIL", "CONTACT_ID", "ENABLED", "LOCKED", "COMPANY_ID", "MODIFIED", "CREATIONDATE") AS SELECT login.id as id,
       login,
       null as email,
       contact_id,
       enabled,
       locked,
       login.company_id as company_id,
       login.modified as modified,
       creationdate
FROM auth.login login
WITH READ ONLY;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_AUTH_V_S_LOGIN" ("ID", "LOGIN", "CONTACT_ID") AS SELECT ID, LOGIN, CONTACT_ID FROM AUTH.LOGIN;

