CREATE OR REPLACE FORCE VIEW "AUTH"."V_S_TOKEN" ("ID", "COMPANY_ID", "ENABLED", "EXPIRYDATE", "SERIAL", "TOKENFORM_ID", "TOKENTYPE_ID", "TOKEN_POOL_ID", "VALIDFROM", "ACTIVATED") AS SELECT id, company_id, enabled, expirydate, serial, tokenform_id, tokentype_id, token_pool_id, validfrom, activated
    FROM token
    WITH READ ONLY;

CREATE OR REPLACE FORCE VIEW "MAIL"."DMARC_REPORT_SUMMARY" ("ID", "ORGANIZATION", "DOMAIN", "DOMAINPOLICY", "START_DATE", "END_DATE", "IP_ADDRESS_LOW", "IP_ADDRESS_HIGH", "COMPANY_ID", "MESSAGECOUNT") AS SELECT A0.ID AS ID,
VAR_V_ORG.NAME AS ORGANIZATION,
VAR_V_DOMAIN.NAME AS DOMAIN,
A0.POLICY_P AS DOMAINPOLICY,
A0.START_DATE AS START_DATE,
A0.END_DATE AS END_DATE,
VAR_V_RECORD.IP_ADDRESS_LOW AS IP_ADDRESS_LOW,
VAR_V_RECORD.IP_ADDRESS_HIGH AS IP_ADDRESS_HIGH,
VAR_V_DOMAIN.COMPANY_ID AS COMPANY_ID,
SUM(VAR_V_RECORD.COUNT) AS MESSAGECOUNT
FROM MAIL.DMARC_REPORT A0
CROSS JOIN MAIL.DMARC_REPORT_RECORD VAR_V_RECORD
CROSS JOIN MAIL.DMARC_REPORT_DOMAIN VAR_V_DOMAIN
CROSS JOIN MAIL.DMARC_REPORT_ORG VAR_V_ORG
WHERE VAR_V_RECORD.DMARC_REPORT_ID = A0.ID
AND A0.DMARC_REPORT_DOMAIN_ID = VAR_V_DOMAIN.ID
AND A0.DMARC_REPORT_ORG_ID = VAR_V_ORG.ID
GROUP BY VAR_V_DOMAIN.COMPANY_ID, A0.ID, VAR_V_ORG.NAME, VAR_V_DOMAIN.NAME, A0.POLICY_P, A0.START_DATE, A0.END_DATE,
VAR_V_RECORD.IP_ADDRESS_LOW, VAR_V_RECORD.IP_ADDRESS_HIGH
WITH READ ONLY;

CREATE OR REPLACE FORCE VIEW "MCAUDIT"."V_RECORD" ("ID", "TIMESTAMP", "APPLICATION_NAME", "SYSTEM_NAME", "COMPONENT_NAME", "RECORD_TYPE_NAME", "DETAILS", "COMPANY_ID", "CONTACT_ID") AS SELECT r.id, r.timestamp, a.name AS application_name, s.name AS system_name, c.name AS component_name,
       rt.name AS record_type_name, details, company_id, contact_id
  FROM record r, application a, system s, component c, record_type rt
  WHERE r.application_id = a.id
    AND c.system_id = s.id
    AND r.component_id = c.id
    AND r.record_type_id = rt.id;

