CREATE OR REPLACE FORCE VIEW "BIREADER"."V_TT_EVENT" ("ID", "TYPE_ID", "PUBLIC_EVENT", "TICKET_ID", "COMPANY_ID", "EVENTDATE", "CONTACT_ID", "HOST_ID", "SIGN_OFF_OK", "DEMOTED", "DETAILS_PUBLIC", "DETAILS_PRIVATE", "ORG_TICKET_ID") AS Select ID ,TYPE_ID ,PUBLIC_EVENT ,TICKET_ID ,COMPANY_ID ,EVENTDATE, CONTACT_ID, HOST_ID ,SIGN_OFF_OK ,DEMOTED ,DETAILS_PUBLIC,DETAILS_PRIVATE,ORG_TICKET_ID
