CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MC_ISP_LINK_HISTORY" ("ID", "ISP_LINK_ID", "REPORTING_HOST_ID", "OLD_ISP_LINK_STATUS_TYPE_ID", "NEW_ISP_LINK_STATUS_TYPE_ID", "CHANGE_DATE", "EVENT_ID") AS SELECT ID, ISP_LINK_ID, REPORTING_HOST_ID, OLD_ISP_LINK_STATUS_TYPE_ID, NEW_ISP_LINK_STATUS_TYPE_ID, CHANGE_DATE, EVENT_ID FROM MC.ISP_LINK_HISTORY;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_ISP_LINK" ("ID", "COMPANY_ID", "ACCOUNT_NUMBER", "LINE_NUMBER", "BANDWIDTH_DOWN", "BANDWIDTH_UP", "SLA_AVAILABILITY", "MTU", "ROUTER_IP_ADDRESS1", "ACCOUNT_MANAGER_ID", "SUPPORT_ID", "PRODUCT_NAME", "CONTRACT_DURATION", "CANCELLATION_PERIOD", "LAST_REVIEW_DATE", "LINK_INSTALLATION_FEE", "LINK_RECURRING_FEE", "WAN_MANAGED", "CONTRACT_END_DATE", "ROUTER_NUMBER", "MEASURED_DOWNLOAD", "MEASURED_UPLOAD", "PING_IP_GROUP_ID", "SITE_ID", "OSAM_ID", "HANDOFF_PORT") AS SELECT ID, COMPANY_ID, ACCOUNT_NUMBER, LINE_NUMBER, BANDWIDTH_DOWN, BANDWIDTH_UP, SLA_AVAILABILITY, MTU, ROUTER_IP_ADDRESS1, ACCOUNT_MANAGER_ID, SUPPORT_ID, PRODUCT_NAME, CONTRACT_DURATION, CANCELLATION_PERIOD, LAST_REVIEW_DATE, LINK_INSTALLATION_FEE, LINK_RECURRING_FEE, WAN_MANAGED, CONTRACT_END_DATE, ROUTER_NUMBER, MEASURED_DOWNLOAD, MEASURED_UPLOAD, PING_IP_GROUP_ID, SITE_ID, OSAM_ID, HANDOFF_PORT FROM MSS.ISP_LINK;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_TT_TICKET" ("ID", "TYPE_ID", "STATUS_ID", "SUBJECT", "HOST_ID", "MSS_SERVICE_ID", "COMPANY_ID", "OPEN_DATE", "CLOSE_DATE", "LAST_RESOLVED_DATE", "LAST_STATUS_CHANGE_DATE", "CONTACT_ID", "PRIORITY", "WORKER_ID", "CUSTOMER_REFERENCE", "PARTNER_REFERENCE", "EMERGENCY", "HANDLED_BY_MCC", "ESCALATION_STATUS_ID", "LAST_ESCALATION_DATE", "CUSTOMER_TICKET_RATING_ID", "ENGINEER_TICKET_RATING_ID", "UPDATE_TIMESTAMP", "WAS_EMERGENCY", "STEPS_TOTAL", "STEPS_COMPLETED", "SERVICE_COMPONENT_ID", "LABEL_ID") AS Select ID, TYPE_ID, STATUS_ID, SUBJECT, HOST_ID, MSS_SERVICE_ID, COMPANY_ID, OPEN_DATE, CLOSE_DATE, LAST_RESOLVED_DATE, LAST_STATUS_CHANGE_DATE, CONTACT_ID, PRIORITY, WORKER_ID, CUSTOMER_REFERENCE, PARTNER_REFERENCE, EMERGENCY, HANDLED_BY_MCC, ESCALATION_STATUS_ID, LAST_ESCALATION_DATE, CUSTOMER_TICKET_RATING_ID, ENGINEER_TICKET_RATING_ID,UPDATE_TIMESTAMP, WAS_EMERGENCY, STEPS_TOTAL, STEPS_COMPLETED, SERVICE_COMPONENT_ID, LABEL_ID FROM TT.TICKET;

