CREATE OR REPLACE FORCE VIEW "MC"."CONNECTION_INTERRUPT" ("ID", "DOWN_DATE", "UP_DATE", "TYPE_ID", "MINUTES", "DETAILS", "EVENT_ID", "HOST_ID", "INTERRUPT_REVIEW_STATUS_ID") AS SELECT id, down_date, (CASE WHEN up_date < down_date THEN down_date ELSE up_date END) up_date, type_id,
         CAST((CASE WHEN up_date < down_date THEN 0 ELSE minutes END) as number(22)) minutes, details, event_id, host_id, INTERRUPT_REVIEW_STATUS_ID
    FROM mc.connection_interrupt_closed
  UNION ALL
  SELECT id, down_date, up_date, type_id,
         CAST((CASE WHEN up_date IS NULL THEN TRUNC((SYSDATE-down_date) * 60 * 24) END) as number(22)) minutes, details, event_id, host_id, INTERRUPT_REVIEW_STATUS_ID
    FROM mc.connection_interrupt_open;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MC_CONNECTION_INTERRUPT_OPEN" ("ID", "HOST_ID", "TYPE_ID", "DOWN_DATE", "UP_DATE", "MINUTES", "ACTIVE", "EVENT_ID", "ISP_ESCALATED", "INTERRUPT_REVIEW_STATUS_ID") AS Select ID, HOST_ID, TYPE_ID, DOWN_DATE, UP_DATE, MINUTES, ACTIVE, EVENT_ID, ISP_ESCALATED, INTERRUPT_REVIEW_STATUS_ID FROM MC.CONNECTION_INTERRUPT_OPEN;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MC_CONNECTION_INTERRUPT_CLOSED" ("ID", "HOST_ID", "TYPE_ID", "DOWN_DATE", "UP_DATE", "MINUTES", "ACTIVE", "EVENT_ID", "INTERRUPT_REVIEW_STATUS_ID") AS Select  ID, HOST_ID, TYPE_ID, DOWN_DATE, UP_DATE, MINUTES, ACTIVE, EVENT_ID, INTERRUPT_REVIEW_STATUS_ID FROM MC.CONNECTION_INTERRUPT_CLOSED;

CREATE OR REPLACE FORCE VIEW "MSS"."V_NONFAKE_INTERFACE" ("ID", "NAME", "VERSION", "HOST_ID", "IP_ADDRESS", "MGMTACCESS", "MTU", "EXTERNAL", "NETWORK_ID", "QOS_BWIN", "QOS_BWOUT", "OSPF_AREA", "OSPF_AUTHKEY", "OSPF_COST", "OSPF_DONT_PROPAGATE_ROUTE", "OSPF_HELLOINTERVAL", "OSPF_DEADINTERVAL", "INTERFACE_RIP_MODE_ID", "INTERFACE_RIP_AUTHKEY", "INTERFACE_SPEED_ID", "ANTI_SPOOFING_IP_GROUP_ID", "DISABLE_ANTI_SPOOFING_CHECKS", "INHERIT_TOS", "AUTHOR", "DESCRIPTION", "COMMENTS", "OSPF6_AREA", "OSPF6_COST", "OSPF6_HELLOINTERVAL", "OSPF6_DEADINTERVAL", "INTERFACE_RIPNG_MODE_ID", "DYNAMIC_IPV4", "HIDING_NAT", "NAT_ADDRESS_ID", "IS_CLUSTER_MANAGED", "BANDWIDTH_CONTROL_PROFILE_ID", "PATH_SELECTION_LINK_CLASS_ID", "OSPF_P2MP", "PATH_SELECTION_DISABLED", "PUBLIC_NAT_IP") AS SELECT "ID","NAME","VERSION","HOST_ID","IP_ADDRESS","MGMTACCESS","MTU","EXTERNAL","NETWORK_ID","QOS_BWIN","QOS_BWOUT","OSPF_AREA","OSPF_AUTHKEY","OSPF_COST","OSPF_DONT_PROPAGATE_ROUTE","OSPF_HELLOINTERVAL","OSPF_DEADINTERVAL","INTERFACE_RIP_MODE_ID","INTERFACE_RIP_AUTHKEY","INTERFACE_SPEED_ID","ANTI_SPOOFING_IP_GROUP_ID","DISABLE_ANTI_SPOOFING_CHECKS","INHERIT_TOS","AUTHOR","DESCRIPTION","COMMENTS","OSPF6_AREA","OSPF6_COST","OSPF6_HELLOINTERVAL","OSPF6_DEADINTERVAL","INTERFACE_RIPNG_MODE_ID","DYNAMIC_IPV4","HIDING_NAT","NAT_ADDRESS_ID","IS_CLUSTER_MANAGED","BANDWIDTH_CONTROL_PROFILE_ID","PATH_SELECTION_LINK_CLASS_ID","OSPF_P2MP","PATH_SELECTION_DISABLED","PUBLIC_NAT_IP"
FROM mss.interface
WHERE name NOT LIKE 'fake%' AND
    name NOT LIKE 'lbvirt%' AND
    name NOT LIKE 'vte_%' AND
    ip_address != 0;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_INTERFACE" ("ID", "NAME", "HOST_ID", "EXTERNAL", "NETWORK_ID", "QOS_BWIN", "QOS_BWOUT", "OSPF_DONT_PROPAGATE_ROUTE", "DESCRIPTION") AS SELECT ID, NAME, HOST_ID, EXTERNAL, NETWORK_ID, QOS_BWIN, QOS_BWOUT, OSPF_DONT_PROPAGATE_ROUTE, DESCRIPTION FROM MSS.INTERFACE;

CREATE OR REPLACE FORCE VIEW "MSS"."TIME_ZONE" ("ID", "SHORT", "UTC_OFFSET", "NAME", "DST") AS SELECT td.id, td.short,
(CASE
  WHEN (SYSTIMESTAMP AT TIME ZONE 'UTC') > td.dst_start_utc AND (SYSTIMESTAMP AT TIME ZONE 'UTC') < td.dst_end_utc
  THEN td.utc_offset_dst/60000
  ELSE td.utc_offset_std/60000
 END),
td.name,
(CASE
  WHEN (SYSTIMESTAMP AT TIME ZONE 'UTC') > td.dst_start_utc AND (SYSTIMESTAMP AT TIME ZONE 'UTC') < td.dst_end_utc
  THEN 1
  ELSE 0
END)
FROM mss.time_zone_data td;

CREATE OR REPLACE FORCE VIEW "NIDS"."NIDS_IP_GROUP" ("ID", "VERSION", "NAME", "AUTOAMTIC", "COMMENTS", "COMPANY_ID") AS select ID, 0, NAME, AUTOMATIC, COMMENTS, COMPANY_ID from NIDS.NIDS_ENTITY_GROUP;

CREATE OR REPLACE FORCE VIEW "NIDS"."NIDS_IP_GROUP_MEMBER" ("ID", "IP_GROUP_ID", "MEMBER_TYPE_ID", "IP_ADDRESS_ID", "NETWORK_ID", "IPV6_ADDRESS_ID", "IPV6_PREFIX_ID", "MEMBER_IP_GROUP_ID") AS select ID, ENTITY_GROUP_ID, NIDS_ENTITY_TYPE_ID, IP_ADDRESS_ID, NETWORK_ID, IPV6_ADDRESS_ID, IPV6_PREFIX_ID, MEMBER_ENTITY_GROUP_ID from NIDS.NIDS_ENTITY;

