CREATE OR REPLACE FORCE VIEW "BIREADER"."V_TT_HOST2SERVICE_WINDOW" ("HOST_ID", "SERVICE_WINDOW_ID") AS SELECT HOST_ID, SERVICE_WINDOW_ID FROM TT.HOST2SERVICE_WINDOW;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_TT_SERVICE_WINDOW" ("ID", "TICKET_ID", "START_DATE", "END_DATE", "DESCRIPTION", "TITLE", "COMPANY_ID") AS SELECT ID, TICKET_ID, START_DATE, END_DATE, DESCRIPTION, TITLE, COMPANY_ID FROM TT.SERVICE_WINDOW;

