CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_LOCAL_CONTACT_NOTIFICATION" ("ID", "LOCAL_CONTACT_ID", "EVENT_NOTIFICATION_TYPE_ID") AS Select ID ,LOCAL_CONTACT_ID ,EVENT_NOTIFICATION_TYPE_ID FROM MSS.local_contact_notification;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_ADDRESS" ("ID", "ADDRESS_LINES", "ADDRESS_SHIPPING_LINES", "LATITUDE_DEGREES", "LATITUDE_MINUTES", "LATITUDE_SECONDS", "LATITUDE_DIRECTION", "LONGITUDE_DEGREES", "LONGITUDE_MINUTES", "LONGITUDE_SECONDS", "LONGITUDE_DIRECTION", "POSTAL_CODE", "IDENTIFIER", "COMPANY_ID", "CITY_ID", "LOCAL_COMPANY_NAME", "PROFORMA_COMMENTS", "PHYSICAL_ACCESS_COMMENTS", "COMMENTS") AS Select  ID,ADDRESS_LINES,ADDRESS_SHIPPING_LINES,LATITUDE_DEGREES,	LATITUDE_MINUTES,	LATITUDE_SECONDS,	LATITUDE_DIRECTION,LONGITUDE_DEGREES,LONGITUDE_MINUTES,LONGITUDE_SECONDS,LONGITUDE_DIRECTION,POSTAL_CODE,IDENTIFIER,COMPANY_ID,CITY_ID,LOCAL_COMPANY_NAME,PROFORMA_COMMENTS,	PHYSICAL_ACCESS_COMMENTS,COMMENTS FROM MSS.ADDRESS;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_LOCAL_CONTACT" ("ID", "PRIORITY", "CONTACT_ID", "LOCAL_CONTACT_TYPE_ID", "ADDRESS_ID", "COMMENTS") AS Select ID ,PRIORITY ,CONTACT_ID ,LOCAL_CONTACT_TYPE_ID ,ADDRESS_ID ,COMMENTS FROM MSS.local_contact;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_CITY" ("ID", "NAME", "TIME_ZONE_ID", "COUNTRY_ID", "CONTINENT_ID", "COUNTRY_NAME", "CONTINENT_NAME", "COUNTRY_CODE") AS Select C.ID ,C.NAME ,C.TIME_ZONE_ID ,C.COUNTRY_ID ,CON.ID ,CO.NAME, CON.NAME, CO.CODE 

FROM MSS.CITY C
LEFT JOIN MSS.Country CO ON C.COUNTRY_ID = CO.ID
