CREATE OR REPLACE FORCE VIEW "BIREADER"."V_TT_TICKET_FLOW" ("ID", "TICKET_ID", "FLOW_IN_DATE", "FLOW_OUT_DATE", "OPEN_TIME") AS SELECT ID, TICKET_ID, 
CAST((FLOW_IN_DATE AT TIME ZONE 'UTC') as TIMESTAMP) as FLOW_IN_DATE, 
CAST((FLOW_OUT_DATE AT TIME ZONE 'UTC') as TIMESTAMP) as FLOW_OUT_DATE, OPEN_TIME FROM TT.TICKET_FLOW;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_PRX_PRX_POLICY_ITEM" ("ID", "COMPANY_ID", "ITEM_VALUE", "CERTIFICATE_FINGERPRINT", "PRX_POLICY_ITEM_TYPE_ID", "PRX_POLICY_TYPE_ID", "TICKET_ID", "DESCRIPTION", "LAST_MODIFIED_TIME", "LAST_MODIFIED_CONTACT_ID", "CUSTOMER_REFERENCE") AS Select ID ,COMPANY_ID ,ITEM_VALUE ,CERTIFICATE_FINGERPRINT ,PRX_POLICY_ITEM_TYPE_ID ,PRX_POLICY_TYPE_ID, TICKET_ID, DESCRIPTION ,LAST_MODIFIED_TIME ,LAST_MODIFIED_CONTACT_ID ,CUSTOMER_REFERENCE FROM PRX.PRX_POLICY_ITEM;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_INSTALLATION_PROJECT_ITEM" ("ID", "NAME", "INSTALLATION_PROJECT_ID", "CUSTOMER_CONTACT_ID", "OSAG_CONTACT_ID", "ORIGINAL_COMPLETION_DATE", "ESTIMATED_COMPLETION_DATE", "COMPLETION_DATE", "ORDER_DATE", "CONFIG_RECEIVED_DATE", "SHIPMENT_DATE", "SHIPMENT_ARRIVED_DATE", "ACTIVATED_DATE", "CANCELLATION_DATE", "TICKET_ID", "BLUEPRINT_ID", "DELAYED", "DELAY_REASON", "DELAY_DATE", "SHIPMENT_EST_ARRIVED_DATE", "PROCESSED_DATE", "LATEST_DISPATCH_DATE", "ORDER_CONTACT_ID", "APPROVAL_CONTACT_ID", "CREATION_DATE") AS SELECT ID, NAME, INSTALLATION_PROJECT_ID, CUSTOMER_CONTACT_ID, OSAG_CONTACT_ID, CAST((ORIGINAL_COMPLETION_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as ORIGINAL_COMPLETION_DATE, 
CAST((ESTIMATED_COMPLETION_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as ESTIMATED_COMPLETION_DATE, 
CAST((COMPLETION_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as COMPLETION_DATE, 
CAST((ORDER_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as ORDER_DATE, 
CAST((CONFIG_RECEIVED_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as CONFIG_RECEIVED_DATE, CAST((SHIPMENT_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as SHIPMENT_DATE,CAST((SHIPMENT_ARRIVED_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as SHIPMENT_ARRIVED_DATE, 
CAST((ACTIVATED_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as ACTIVATED_DATE, CAST((CANCELLATION_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as CANCELLATION_DATE, TICKET_ID, BLUEPRINT_ID, DELAYED, DELAY_REASON, CAST((DELAY_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as DELAY_DATE, CAST((SHIPMENT_EST_ARRIVED_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as SHIPMENT_EST_ARRIVED_DATE,
CAST((PROCESSED_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as PROCESSED_DATE, CAST((LATEST_DISPATCH_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as LATEST_DISPATCH_DATE, ORDER_CONTACT_ID, APPROVAL_CONTACT_ID, CAST((CREATION_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as CREATION_DATE  FROM MSS.INSTALLATION_PROJECT_ITEM;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_VPN_TUNNEL" ("ID", "OSPF_COST", "STATUS", "TUNNELMODE", "ACTIVE", "COMPRESSION", "EGRESS_BW", "INGRESS_BW", "LAST_EVENT_ID", "LATENCY", "STATUS_DATE", "MEMBER_NO", "VPN_MEMBER_ID1", "VPN_MEMBER_ID2", "IPV6_TUNNEL", "OCTETS_PER_SECOND_IN", "OCTETS_PER_SECOND_OUT", "RTT", "LOSS") AS SELECT ID, OSPF_COST, STATUS, TUNNELMODE, ACTIVE, COMPRESSION, EGRESS_BW, INGRESS_BW, LAST_EVENT_ID, LATENCY, STATUS_DATE, MEMBER_NO, VPN_MEMBER_ID1, VPN_MEMBER_ID2, IPV6_TUNNEL, OCTETS_PER_SECOND_IN, OCTETS_PER_SECOND_OUT, RTT, LOSS FROM VPN.TUNNEL;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_AUTH_LOGIN2GROUPS" ("LOGIN_ID", "NAME") AS Select l2tg.login_id, tg.name

FROM AUTH.PASSPORT_LOGIN2TUNNELGROUP l2tg
         JOIN AUTH.TUNNELGROUP tg on (l2tg.TUNNELGROUP_id = tg.id)
         JOIN AUTH.PASSPORT_LOGIN l ON l2tg.login_id=l.id
         JOIN STOP.PASSPORT_CONTACT c ON l.contact_id=c.id
WHERE c.company_id=6;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_AUTH_TUNNELGROUP" ("ID", "NAME", "AUTHSYS_ID", "DESCRIPTION") AS SELECT ID,NAME,AUTHSYS_ID,DESCRIPTION FROM AUTH.TUNNELGROUP;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MC_PERMISSION_RADIUS" ("LOGIN_ID", "RADIUSGROUP_ID", "RADIUSGROUP_NAME", "RADIUSGROUP_DESCRIPTION") AS SELECT    l.id  as login_id,    g.id as radiusgroup_id,    g.name  as radiusgroup_name,    g.description as radiusgroup_description
FROM AUTH.PASSPORT_LOGIN2GROUPS l2g
         JOIN AUTH.PASSPORT_LOGIN l on (l2g.LOGIN_ID=l.id)
         JOIN AUTH.GROUPS  g on (l2g.GROUP_ID = g.id)
         JOIN STOP.PASSPORT_CONTACT c on (c.id = l.contact_id)
WHERE c.company_id=6;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_AUTH_LOGIN2TUNNELGROUP" ("ID", "RADIUSGROUP_NAME", "RADIUSGROUP_DESCRIPTION") AS select l.id,
       g.name          as radiusgroup_name,
       g.description   as radiusgroup_description
FROM AUTH.PASSPORT_LOGIN2GROUPS l2g
         JOIN AUTH.PASSPORT_LOGIN          l on (l2g.LOGIN_ID=l.id)
         JOIN AUTH.GROUPS         g on (l2g.GROUP_ID = g.id)
         JOIN STOP.PASSPORT_CONTACT        c on (c.id = l.contact_id)
WHERE c.company_id=6;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_NETWORK" ("ID", "VERSION", "NAME", "IP_ADDRESS", "NETMASK", "SCOPE_COMPANY_ID", "AUTHOR", "COMMENTS", "DESCRIPTION") AS Select ID, VERSION, NAME, IP_ADDRESS, NETMASK, SCOPE_COMPANY_ID, AUTHOR, COMMENTS, DESCRIPTION FROM MSS.NETWORK;

CREATE OR REPLACE FORCE VIEW "OSIXINFO"."V_FIRMWAREBASE" ("ID", "FIRMWARE_BASE", "HARDWARE_ID", "CHANGE_TIMESTAMP") AS SELECT
  id,
  value as firmware_base,
  hardware_id as hardware_id,
  change_timestamp as change_timestamp
FROM osixinfo.osixinfo
WHERE key='firmwareBase';

CREATE OR REPLACE FORCE VIEW "OSIXINFO"."V_HOSTCLUSTERSTATE" ("ID", "HOST_CLUSTER_STATE", "HARDWARE_ID", "CHANGE_TIMESTAMP") AS SELECT
  id,
  value as host_cluster_state,
  hardware_id as hardware_id,
  change_timestamp as change_timestamp
FROM osixinfo.osixinfo
WHERE key='hostClusterState';

CREATE OR REPLACE FORCE VIEW "OSIXINFO"."V_IMAGE" ("ID", "IMAGE", "HARDWARE_ID", "CHANGE_TIMESTAMP") AS SELECT
  id,
  value as image,
  hardware_id as hardware_id,
  change_timestamp as change_timestamp
FROM osixinfo.osixinfo
WHERE key='image';

CREATE OR REPLACE FORCE VIEW "OSIXINFO"."V_FIRMWARE" ("ID", "FIRMWARE", "HARDWARE_ID", "CHANGE_TIMESTAMP") AS SELECT
  id,
  value as firmware,
  hardware_id as hardware_id,
  change_timestamp as change_timestamp
FROM osixinfo.osixinfo
WHERE key='firmware';

CREATE OR REPLACE FORCE VIEW "OSIXINFO"."V_LAST_UPDATE" ("ID", "LAST_UPDATE", "HARDWARE_ID", "CHANGE_TIMESTAMP") AS SELECT
  osixinfo.id,
  osixinfo.change_timestamp last_update,
  osixinfo.hardware_id hardware_id,
  osixinfo.change_timestamp change_timestamp
FROM osixinfo.osixinfo
WHERE osixinfo.key='last_update';

CREATE OR REPLACE FORCE VIEW "OSIXINFO"."V_MAC" ("ID", "MAC", "HARDWARE_ID", "CHANGE_TIMESTAMP") AS SELECT
    id,
    osixinfo.value mac,
    osixinfo.hardware_id hardware_id,
    osixinfo.change_timestamp change_timestamp
FROM osixinfo.osixinfo
WHERE osixinfo.key='hardware';

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_AUTH_USER_ROLE_SCOPE_TYPE" ("ID", "NAME", "DESCRIPTION") AS SELECT ID,NAME,DESCRIPTION FROM AUTH.USER_ROLE_SCOPE_TYPE;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_TIM_BLACKLIST_VALUE_CATEGORY" ("ID", "CATEGORY", "DESCRIPTION") AS Select ID ,CATEGORY ,DESCRIPTION FROM TIM.BLACKLIST_VALUE_CATEGORY;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_TIM_BLACKLIST_ZONE_FILE" ("ID", "COMPANY_ID", "BLACKLIST_VALUE_TYPE_ID", "UPDATE_TIMESTAMP") AS Select ID ,COMPANY_ID ,BLACKLIST_VALUE_TYPE_ID ,UPDATE_TIMESTAMP FROM TIM.BLACKLIST_ZONE_FILE;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_TIM_BLACKLIST_VALUE" ("ID", "VALUE", "BLACKLIST_VALUE_CATEGORY_ID", "DESCRIPTION", "LAST_MODIFIED_TIME", "LAST_MODIFIED_CONTACT_ID", "TICKET_ID", "BLACKLIST_ZONE_FILE_ID", "CUSTOMER_REFERENCE") AS Select ID ,VALUE ,BLACKLIST_VALUE_CATEGORY_ID ,DESCRIPTION ,LAST_MODIFIED_TIME ,LAST_MODIFIED_CONTACT_ID,
 TICKET_ID, BLACKLIST_ZONE_FILE_ID ,CUSTOMER_REFERENCE FROM TIM.BLACKLIST_VALUE;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_TIM_EXCLUSION_LIST_VALUE_TYPE" ("ID", "TYPE", "DESCRIPTION") AS Select ID ,TYPE ,DESCRIPTION FROM TIM.EXCLUSION_LIST_VALUE_TYPE;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_TIM_EXCLUSION_LIST_VALUE" ("ID", "COMPANY_ID", "EXCLUSION_LIST_VALUE_TYPE_ID", "VALUE", "DESCRIPTION", "LAST_MODIFIED_TIME", "LAST_MODIFIED_CONTACT_ID", "TICKET_ID", "CUSTOMER_REFERENCE") AS Select ID ,COMPANY_ID ,EXCLUSION_LIST_VALUE_TYPE_ID ,VALUE ,DESCRIPTION ,LAST_MODIFIED_TIME, LAST_MODIFIED_CONTACT_ID, TICKET_ID ,CUSTOMER_REFERENCE FROM TIM.EXCLUSION_LIST_VALUE;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_LOCAL_CONTACT_TYPE" ("ID", "NAME", "COMMENTS") AS Select ID ,NAME ,COMMENTS FROM MSS.local_contact_type;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_AUTH_LOGIN2TUNNELGROUP_NEW" ("LOGIN_ID", "TUNNELGROUP_ID") AS SELECT LOGIN_ID, TUNNELGROUP_ID FROM AUTH.PASSPORT_LOGIN2TUNNELGROUP;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_PRX_PRX_POLICY_TYPE" ("ID", "POLICY_TYPE") AS Select ID ,POLICY_TYPE FROM PRX.PRX_POLICY_TYPE;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_SERVICE_FEATURE" ("ID", "SERVICE_ID", "ENTITLEMENT_REF", "OPERATIONAL_DATE", "APPROVED_DATE", "INSTALLATION_PROJECT_ITEM_ID", "INITIALIZED_DATE") AS Select ID ,SERVICE_ID ,ENTITLEMENT_REF ,OPERATIONAL_DATE ,APPROVED_DATE ,INSTALLATION_PROJECT_ITEM_ID, INITIALIZED_DATE FROM MSS.SERVICE_FEATURE;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_STATIC_ROUTE" ("ID", "OSPF_DONT_PROPAGATE_ROUTE", "NETWORK_ID", "NEXTHOP_INTERFACE_ID", "PRIORITY") AS Select  ID, OSPF_DONT_PROPAGATE_ROUTE, NETWORK_ID, NEXTHOP_INTERFACE_ID, PRIORITY FROM  MSS.STATIC_ROUTE;

CREATE OR REPLACE FORCE VIEW "BIREADER"."V_MSS_HARDWARE_DEPLOY_REASON" ("ID", "NAME", "DESCRIPTION") AS SELECT ID, NAME, DESCRIPTION FROM MSS.HARDWARE_DEPLOY_REASON;

CREATE OR REPLACE FORCE VIEW "CERTS"."V_PRIVATE_KEY_RESTRICTED" ("ID", "GENERATED") AS SELECT PK.ID, PK.GENERATED FROM CERTS.PRIVATE_KEY PK;

CREATE TABLE APPID."#JDO_PROPERTIES" (KEY VARCHAR2(400 BYTE) NOT NULL, VALUE VARCHAR2(400 BYTE) DEFAULT 'none', CONSTRAINT JDO_PROPERTIES_PK PRIMARY KEY (KEY));

CREATE TABLE APPID.APP (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, TYPE_ID NUMBER(10, 0) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), COMMENTS VARCHAR2(1024 BYTE), COMPANY_ID NUMBER(22, 0), PRODUCTIVITY_SCORE NUMBER(2, 0), RISK_SCORE NUMBER(2, 0), VENDOR_ID VARCHAR2(32 BYTE), SEQ_ID NUMBER(10, 0), MARK NUMBER(10, 0), CATEGORY_ID NUMBER(10, 0) NOT NULL, PROCERA_COMPATIBLE NUMBER(1, 0) DEFAULT 1 NOT NULL, AUTOMATIC NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT APP_PK PRIMARY KEY (ID));
COMMENT ON COLUMN APPID.APP.SEQ_ID IS 'Optional sequence number (only QuickID applications are ordered)';
COMMENT ON COLUMN APPID.APP.MARK IS 'FWMARK value used to track the application in the netfilter stack';
COMMENT ON COLUMN APPID.APP.PROCERA_COMPATIBLE IS 'Flag to mark QuickID apps that can be run together with Procera apps.';
COMMENT ON COLUMN APPID.APP.AUTOMATIC IS 'Is the application created automatically (e.g. automatic optimized apps).';

