COMMENT ON COLUMN APPID.QUICKID_DNS.FQDN IS 'DNS name (incl. wildcards)';

CREATE TABLE APPID.QUICKID_NET4 (ID NUMBER(10, 0) NOT NULL, APP_ID NUMBER(10, 0) NOT NULL, ADDRESS NUMBER(10, 0) NOT NULL, MASK NUMBER(2, 0) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), CONSTRAINT QUICKIDNET4_PK PRIMARY KEY (ID));
COMMENT ON COLUMN APPID.QUICKID_NET4.MASK IS 'The netmask in CIDR notation.';

CREATE TABLE APPID.QUICKID_NET6 (ID NUMBER(10, 0) NOT NULL, APP_ID NUMBER(10, 0) NOT NULL, ADDRESS_1 NUMBER(20, 0) NOT NULL, ADDRESS_2 NUMBER(20, 0) NOT NULL, MASK NUMBER(3, 0) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), CONSTRAINT QUICKIDNET6_PK PRIMARY KEY (ID));
COMMENT ON COLUMN APPID.QUICKID_NET6.ADDRESS_1 IS 'The most significant 64bit';
COMMENT ON COLUMN APPID.QUICKID_NET6.ADDRESS_2 IS 'The least signigicant 64bit';
COMMENT ON COLUMN APPID.QUICKID_NET6.MASK IS 'The netmask in CIDR notation.';

