CREATE TABLE CERTS."#JDO_PROPERTIES" (KEY VARCHAR2(400 BYTE) NOT NULL, VALUE VARCHAR2(400 BYTE) DEFAULT 'none', CONSTRAINT JDO_PROPERTIES_PK PRIMARY KEY (KEY));

CREATE TABLE CERTS.CERTIFICATE (ID NUMBER(11, 0) NOT NULL, COMPANY_ID NUMBER(11, 0) NOT NULL, TICKET_ID NUMBER(11, 0), SHA256_FINGERPRINT VARCHAR2(64 BYTE) NOT NULL, COMMON_NAME VARCHAR2(1024 BYTE), ISSUER VARCHAR2(1024 BYTE), VALID_FROM TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, VALID_UNTIL TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, CERTIFICATE VARCHAR2(32767 BYTE) NOT NULL, KEY_ID NUMBER(11, 0), INTERMEDIATES VARCHAR2(32767 BYTE), ROOT VARCHAR2(32767 BYTE), CONSTRAINT CERTIFICATE_PK PRIMARY KEY (ID));
COMMENT ON TABLE CERTS.CERTIFICATE IS 'Stores information about certificates';
COMMENT ON COLUMN CERTS.CERTIFICATE.COMPANY_ID IS 'ID of company associated with the certificate.';
COMMENT ON COLUMN CERTS.CERTIFICATE.TICKET_ID IS 'ID of ticket which tracks creation of the certificate.';
COMMENT ON COLUMN CERTS.CERTIFICATE.SHA256_FINGERPRINT IS 'SHA256 fingerprint of the certificate.';
COMMENT ON COLUMN CERTS.CERTIFICATE.COMMON_NAME IS 'Host name associated with the certificate.';
COMMENT ON COLUMN CERTS.CERTIFICATE.ISSUER IS 'The subject which issued the certificate.';
COMMENT ON COLUMN CERTS.CERTIFICATE.VALID_FROM IS 'The certificate is valid from this time.';
COMMENT ON COLUMN CERTS.CERTIFICATE.VALID_UNTIL IS 'The certificate is valid until this time.';
COMMENT ON COLUMN CERTS.CERTIFICATE.KEY_ID IS 'ID of the private key associated with certificate.';

CREATE TABLE CERTS.CERTIFICATE_INDEX (ID NUMBER(11, 0) NOT NULL, CERTIFICATE_ID NUMBER(11, 0) NOT NULL, SUBJECT_KEY_ID VARCHAR2(64 BYTE) NOT NULL, CONSTRAINT CERTIFICATE_INDEX_PK PRIMARY KEY (ID));

CREATE TABLE CERTS.CERTIFICATE_SCOPE_TYPE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, DESCRIPTION VARCHAR2(128 BYTE), CONSTRAINT CERTIFICATESCOPETYPE_PK PRIMARY KEY (ID));
COMMENT ON TABLE CERTS.CERTIFICATE_SCOPE_TYPE IS 'Defines certificate scope types';
COMMENT ON COLUMN CERTS.CERTIFICATE_SCOPE_TYPE.NAME IS 'Name of the certificate scope type.';
COMMENT ON COLUMN CERTS.CERTIFICATE_SCOPE_TYPE.DESCRIPTION IS 'Description for the certificate scope type.';

CREATE TABLE CERTS.CERTIFICATE_USAGE (ID NUMBER(11, 0) NOT NULL, CERTIFICATE_ID NUMBER(11, 0) NOT NULL, TICKET_ID NUMBER(11, 0), COMPANY_ID NUMBER(11, 0), SERVICE_ID NUMBER(11, 0), HOST_ID NUMBER(11, 0), CERTIFICATE_SCOPE_TYPE_ID NUMBER(11, 0) NOT NULL, CERTIFICATE_SCOPE_NAME VARCHAR2(128 BYTE), GROUP_ID NUMBER(11, 0), CONSTRAINT CERTIFICATEUSAGE_PK PRIMARY KEY (ID));
COMMENT ON TABLE CERTS.CERTIFICATE_USAGE IS 'Describes where the certificate is used';
COMMENT ON COLUMN CERTS.CERTIFICATE_USAGE.CERTIFICATE_ID IS 'The certificate ID.';
COMMENT ON COLUMN CERTS.CERTIFICATE_USAGE.TICKET_ID IS 'ID of ticket which tracks deployment of the certificate.';
COMMENT ON COLUMN CERTS.CERTIFICATE_USAGE.COMPANY_ID IS 'ID of the company if the certificate is used on a company scope.';
COMMENT ON COLUMN CERTS.CERTIFICATE_USAGE.SERVICE_ID IS 'ID of the service if the certificate is used on a service scope.';
COMMENT ON COLUMN CERTS.CERTIFICATE_USAGE.HOST_ID IS 'ID of the host if the certificate is used on a host scope.';
COMMENT ON COLUMN CERTS.CERTIFICATE_USAGE.CERTIFICATE_SCOPE_TYPE_ID IS 'ID of the scope type which the certificate is applied on.';
COMMENT ON COLUMN CERTS.CERTIFICATE_USAGE.CERTIFICATE_SCOPE_NAME IS 'Name of the scope which the certificate is used on.';
COMMENT ON COLUMN CERTS.CERTIFICATE_USAGE.GROUP_ID IS 'ID of the group if the certificate is used on a group scope.';

CREATE TABLE CERTS.CSR (ID NUMBER(11, 0) NOT NULL, COMPANY_ID NUMBER(11, 0) NOT NULL, TICKET_ID NUMBER(11, 0), TEMPLATE_CERTIFICATE_ID NUMBER(11, 0), MODULUS VARCHAR2(64 BYTE) NOT NULL, COMMON_NAME VARCHAR2(1024 BYTE), CSR VARCHAR2(32767 BYTE) NOT NULL, KEY_ID NUMBER(11, 0) NOT NULL, CREATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, CONSTRAINT CSR_PK PRIMARY KEY (ID));
COMMENT ON TABLE CERTS.CSR IS 'Stores information about certificate signing requests';
COMMENT ON COLUMN CERTS.CSR.COMPANY_ID IS 'ID of company associated with the CSR.';
COMMENT ON COLUMN CERTS.CSR.TICKET_ID IS 'ID of ticket which tracks creation of the CSR.';
COMMENT ON COLUMN CERTS.CSR.TEMPLATE_CERTIFICATE_ID IS 'ID of certificate which was used as a template for CSR.';
COMMENT ON COLUMN CERTS.CSR.MODULUS IS 'RSA key modulus associated with the certificate.';
COMMENT ON COLUMN CERTS.CSR.COMMON_NAME IS 'Host name associated with the certificate.';
COMMENT ON COLUMN CERTS.CSR.KEY_ID IS 'ID of private key associated with the certificate.';

CREATE TABLE CERTS.SAN (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(256 BYTE) NOT NULL, CERTIFICATE_ID NUMBER(11, 0), CSR_ID NUMBER(11, 0), CONSTRAINT SAN_PK PRIMARY KEY (ID));
COMMENT ON TABLE CERTS.SAN IS 'Stores subject alternative names used by certificates';
COMMENT ON COLUMN CERTS.SAN.NAME IS 'Alternative name associated with the certificate.';
COMMENT ON COLUMN CERTS.SAN.CERTIFICATE_ID IS 'ID of the certificate associated with SAN.';
COMMENT ON COLUMN CERTS.SAN.CSR_ID IS 'ID of the CSR associated with SAN.';

CREATE TABLE ESP."#JDO_PROPERTIES" (KEY VARCHAR2(400 BYTE) NOT NULL, VALUE VARCHAR2(400 BYTE) DEFAULT 'none', CONSTRAINT JDO_PROPERTIES_PK PRIMARY KEY (KEY));

CREATE TABLE ESP.MC_CENTER (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, ADDRESS_ID NUMBER(11, 0) NOT NULL, PLANNED NUMBER(1, 0) NOT NULL, RESET_LEAVING_ENGINEER NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSIDER_SHIFT_PREFERENCES NUMBER(1, 0) DEFAULT 1 NOT NULL, CONSTRAINT MCCENTER_PK PRIMARY KEY (ID));
COMMENT ON TABLE ESP.MC_CENTER IS 'Defines an MC Center, i.e. a center with its own schedule and shift types etc.';
COMMENT ON COLUMN ESP.MC_CENTER.NAME IS 'Descriptive name.';
COMMENT ON COLUMN ESP.MC_CENTER.ADDRESS_ID IS 'Location of the MC Center.';
COMMENT ON COLUMN ESP.MC_CENTER.PLANNED IS 'Currently not used';
COMMENT ON COLUMN ESP.MC_CENTER.RESET_LEAVING_ENGINEER IS 'If set to true, the workload of all contacts which are currently not assigned to this center should be 0 -> ensured by a nightly cron job.';
COMMENT ON COLUMN ESP.MC_CENTER.CONSIDER_SHIFT_PREFERENCES IS 'If set to true if the shift preferences should be considered when creating generations for this center.';

CREATE TABLE ESP.MC_CENTER_CONTACT (ID NUMBER(11, 0) NOT NULL, MC_CENTER_ID NUMBER(11, 0) NOT NULL, CONTACT_ID NUMBER(11, 0) NOT NULL, START_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, END_DATE TIMESTAMP(6) WITH TIME ZONE, CONSTRAINT MCCENTERCONTACT_PK PRIMARY KEY (ID));
COMMENT ON TABLE ESP.MC_CENTER_CONTACT IS 'Tells which engineers are present/available for which MC Center.';
COMMENT ON COLUMN ESP.MC_CENTER_CONTACT.MC_CENTER_ID IS 'The MC center';
COMMENT ON COLUMN ESP.MC_CENTER_CONTACT.CONTACT_ID IS 'The engineer';
COMMENT ON COLUMN ESP.MC_CENTER_CONTACT.START_DATE IS 'The date from which the engineer is available for this MC center';
COMMENT ON COLUMN ESP.MC_CENTER_CONTACT.END_DATE IS 'The date until which the engineer is available for this MC center. Null means indefinite.';

CREATE TABLE FW."#JDO_PROPERTIES" (KEY VARCHAR2(400 BYTE) NOT NULL, VALUE VARCHAR2(400 BYTE) DEFAULT 'none', CONSTRAINT JDO_PROPERTIES_PK PRIMARY KEY (KEY));

CREATE TABLE FW.ACTION (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, CONSTRAINT ACTION_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.ACTION IS 'Value table for firewall rule target actions';

CREATE TABLE FW.APP_GROUP2APP (APP_GROUP_ID NUMBER(10, 0) NOT NULL, APP_ID NUMBER(10, 0) NOT NULL, CONSTRAINT APPGROUP2APP_PK PRIMARY KEY (APP_GROUP_ID, APP_ID));

CREATE TABLE FW.APP_GROUP2APP_GROUP (PARENT_ID NUMBER(10, 0) NOT NULL, CHILD_ID NUMBER(10, 0) NOT NULL, CONSTRAINT APPGROUP2APPGROUP_PK PRIMARY KEY (PARENT_ID, CHILD_ID));

CREATE TABLE FW.AWS_Azure_IMP_uniq (NET VARCHAR2(50 BYTE), MASK NUMBER(*, 0), NAME VARCHAR2(2000 BYTE), "GROUP" VARCHAR2(20 BYTE), CREATED_NETWORK NUMBER(*, 0) DEFAULT 0, CREATED_GROUPMEMBER NUMBER(*, 0) DEFAULT 0, network_ID NUMBER(*, 0));

CREATE TABLE FW.CHANGE (ID NUMBER NOT NULL, COMPANY_ID NUMBER(22, 0) NOT NULL, CUSTOMER_REFERENCE VARCHAR2(64 BYTE), DESCRIPTION VARCHAR2(1024 BYTE), TICKET_ID NUMBER(22, 0), SUMMARY_BLOB_NAME VARCHAR2(256 CHAR) NOT NULL, AUTHOR_USER VARCHAR2(128 BYTE), AUTHORED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT PK_CHANGE PRIMARY KEY (ID));
COMMENT ON TABLE FW.CHANGE IS 'Stores historic firewall change metadata. The change summary itself is stored as JSON in Azure Blob Storage.';
COMMENT ON COLUMN FW.CHANGE.ID IS 'Surrogate primary key.';
COMMENT ON COLUMN FW.CHANGE.COMPANY_ID IS 'The company for which the change was made.';
COMMENT ON COLUMN FW.CHANGE.CUSTOMER_REFERENCE IS 'A customer-internal reference for the change.';
COMMENT ON COLUMN FW.CHANGE.DESCRIPTION IS 'Customer-provided description of the change.';
COMMENT ON COLUMN FW.CHANGE.TICKET_ID IS 'Optional reference to a ticket associated with the change.';
COMMENT ON COLUMN FW.CHANGE.SUMMARY_BLOB_NAME IS 'The name of the blob storing the change summary in Azure Blob Storage.';
COMMENT ON COLUMN FW.CHANGE.AUTHOR_USER IS 'The user who authored the change at the time it was made.';
COMMENT ON COLUMN FW.CHANGE.AUTHORED IS 'Timestamp when the change was made.';

CREATE TABLE FW.CHE_DNAT_SRC_ZONE (DESTINATION_NAT_RULE_ID NUMBER(10, 0) NOT NULL, ZONE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT CHEDNATSRCZONE_PK PRIMARY KEY (DESTINATION_NAT_RULE_ID, ZONE_ID));
COMMENT ON TABLE FW.CHE_DNAT_SRC_ZONE IS 'MING destination NAT rule to source zone mapping table';
COMMENT ON COLUMN FW.CHE_DNAT_SRC_ZONE.DESTINATION_NAT_RULE_ID IS 'FK to destination nat rule';
COMMENT ON COLUMN FW.CHE_DNAT_SRC_ZONE.ZONE_ID IS 'FK to zone to be used as source zone';

CREATE TABLE FW.CHE_SNAT_DST_ZONE (SOURCE_NAT_RULE_ID NUMBER(10, 0) NOT NULL, ZONE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT CHESNATDSTZONE_PK PRIMARY KEY (SOURCE_NAT_RULE_ID, ZONE_ID));
COMMENT ON TABLE FW.CHE_SNAT_DST_ZONE IS 'MING source NAT rule to destination zone mapping table';
COMMENT ON COLUMN FW.CHE_SNAT_DST_ZONE.SOURCE_NAT_RULE_ID IS 'FK to source nat rule';
COMMENT ON COLUMN FW.CHE_SNAT_DST_ZONE.ZONE_ID IS 'FK to zone to be used as destination zone';

CREATE TABLE FW.CHE_SNAT_SRC_ZONE (SOURCE_NAT_RULE_ID NUMBER(10, 0) NOT NULL, ZONE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT CHESNATSRCZONE_PK PRIMARY KEY (SOURCE_NAT_RULE_ID, ZONE_ID));
COMMENT ON TABLE FW.CHE_SNAT_SRC_ZONE IS 'MING source NAT rule to source zone mapping table';
COMMENT ON COLUMN FW.CHE_SNAT_SRC_ZONE.SOURCE_NAT_RULE_ID IS 'FK to source nat rule';
COMMENT ON COLUMN FW.CHE_SNAT_SRC_ZONE.ZONE_ID IS 'FK to zone to be used as source zone';

CREATE TABLE FW.EXTERNAL_IP_LIST (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, COMPANY_ID NUMBER(10, 0), DESCRIPTION VARCHAR2(1024 BYTE), COMMENTS VARCHAR2(1024 BYTE), SHORT VARCHAR2(256 BYTE) NOT NULL, CONSTRAINT EXTERNALIPLIST_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.EXTERNAL_IP_LIST IS 'Ming external ip list';

CREATE TABLE FW.ICMPV6_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, CONSTRAINT ICMPV6TYPE_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.ICMPV6_TYPE IS 'value table for ICMPv6 type codes and names';

CREATE TABLE FW.ICMP_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, CONSTRAINT ICMPTYPE_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.ICMP_TYPE IS 'value table for ICMP type codes and names';

CREATE TABLE FW.IP_GROUP_MEMBER (ID NUMBER(10, 0) NOT NULL, IP_GROUP_ID NUMBER(10, 0) NOT NULL, MEMBER_TYPE_ID NUMBER(10, 0) NOT NULL, MEMBER_USAGE_ID NUMBER(10, 0) NOT NULL, SUBTRACT NUMBER(1, 0) NOT NULL, HOST_ID NUMBER(10, 0), INTERFACE_ID NUMBER(10, 0), NETWORK_ID NUMBER(10, 0), IP_ADDRESS_ID NUMBER(10, 0), MEMBER_IP_GROUP_ID NUMBER(10, 0), IPV6_ADDRESS_ID NUMBER(10, 0), IPV6_PREFIX_ID NUMBER(10, 0), SCOPED_IP_GROUP_MEMBER_ID NUMBER(10, 0), INTERFACE_ADDRESS_ID NUMBER(10, 0), DNS_OBJECT_ID NUMBER(10, 0), EXTERNAL_IP_LIST_ID NUMBER(10, 0), CONSTRAINT IPGROUPMEMBER_PK PRIMARY KEY (ID));
COMMENT ON COLUMN FW.IP_GROUP_MEMBER.SCOPED_IP_GROUP_MEMBER_ID IS 'FK to a scoped IP group member (if IP group should contain a scoped IP group)';
COMMENT ON COLUMN FW.IP_GROUP_MEMBER.INTERFACE_ADDRESS_ID IS 'FK to a IPv6 Interface Address';
COMMENT ON COLUMN FW.IP_GROUP_MEMBER.DNS_OBJECT_ID IS 'FK to a DNS Object';

CREATE TABLE FW.IP_GROUP_MEMBER_BACKUP (ID NUMBER(10, 0) NOT NULL, IP_GROUP_ID NUMBER(10, 0) NOT NULL, MEMBER_TYPE_ID NUMBER(10, 0) NOT NULL, MEMBER_USAGE_ID NUMBER(10, 0) NOT NULL, SUBTRACT NUMBER(1, 0) NOT NULL, HOST_ID NUMBER(10, 0), INTERFACE_ID NUMBER(10, 0), NETWORK_ID NUMBER(10, 0), IP_ADDRESS_ID NUMBER(10, 0), MEMBER_IP_GROUP_ID NUMBER(10, 0), HOST_GROUP_ID NUMBER(10, 0), IPV6_ADDRESS_ID NUMBER(10, 0), IPV6_PREFIX_ID NUMBER(10, 0), SCOPED_IP_GROUP_MEMBER_ID NUMBER(10, 0), INTERFACE_ADDRESS_ID NUMBER(10, 0), DNS_OBJECT_ID NUMBER(10, 0), EXTERNAL_IP_LIST_ID NUMBER(10, 0));

CREATE TABLE FW.IP_PROTOCOL (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, CONSTRAINT IPPROTOCOL_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.IP_PROTOCOL IS 'Value table for IP protocol numbers and names';

CREATE TABLE FW.IP_SERVICE2TCP_FLAG (IP_SERVICE_ID NUMBER(10, 0) NOT NULL, TCP_FLAG_ID NUMBER(10, 0) NOT NULL, CONSTRAINT IPSERVICE2TCPFLAG_PK PRIMARY KEY (IP_SERVICE_ID, TCP_FLAG_ID));
COMMENT ON TABLE FW.IP_SERVICE2TCP_FLAG IS 'link from ip_service to tcp_flag; multiple connections mean ''AND''';

CREATE TABLE FW.LOG_TARGET (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, CONSTRAINT LOGTARGET_PK PRIMARY KEY (ID));

CREATE TABLE FW.MAINTAINED_OBJECTS (ID NUMBER NOT NULL, SYNC_NAME VARCHAR2(255 BYTE) NOT NULL, PROCESS VARCHAR2(255 BYTE) NOT NULL, LAST_SYNCHRONIZED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, LAST_SYNC_TICKET_ID NUMBER(11, 0), CONSTRAINT PK_MAINTAINED_OBJECTS PRIMARY KEY (ID));
COMMENT ON TABLE FW.MAINTAINED_OBJECTS IS 'Stores data about one collection of maintained shared objects (like a QuickID app and an IP group), in relation to their maintenance process.';
COMMENT ON COLUMN FW.MAINTAINED_OBJECTS.SYNC_NAME IS 'An identifier for the maintained objects, owned by the maintenance process.';
COMMENT ON COLUMN FW.MAINTAINED_OBJECTS.PROCESS IS 'The name of the maintenance process to which the maintained objects belong.';
COMMENT ON COLUMN FW.MAINTAINED_OBJECTS.LAST_SYNCHRONIZED IS 'Last successful synchronization. This does not imply that the maintained objects were changed.';
COMMENT ON COLUMN FW.MAINTAINED_OBJECTS.LAST_SYNC_TICKET_ID IS 'The ticket ID associated with the last successful synchronization.';

CREATE TABLE FW.MAINTAINED_OBJECTS2APP (APP_ID NUMBER(11, 0) NOT NULL, MAINTAINED_OBJECTS_ID NUMBER(11, 0) NOT NULL, CONSTRAINT PK_MAINTOBJS2APP PRIMARY KEY (APP_ID, MAINTAINED_OBJECTS_ID));
COMMENT ON TABLE FW.MAINTAINED_OBJECTS2APP IS 'Associates an application with with one collection of maintained objects.';

CREATE TABLE FW.MAINTAINED_OBJECTS2IP_GROUP (IP_GROUP_ID NUMBER(11, 0) NOT NULL, MAINTAINED_OBJECTS_ID NUMBER(11, 0) NOT NULL, CONSTRAINT PK_MAINTOBJS2IPGROUP PRIMARY KEY (IP_GROUP_ID, MAINTAINED_OBJECTS_ID));
COMMENT ON TABLE FW.MAINTAINED_OBJECTS2IP_GROUP IS 'Associates an IP group with one collection of maintained objects.';

CREATE TABLE FW.MAINTAINED_OBJECTS2SRV_GROUP (SERVICE_GROUP_ID NUMBER(11, 0) NOT NULL, MAINTAINED_OBJECTS_ID NUMBER(11, 0) NOT NULL, CONSTRAINT PK_MAINTOBJS2SRGROUP PRIMARY KEY (SERVICE_GROUP_ID, MAINTAINED_OBJECTS_ID));
COMMENT ON TABLE FW.MAINTAINED_OBJECTS2SRV_GROUP IS 'Associates a service group with one collection of maintained objects.';

CREATE TABLE FW.MEMBER_TYPE (ID NUMBER(10, 0) NOT NULL, TABLE_NAME VARCHAR2(64 BYTE) NOT NULL, JAVA_CLASS_NAME VARCHAR2(128 BYTE) NOT NULL, DEFAULT_USAGE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT MEMBERTYPE_PK PRIMARY KEY (ID));

CREATE TABLE FW.MEMBER_USAGE (ID NUMBER(10, 0) NOT NULL, MEMBER_TYPE_ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, JAVA_RESOLVE_PROPERTY VARCHAR2(255 BYTE) NOT NULL, JAVA_DISPLAY_PROPERTY VARCHAR2(255 BYTE) NOT NULL, ICON_NAME VARCHAR2(32 BYTE) NOT NULL, DESCRIPTION VARCHAR2(512 BYTE), SUBTRACTABLE NUMBER(1, 0) NOT NULL, CONSTRAINT MEMBERUSAGE_PK PRIMARY KEY (ID));

CREATE TABLE FW.NAT_ACTION (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(20 BYTE) NOT NULL, DESCRIPTION VARCHAR2(200 BYTE) NOT NULL, CONSTRAINT NATACTION_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.NAT_ACTION IS 'Value table for NAT rule actions';

CREATE TABLE FW.NAT_SECTION_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, DIRECTION VARCHAR2(10 BYTE) NOT NULL, DESCRIPTION VARCHAR2(200 BYTE), CONSTRAINT NATSECTIONTYPE_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.NAT_SECTION_TYPE IS 'Value table for NAT section types';

CREATE TABLE FW.RECENT_POLICY (ID NUMBER(10, 0) NOT NULL, POLICY_ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0), CONTACT_ID NUMBER(10, 0) NOT NULL, TIME TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT RECENTPOLICY_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.RECENT_POLICY IS 'Contains all recently openened MING policies';
COMMENT ON COLUMN FW.RECENT_POLICY.POLICY_ID IS 'The policy that was opened';
COMMENT ON COLUMN FW.RECENT_POLICY.SERVICE_ID IS 'The service that this policy was opened for. May be null';
COMMENT ON COLUMN FW.RECENT_POLICY.CONTACT_ID IS 'The contact that opened the policy';
COMMENT ON COLUMN FW.RECENT_POLICY.TIME IS 'timestamp of the event';

CREATE TABLE FW.SCOPED_IP_GROUP_MEMBER_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, DESCRIPTION VARCHAR2(200 BYTE) NOT NULL, CONSTRAINT SCOPEDIPGROUPMEMBERTYPE_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.SCOPED_IP_GROUP_MEMBER_TYPE IS '#MING';
COMMENT ON COLUMN FW.SCOPED_IP_GROUP_MEMBER_TYPE.NAME IS 'name of the scope type';
COMMENT ON COLUMN FW.SCOPED_IP_GROUP_MEMBER_TYPE.DESCRIPTION IS 'description for this scope type';

CREATE TABLE FW.SCOPED_IP_GROUP_SCOPE (ID NUMBER(10, 0) NOT NULL, SCOPED_IP_GROUP_ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0) NOT NULL, IP_GROUP_ID NUMBER(10, 0) NOT NULL, CONSTRAINT SCOPEDIPGROUPSCOPE_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.SCOPED_IP_GROUP_SCOPE IS '#MING';
COMMENT ON COLUMN FW.SCOPED_IP_GROUP_SCOPE.SCOPED_IP_GROUP_ID IS 'FK to the parent scoped ip group';
COMMENT ON COLUMN FW.SCOPED_IP_GROUP_SCOPE.SERVICE_ID IS 'FK to the service that defines the scope';
COMMENT ON COLUMN FW.SCOPED_IP_GROUP_SCOPE.IP_GROUP_ID IS 'FK to the actual IP group defined for this scope (IP group has automatic set to 1 in such a case)';

CREATE TABLE FW.SERVICE_GROUP2IP_SERVICE (SERVICE_GROUP_ID NUMBER(10, 0) NOT NULL, IP_SERVICE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT SERVICEGROUP2IPSERVICE_PK PRIMARY KEY (SERVICE_GROUP_ID, IP_SERVICE_ID));

CREATE TABLE FW.SERVICE_GROUP2SERVICE_GROUP (PARENT_ID NUMBER(10, 0) NOT NULL, CHILD_ID NUMBER(10, 0) NOT NULL, CONSTRAINT SERVICEGROUP2SERVICEGROUP_PK PRIMARY KEY (PARENT_ID, CHILD_ID));

CREATE TABLE FW.SUB_SECTION (ID NUMBER(10, 0) NOT NULL, SECTION_ID NUMBER(10, 0), SOURCE_SERVICE_ID NUMBER(10, 0), SUB_SECTION_TYPE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT SUBSECTION_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.SUB_SECTION IS '#MING Holds the actual rules of a policy. Their ordering is derived from the semantics of the type,
	    cf. above, and within a type on the natural ordering of the involved host/service names.';
COMMENT ON COLUMN FW.SUB_SECTION.SECTION_ID IS 'FK to the parent section, null for section of type host_* and external';
COMMENT ON COLUMN FW.SUB_SECTION.SOURCE_SERVICE_ID IS 'installation target, NULL if global';
COMMENT ON COLUMN FW.SUB_SECTION.SUB_SECTION_TYPE_ID IS 'FK to subsection type';

CREATE TABLE FW.SUB_SECTION_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), CONSTRAINT SUBSECTIONTYPE_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.SUB_SECTION_TYPE IS '#MING Defines the various types of subsections.';
COMMENT ON COLUMN FW.SUB_SECTION_TYPE.NAME IS 'Name of the host section type';
COMMENT ON COLUMN FW.SUB_SECTION_TYPE.DESCRIPTION IS 'Description';

CREATE TABLE FW.TCP_FLAG (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, CONSTRAINT TCPFLAG_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.TCP_FLAG IS 'Value table for TCP flags';

CREATE TABLE FW.ZONE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), COMPANY_ID NUMBER(10, 0), CONSTRAINT ZONE_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.ZONE IS 'Holds the definition of a zone for MING. As these zones are globally defined or at company level,
      they are managed in MCA2 and not in MING itself. A zone figures as source or destination of a section.';
COMMENT ON COLUMN FW.ZONE.NAME IS 'name of the zone';
COMMENT ON COLUMN FW.ZONE.DESCRIPTION IS 'description of the zone';
COMMENT ON COLUMN FW.ZONE.COMPANY_ID IS 'FK to company or NULL if global, predefined zone';

CREATE TABLE FW.ZONE_MEMBER (ID NUMBER(10, 0) NOT NULL, ZONE_ID NUMBER(10, 0) NOT NULL, INTERFACE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT ZONEMEMBER_PK PRIMARY KEY (ID));
COMMENT ON TABLE FW.ZONE_MEMBER IS '#MING Defines the members, i.e. the interfaces that are in a zone (managed in MCA2).';
COMMENT ON COLUMN FW.ZONE_MEMBER.ZONE_ID IS 'FK to FW.ZONE';
COMMENT ON COLUMN FW.ZONE_MEMBER.INTERFACE_ID IS 'FK to MSS.INTERFACE';

CREATE TABLE FYI."#JDO_PROPERTIES" (KEY VARCHAR2(400 BYTE) NOT NULL, VALUE VARCHAR2(400 BYTE) DEFAULT 'none', CONSTRAINT JDO_PROPERTIES_PK PRIMARY KEY (KEY));

