CREATE TABLE FYI.FILTER_SUBJECT_REGEX (ID NUMBER(10, 0) NOT NULL, SUBSCRIPTION_ID NUMBER(10, 0) NOT NULL, SUBJECT_REGEX VARCHAR2(4000 BYTE) NOT NULL, CONSTRAINT FILTERSUBJECTREGEX_PK PRIMARY KEY (ID));

