CREATE TABLE FYI.SUBSCRIPTION_BAK_20250714 (ID NUMBER(10, 0) NOT NULL, NOTIFICATION_TYPE_ID NUMBER(10, 0) NOT NULL, CONTACT_ID NUMBER(10, 0) NOT NULL, TOPIC_GROUP_ID NUMBER(10, 0) NOT NULL, TOPIC_ID NUMBER(10, 0), COMMENTS VARCHAR2(4000 BYTE));

CREATE TABLE FYI.TARGET_NAME (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE), CONSTRAINT TARGETNAME_PK PRIMARY KEY (ID));

