CREATE TABLE GUMA2."#JDO_PROPERTIES" (KEY VARCHAR2(400 BYTE) NOT NULL, VALUE VARCHAR2(400 BYTE) DEFAULT 'none', CONSTRAINT JDO_PROPERTIES_PK PRIMARY KEY (KEY));

CREATE TABLE GUMA2.EXTERNAL_SENSOR (ID NUMBER(10, 0) NOT NULL, MONITOREDHOST_INTERFACE_ID NUMBER(10, 0) NOT NULL, SENSORHOST_INTERFACE_ID NUMBER(10, 0) NOT NULL, SENSOR_TYPE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT EXTERNALSENSOR_PK PRIMARY KEY (ID));
COMMENT ON COLUMN GUMA2.EXTERNAL_SENSOR.MONITOREDHOST_INTERFACE_ID IS 'Interface of host to be monitored by the sensor host';
COMMENT ON COLUMN GUMA2.EXTERNAL_SENSOR.SENSORHOST_INTERFACE_ID IS 'Interface of the sensor host from where the monitored host is monitored';
COMMENT ON COLUMN GUMA2.EXTERNAL_SENSOR.SENSOR_TYPE_ID IS 'Type of monitoring by the sensor host (e.g. syslog, snmp)';

