CREATE TABLE GUMA2.SENSOR_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, DESCRIPTION VARCHAR2(256 BYTE) NOT NULL, CONSTRAINT SENSORTYPE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN GUMA2.SENSOR_TYPE.NAME IS 'Name of the sensor type, explaining the monitoring protocol/technology';
COMMENT ON COLUMN GUMA2.SENSOR_TYPE.DESCRIPTION IS 'More descriptive explanation of the sensor type';

CREATE TABLE GUMA2.SYSLOG_FACILITY (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, DESCRIPTION VARCHAR2(256 BYTE) NOT NULL, CONSTRAINT SYSLOGFACILITY_PK PRIMARY KEY (ID));

CREATE TABLE GUMA2.SYSLOG_MESSAGE_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, CONSTRAINT SYSLOGMESSAGETYPE_PK PRIMARY KEY (ID));
