COMMENT ON COLUMN GUMA2.SYSLOG_MESSAGE_TYPE.NAME IS 'The name of the type';

CREATE TABLE GUMA2.SYSLOG_SEVERITY (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, DESCRIPTION VARCHAR2(256 BYTE) NOT NULL, CONSTRAINT SYSLOGSEVERITY_PK PRIMARY KEY (ID));

CREATE TABLE MAIL."#JDO_PROPERTIES" (KEY VARCHAR2(400 BYTE) NOT NULL, VALUE VARCHAR2(400 BYTE) DEFAULT 'none', CONSTRAINT JDO_PROPERTIES_PK PRIMARY KEY (KEY));

CREATE TABLE MAIL.BATV_KEY (ID NUMBER(10, 0) NOT NULL, KEY_NUMBER NUMBER(10, 0) NOT NULL, KEY VARCHAR2(4000 BYTE) NOT NULL, SERVICE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT BATVKEY_PK PRIMARY KEY (ID));
COMMENT ON TABLE MAIL.BATV_KEY IS 'Key storage for Backscatter Protection (using Bounce Address Tag Validation)';

CREATE TABLE MAIL.CUSTOM_POLICY_LIST (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(500 BYTE) NOT NULL, DISPLAY_NAME VARCHAR2(2000 BYTE) NOT NULL, DESCRIPTION VARCHAR2(2000 BYTE), COMPANY_ID NUMBER(10, 0) NOT NULL, POLICY_LIST_VALUE_TYPE_ID NUMBER(10, 0), IS_SELF_PROVISIONED NUMBER(1, 0) DEFAULT 0 NOT NULL, IS_AUTO_CREATED NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT CUSTOMPOLICYLIST_PK PRIMARY KEY (ID));

CREATE TABLE MAIL.CUSTOM_POLICY_LIST_VALUE (ID NUMBER(10, 0) NOT NULL, CUSTOM_POLICY_LIST_ID NUMBER(10, 0) NOT NULL, VALUE VARCHAR2(2000 BYTE) NOT NULL, DESCRIPTION VARCHAR2(2000 BYTE), LAST_MODIFIED_TIME TIMESTAMP(6) WITH TIME ZONE NOT NULL, LAST_MODIFIED_CONTACT_ID NUMBER(10, 0) NOT NULL, TICKET_ID NUMBER(10, 0), CUSTOMER_REFERENCE VARCHAR2(64 BYTE), CONSTRAINT CUSTOMPOLICYLISTVALUE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MAIL.CUSTOM_POLICY_LIST_VALUE.LAST_MODIFIED_TIME IS 'The time when the entry was updated the last time';
COMMENT ON COLUMN MAIL.CUSTOM_POLICY_LIST_VALUE.LAST_MODIFIED_CONTACT_ID IS 'The contact that updated the entry the last time';
COMMENT ON COLUMN MAIL.CUSTOM_POLICY_LIST_VALUE.CUSTOMER_REFERENCE IS 'A reference to the customer''s incident/ticketing system';

CREATE TABLE MAIL.DKIM_KEY (ID NUMBER(10, 0) NOT NULL, SELECTOR VARCHAR2(100 BYTE) NOT NULL, PUBLIC_KEY VARCHAR2(4000 BYTE) NOT NULL, DKIM_KEY_STATE_ID NUMBER(10, 0) NOT NULL, DOMAIN_ID NUMBER(10, 0) NOT NULL, GENERATE_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, PUBLISH_DATE TIMESTAMP(6) WITH TIME ZONE, ACTIVATE_DATE TIMESTAMP(6) WITH TIME ZONE, RETIRE_DATE TIMESTAMP(6) WITH TIME ZONE, REVOKE_DATE TIMESTAMP(6) WITH TIME ZONE, REMOVE_DATE TIMESTAMP(6) WITH TIME ZONE, CONSTRAINT DKIMKEY_PK PRIMARY KEY (ID));

CREATE TABLE MAIL.DKIM_KEY_STATE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(50 BYTE) NOT NULL, CONSTRAINT DKIMKEYSTATE_PK PRIMARY KEY (ID));

CREATE TABLE MAIL.DKIM_PRIVATE_KEY (DKIM_KEY_ID NUMBER(10, 0) NOT NULL, PRIVATE_KEY VARCHAR2(4000 BYTE) NOT NULL, CONSTRAINT DKIMPRIVATEKEY_PK PRIMARY KEY (DKIM_KEY_ID));

