CREATE TABLE MAIL.DMARC_SPF_RESULT (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(20 BYTE) NOT NULL, CONSTRAINT DMARCSPFRESULT_PK PRIMARY KEY (ID));

