CREATE TABLE MAIL.POLICY_LIST_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(500 BYTE) NOT NULL, CONSTRAINT POLICYLISTTYPE_PK PRIMARY KEY (ID));

