COMMENT ON COLUMN MAIL.POLICY_LIST_VALUE.LAST_MODIFIED_TIME IS 'The time when the entry was updated the last time';
COMMENT ON COLUMN MAIL.POLICY_LIST_VALUE.LAST_MODIFIED_CONTACT_ID IS 'The contact that updated the entry the last time';
COMMENT ON COLUMN MAIL.POLICY_LIST_VALUE.CUSTOMER_REFERENCE IS 'A reference to the customer''s incident/ticketing system';

CREATE TABLE MAIL.POLICY_LIST_VALUE_2_GROUP (POLICY_LIST_VALUE_ID NUMBER(10, 0) NOT NULL, USER_GROUP_ID NUMBER(10, 0) NOT NULL, CONSTRAINT POLICYLISTVALUE2GROUP_PK PRIMARY KEY (POLICY_LIST_VALUE_ID, USER_GROUP_ID));

CREATE TABLE MAIL.POLICY_LIST_VALUE_2_TAG (POLICY_LIST_VALUE_ID NUMBER(10, 0) NOT NULL, POLICY_LIST_TAG_ID NUMBER(10, 0) NOT NULL, CONSTRAINT POLICYLISTVALUE2TAG_PK PRIMARY KEY (POLICY_LIST_VALUE_ID, POLICY_LIST_TAG_ID));

CREATE TABLE MAIL.POLICY_LIST_VALUE_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(500 BYTE) NOT NULL, DISPLAY_NAME VARCHAR2(500 BYTE) NOT NULL, CONSTRAINT POLICYLISTVALUETYPE_PK PRIMARY KEY (ID));

CREATE TABLE MAIL.USER_GROUP (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(500 BYTE) NOT NULL, DESCRIPTION VARCHAR2(2000 BYTE), COMPANY_ID NUMBER(10, 0) NOT NULL, CONSTRAINT USERGROUP_PK PRIMARY KEY (ID));

CREATE TABLE MC."#JDO_PROPERTIES" (KEY VARCHAR2(400 BYTE) NOT NULL, VALUE VARCHAR2(400 BYTE) DEFAULT 'none', CONSTRAINT JDO_PROPERTIES_PK PRIMARY KEY (KEY));

CREATE TABLE MC.AVAILABILITY_REPORT (ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0), DELETED_SERVICE_ID NUMBER(10, 0), MONTH NUMBER(2, 0) NOT NULL, YEAR NUMBER(4, 0) NOT NULL, CONN_SLA_CLASS_ID NUMBER(10, 0), CONN_SLA_TARGET_ID NUMBER(10, 0), CONNECTIVITY_INCLUDED NUMBER(1, 0) DEFAULT 0 NOT NULL, CREATED TIMESTAMP(6) WITH TIME ZONE NOT NULL, LAST_UPDATED TIMESTAMP(6) WITH TIME ZONE NOT NULL, REPORT_STATUS_ID NUMBER(10, 0) DEFAULT 1 NOT NULL, MONITORED_TIME NUMBER(14, 0) NOT NULL, AVAILABLE_TIME NUMBER(14, 0) NOT NULL, SERVICE_DOWN_TIME NUMBER(14, 0) NOT NULL, ISP_DOWN_TIME NUMBER(14, 0) NOT NULL, MAINTENANCE_TIME NUMBER(14, 0) NOT NULL, SLA_BREACHED NUMBER(1, 0) DEFAULT 0 NOT NULL, REPORT_DATA_REFERENCE VARCHAR2(512 BYTE), SLA_AVAILABLE_TIME NUMBER(14, 0), SLA_SERVICE_DOWN_TIME NUMBER(14, 0), SLA_ISP_DOWN_TIME NUMBER(14, 0), SLA_MAINTENANCE_TIME NUMBER(14, 0), SLA_OTHER_TIME NUMBER(14, 0), CONSTRAINT AVAILABILITYREPORT_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MC.AVAILABILITY_REPORT.DELETED_SERVICE_ID IS 'Service ID of the previously assigned service, not a foreign key';
COMMENT ON COLUMN MC.AVAILABILITY_REPORT.CONN_SLA_CLASS_ID IS 'No SLA class (NULL) if the company has SLA reporting disabled';
COMMENT ON COLUMN MC.AVAILABILITY_REPORT.CONN_SLA_TARGET_ID IS 'No SLA target (NULL) stands for best effort';
COMMENT ON COLUMN MC.AVAILABILITY_REPORT.CONNECTIVITY_INCLUDED IS 'Value of MC.SERVICE_CONN_SLA_CONFIG.INCLUDE_CONNECTIVITY of the corresponding service at the time of report creation';
COMMENT ON COLUMN MC.AVAILABILITY_REPORT.REPORT_DATA_REFERENCE IS 'Where to find the cache for this report';

CREATE TABLE MC.AVAILABILITY_REPORT_STATUS (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(16 BYTE) NOT NULL, DESCRIPTION VARCHAR2(512 BYTE) NOT NULL, CONSTRAINT AVAILABILITYREPORTSTATUS_PK PRIMARY KEY (ID));

CREATE TABLE MC.CONN_SLA_CLASS (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(48 BYTE) NOT NULL, SEQ_NO NUMBER(2, 0) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, CONN_SLA_TARGET_ID NUMBER(10, 0), CONSTRAINT CONNSLACLASS_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MC.CONN_SLA_CLASS.SEQ_NO IS 'Sequence number to model a consistent sorting of the SLA classes';
COMMENT ON COLUMN MC.CONN_SLA_CLASS.CONN_SLA_TARGET_ID IS 'No SLA target (NULL) stands for best effort';

CREATE TABLE MC.CONN_SLA_TARGET (ID NUMBER(10, 0) NOT NULL, HOST_ESCALATION_TIMEOUT NUMBER(10, 0) NOT NULL, ISP_LINE_ESCALATION_TIMEOUT NUMBER(10, 0) NOT NULL, TARGET NUMBER(5, 0) NOT NULL, CONSTRAINT CONNSLATARGET_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MC.CONN_SLA_TARGET.TARGET IS 'SLA target in % multiplied by 1000 (only integers allowed between 1000 and 99999)';

CREATE TABLE MC.CON_INT_TYPE (ID NUMBER(22, 0) NOT NULL, NAME VARCHAR2(30 BYTE), DESCRIPTION VARCHAR2(200 BYTE), CONSTRAINT CONINTTYPE_PK PRIMARY KEY (ID));

CREATE TABLE MC.INTERRUPT_REVIEW_STATUS (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(16 BYTE) NOT NULL, CONSTRAINT INTERRUPTREVIEWSTATUS_PK PRIMARY KEY (ID));

CREATE TABLE MC.ISP_AVAILABILITY_REPORT (ID NUMBER(10, 0) NOT NULL, ISP_LINK_ID NUMBER(10, 0) NOT NULL, MONTH NUMBER(2, 0) NOT NULL, YEAR NUMBER(4, 0) NOT NULL, CREATED TIMESTAMP(6) WITH TIME ZONE NOT NULL, LAST_UPDATED TIMESTAMP(6) WITH TIME ZONE NOT NULL, MONITORED_TIME NUMBER(14, 0) NOT NULL, AVAILABLE_TIME NUMBER(14, 0) NOT NULL, MAINTENANCE_TIME NUMBER(14, 0) NOT NULL, DOWN_TIME NUMBER(14, 0) NOT NULL, CONSTRAINT ISPAVAILABILITYREPORT_PK PRIMARY KEY (ID));

CREATE TABLE MC.MC_FILE_TYPE (ID NUMBER(22, 0) NOT NULL, NAME VARCHAR2(256 BYTE) NOT NULL, SHARED NUMBER(1, 0) DEFAULT 0 NOT NULL, RELEASABLE NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT MCFILETYPE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MC.MC_FILE_TYPE.SHARED IS 'Flag that indicates whether the files of this type are for multiple companies or just a single one';
COMMENT ON COLUMN MC.MC_FILE_TYPE.RELEASABLE IS 'Flag that indicates whether the files of this type can be in a pre-release state or not';

CREATE TABLE MC.SERVICE_CONN_SLA_CONFIG (ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0) NOT NULL, CONN_SLA_CLASS_ID NUMBER(10, 0) NOT NULL, INCLUDE_CONNECTIVITY NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT SERVICECONNSLACONFIG_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MC.SERVICE_CONN_SLA_CONFIG.INCLUDE_CONNECTIVITY IS 'Whether to include ISP related downtime into SLA calculations or not';

CREATE TABLE MCAUDIT."#JDO_PROPERTIES" (KEY VARCHAR2(400 BYTE) NOT NULL, VALUE VARCHAR2(400 BYTE) DEFAULT 'none', CONSTRAINT JDO_PROPERTIES_PK PRIMARY KEY (KEY));

CREATE TABLE MSS."#JDO_PROPERTIES" (KEY VARCHAR2(400 BYTE) NOT NULL, VALUE VARCHAR2(400 BYTE) DEFAULT 'none', CONSTRAINT JDO_PROPERTIES_PK PRIMARY KEY (KEY));

CREATE TABLE MSS.APPLICATION (ID NUMBER(10, 0) NOT NULL, APPLICATION_GROUP_ID NUMBER(10, 0) NOT NULL, AUTHOR VARCHAR2(64 BYTE), LEARNING_PHASE NUMBER(10, 0) DEFAULT 0 NOT NULL, PROTECTED_HOST_ID NUMBER(10, 0) NOT NULL, COMMENTS VARCHAR2(1024 BYTE), CONSTRAINT APPLICATION_PK PRIMARY KEY (ID));

CREATE TABLE MSS.APPLICATION_GROUP (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, OPERATING_SYSTEM_ID NUMBER(10, 0) NOT NULL, RELEASE VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(512 BYTE) NOT NULL, CONSTRAINT APPLICATIONGROUP_PK PRIMARY KEY (ID));

CREATE TABLE MSS.APPLICATION_TEAM (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, DESCRIPTION VARCHAR2(512 BYTE), CONSTRAINT APPLICATIONTEAM_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.APPLICATION_TEAM.ID IS 'ID of the application team.';
COMMENT ON COLUMN MSS.APPLICATION_TEAM.NAME IS 'Name of the application team.';
COMMENT ON COLUMN MSS.APPLICATION_TEAM.DESCRIPTION IS 'Description of the application team.';

CREATE TABLE MSS.APPLICATION_TEAM_CONTACT (ID NUMBER(10, 0) NOT NULL, APPLICATION_TEAM_ID NUMBER(10, 0) NOT NULL, CONTACT_ID NUMBER(10, 0) NOT NULL, CONSTRAINT APPLICATIONTEAMCONTACT_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.APPLICATION_TEAM_CONTACT.ID IS 'ID of the application team contact.';
COMMENT ON COLUMN MSS.APPLICATION_TEAM_CONTACT.APPLICATION_TEAM_ID IS 'ID of the application team.';
COMMENT ON COLUMN MSS.APPLICATION_TEAM_CONTACT.CONTACT_ID IS 'ID of the contact.';

CREATE TABLE MSS.APPLICATION_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, APPLICATION_GROUP_ID NUMBER(10, 0) NOT NULL, APPLICATION_TEAM_ID NUMBER(10, 0), DESCRIPTION VARCHAR2(512 BYTE) NOT NULL, OPERATING_SYSTEM_ID NUMBER(10, 0) NOT NULL, RELEASE VARCHAR2(64 BYTE) NOT NULL, TAG VARCHAR2(64 BYTE) NOT NULL, SERVICE_COMPONENT_ID NUMBER(10, 0), CONSTRAINT APPLICATIONTYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.BLUEPRINT (ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(200 BYTE) NOT NULL, CONSTRAINT BLUEPRINT_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.BLUEPRINT.COMPANY_ID IS 'Reference to the customer company for this project.';

CREATE TABLE MSS.BLUEPRINT_ENTRY (ID NUMBER(10, 0) NOT NULL, BLUEPRINT_ID NUMBER(10, 0) NOT NULL, SERVICE_OPTION_TYPE_ID NUMBER(10, 0) NOT NULL, IS_NEW NUMBER(1, 0) DEFAULT 1 NOT NULL, ADDITIONAL NUMBER(1, 0) DEFAULT 0 NOT NULL, SCOPE NUMBER(10, 0) NOT NULL, SERVICE_LEVEL_ID NUMBER(10, 0), CONSTRAINT BLUEPRINTENTRY_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.BLUEPRINT_ENTRY.IS_NEW IS 'Denotes whether this entry is a new installation.';
COMMENT ON COLUMN MSS.BLUEPRINT_ENTRY.ADDITIONAL IS 'Denotes whether this entry is to be added to an existing installation.';
COMMENT ON COLUMN MSS.BLUEPRINT_ENTRY.SCOPE IS 'A number which denotes the scope (i.e. logical unit) for this blueprint entry.';

CREATE TABLE MSS.CAS_PORT (ID NUMBER(10, 0) NOT NULL, HOST_ID NUMBER(10, 0) NOT NULL, CAS_HOST_ID NUMBER(10, 0) NOT NULL, PORT NUMBER(3, 0), CONSTRAINT CASPORT_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.CAS_PORT.HOST_ID IS 'The host that is attached to this port';
COMMENT ON COLUMN MSS.CAS_PORT.CAS_HOST_ID IS 'The CAS server this port belongs to';
COMMENT ON COLUMN MSS.CAS_PORT.PORT IS 'The actual number of the port';

CREATE TABLE MSS.CLIENT_PROFILE_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, CONSTRAINT CLIENTPROFILETYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.CLOUD_REGION_INSTANCE (ID NUMBER(10, 0) NOT NULL, INTERNAL_CODE VARCHAR2(64 BYTE) NOT NULL, PROVIDER VARCHAR2(32 BYTE) NOT NULL, REGION VARCHAR2(32 BYTE) NOT NULL, DISPLAY_NAME VARCHAR2(200 BYTE) NOT NULL, CLUSTER_URL VARCHAR2(255 BYTE) NOT NULL, DEPRECATED NUMBER(1, 0) DEFAULT 0 NOT NULL, LATITUDE_DEGREES NUMBER(2, 0), LATITUDE_MINUTES NUMBER(2, 0), LATITUDE_SECONDS NUMBER, LATITUDE_DIRECTION VARCHAR2(1 BYTE), LONGITUDE_DEGREES NUMBER(3, 0), LONGITUDE_MINUTES NUMBER(2, 0), LONGITUDE_SECONDS NUMBER, LONGITUDE_DIRECTION VARCHAR2(1 BYTE), REGION_INTERNAL_CODE VARCHAR2(64 BYTE) NOT NULL, CITY_ID NUMBER(10, 0), REGION_INTERNAL_IP NUMBER(10, 0), CONSTRAINT CLOUDREGIONINSTANCE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.CLOUD_REGION_INSTANCE.REGION_INTERNAL_CODE IS 'Location code for use in hostnames';
COMMENT ON COLUMN MSS.CLOUD_REGION_INSTANCE.CITY_ID IS 'The city where the data center for the cloud region is located.
Knowing it allows to automatically set the address for services located in that cloud region.';

CREATE TABLE MSS.CONFIG_LIST (ID NUMBER(10, 0) NOT NULL, CONFIG_LIST_TYPE_ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0) NOT NULL, IS_SELF_PROVISIONED NUMBER(1, 0) DEFAULT 0 NOT NULL, IS_DIRTY NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT CONFIGLIST_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.CONFIG_LIST.ID IS 'The primary key';
COMMENT ON COLUMN MSS.CONFIG_LIST.CONFIG_LIST_TYPE_ID IS 'The type of this list.';
COMMENT ON COLUMN MSS.CONFIG_LIST.SERVICE_ID IS 'The service scope of this list.';
COMMENT ON COLUMN MSS.CONFIG_LIST.IS_SELF_PROVISIONED IS 'Indicates whether the entries in this list can be edited by the customer.';
COMMENT ON COLUMN MSS.CONFIG_LIST.IS_DIRTY IS 'A config list is dirty if entries of the list have been added, deleted or modified. The list becomes clean after a deployment has been scheduled for it.';

CREATE TABLE MSS.CONFIG_LIST_TYPE (ID NUMBER(10, 0) NOT NULL, CONFIG_LIST_VALUE_TYPE_ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0), NAME VARCHAR2(400 BYTE) NOT NULL, DISPLAY_NAME VARCHAR2(400 BYTE) NOT NULL, DESCRIPTION VARCHAR2(32767 BYTE) NOT NULL, CONSTRAINT CONFIGLISTTYPE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.CONFIG_LIST_TYPE.ID IS 'The primary key';
COMMENT ON COLUMN MSS.CONFIG_LIST_TYPE.CONFIG_LIST_VALUE_TYPE_ID IS 'Reference to the value type for this list type.';
COMMENT ON COLUMN MSS.CONFIG_LIST_TYPE.COMPANY_ID IS 'Reference to the company this list type belongs to.';
COMMENT ON COLUMN MSS.CONFIG_LIST_TYPE.NAME IS 'The name of this list type.';
COMMENT ON COLUMN MSS.CONFIG_LIST_TYPE.DISPLAY_NAME IS 'The display name of this list type.';

CREATE TABLE MSS.CONFIG_LIST_VALUE (ID NUMBER(10, 0) NOT NULL, CONFIG_LIST_ID NUMBER(10, 0) NOT NULL, VALUE VARCHAR2(2000 BYTE) NOT NULL, DESCRIPTION VARCHAR2(2000 BYTE), LAST_MODIFIED_TIME TIMESTAMP(6) WITH TIME ZONE NOT NULL, LAST_MODIFIED_CONTACT_ID NUMBER(10, 0) NOT NULL, CONSTRAINT CONFIGLISTVALUE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.CONFIG_LIST_VALUE.ID IS 'The primary key';
COMMENT ON COLUMN MSS.CONFIG_LIST_VALUE.CONFIG_LIST_ID IS 'The config list this value belongs to.';
COMMENT ON COLUMN MSS.CONFIG_LIST_VALUE.VALUE IS 'The value.';
COMMENT ON COLUMN MSS.CONFIG_LIST_VALUE.DESCRIPTION IS 'Comment/description of this value.';
COMMENT ON COLUMN MSS.CONFIG_LIST_VALUE.LAST_MODIFIED_TIME IS 'The last time this value was modified.';
COMMENT ON COLUMN MSS.CONFIG_LIST_VALUE.LAST_MODIFIED_CONTACT_ID IS 'The last login who modified this value.';

CREATE TABLE MSS.CONFIG_LIST_VALUE_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(400 BYTE) NOT NULL, REGEX VARCHAR2(32767 BYTE) NOT NULL, CONSTRAINT CONFIGLISTVALUETYPE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.CONFIG_LIST_VALUE_TYPE.ID IS 'The primary key';
COMMENT ON COLUMN MSS.CONFIG_LIST_VALUE_TYPE.NAME IS 'The name of this list type.';

CREATE TABLE MSS.CURRENCY (ID NUMBER(10, 0) NOT NULL, SHORT VARCHAR2(8 BYTE) NOT NULL, CONSTRAINT CURRENCY_PK PRIMARY KEY (ID));

CREATE TABLE MSS.CVPN_DHCP_SERVER (ID NUMBER(10, 0) NOT NULL, CVPN_POOL_ID NUMBER(10, 0) NOT NULL, IP_ADDRESS NUMBER(10, 0) NOT NULL, CONSTRAINT CVPNDHCPSERVER_PK PRIMARY KEY (ID));

CREATE TABLE MSS.CVPN_DNS_CONFIG (ID NUMBER(10, 0) NOT NULL, DNS_SERVER_ADDR_IPV4 VARCHAR2(50 BYTE), DNS_SERVER_SECONDARY_ADDR_IPV4 VARCHAR2(50 BYTE), DNS_SERVER_ADDR_IPV6 VARCHAR2(50 BYTE), DNS_SERVER_SECONDARY_ADDR_IPV6 VARCHAR2(50 BYTE), DNS_SEARCH_DOMAIN VARCHAR2(255 BYTE), CONSTRAINT CVPNDNSCONFIG_PK PRIMARY KEY (ID));

CREATE TABLE MSS.CVPN_GROUP (ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, TUNNELGROUP_ID NUMBER(10, 0), CVPN_GROUP_DNS_TYPE_ID NUMBER(10, 0) NOT NULL, DNS_SEARCH_DOMAIN_TYPE_ID NUMBER(10, 0) NOT NULL, CVPN_DNS_CONFIG_ID NUMBER(10, 0), CVPN_GROUP_PROXY_TYPE_ID NUMBER(10, 0) NOT NULL, CVPN_PROXY_CONFIG_ID NUMBER(10, 0), SPLIT_TUNNELING_TYPE_ID NUMBER(10, 0) NOT NULL, CLIENT_PROFILE_TYPE_ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(50 BYTE) NOT NULL, DESCRIPTION VARCHAR2(255 BYTE), PROXY_LOCKDOWN NUMBER(1, 0) DEFAULT 0 NOT NULL, LOCAL_LAN_ACCESS NUMBER(1, 0) DEFAULT 0 NOT NULL, SPECIFIC_CLIENT_PROFILE VARCHAR2(64 BYTE), SAML_GROUP_ID VARCHAR2(255 BYTE), IS_ZTNA_COMPATIBLE NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT CVPNGROUP_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.CVPN_GROUP.IS_ZTNA_COMPATIBLE IS 'ZTNA-1118: Introduce Field for concurrent use with ZTNA';

CREATE TABLE MSS.CVPN_GROUP_2_APP (CVPN_GROUP_ID NUMBER(11, 0) NOT NULL, APP_ID NUMBER(11, 0) NOT NULL, CONSTRAINT CVPNGROUP2APP_PK PRIMARY KEY (CVPN_GROUP_ID, APP_ID));

CREATE TABLE MSS.CVPN_GROUP_DNS_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, CONSTRAINT CVPNGROUPDNSTYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.CVPN_GROUP_PROXY_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, CONSTRAINT CVPNGROUPPROXYTYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.CVPN_POOL (ID NUMBER(10, 0) NOT NULL, CVPN_GROUP_ID NUMBER(10, 0) NOT NULL, CVPN_SERVICE_ID NUMBER(10, 0) NOT NULL, NETWORK_ID NUMBER(10, 0) NOT NULL, DHCP_NETWORK_ID NUMBER(10, 0), CONSTRAINT CVPNPOOL_PK PRIMARY KEY (ID));

CREATE TABLE MSS.CVPN_PROXY_CONFIG (ID NUMBER(10, 0) NOT NULL, ADDRESS VARCHAR2(255 BYTE), PORT NUMBER(5, 0), PAC_URL VARCHAR2(255 BYTE), CONSTRAINT CVPNPROXYCONFIG_PK PRIMARY KEY (ID));

CREATE TABLE MSS.CVPN_PROXY_EXCEPTION (ID NUMBER(10, 0) NOT NULL, CVPN_PROXY_CONFIG_ID NUMBER(10, 0) NOT NULL, ADDRESS VARCHAR2(255 BYTE) NOT NULL, CONSTRAINT CVPNPROXYEXCEPTION_PK PRIMARY KEY (ID));

CREATE TABLE MSS.CVPN_SERVICE (ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0) NOT NULL, CVPN_SERVICE_DNS_TYPE_ID NUMBER(10, 0) NOT NULL, CVPN_DNS_CONFIG_ID NUMBER(10, 0), CVPN_SERVICE_PROXY_TYPE_ID NUMBER(10, 0) NOT NULL, CVPN_PROXY_CONFIG_ID NUMBER(10, 0), DEFAULT_IPV4_NETWORK_PREFIX VARCHAR2(50 BYTE), DEFAULT_IPV6_NETWORK_PREFIX VARCHAR2(50 BYTE), CONSTRAINT CVPNSERVICE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.CVPN_SERVICE_DNS_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, CONSTRAINT CVPNSERVICEDNSTYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.CVPN_SERVICE_PROXY_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, CONSTRAINT CVPNSERVICEPROXYTYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.CVPN_SPLIT_TUNNELING_ROUTE (ID NUMBER(10, 0) NOT NULL, CVPN_GROUP_ID NUMBER(10, 0) NOT NULL, ROUTE_ADDRESS VARCHAR2(50 BYTE) NOT NULL, DESCRIPTION VARCHAR2(255 BYTE), CONSTRAINT CVPNSPLITTUNNELINGROUTE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.DECOMM_HOST (ID NUMBER(10, 0) NOT NULL, CREATION_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, CREATION_CONTACT_ID NUMBER(10, 0), HOST_ID NUMBER(10, 0), DISPLAY_COMPANY VARCHAR2(10 BYTE) NOT NULL, DISPLAY_HOST VARCHAR2(32 BYTE) NOT NULL, APPROVAL_DATE TIMESTAMP(6) WITH TIME ZONE, APPROVAL_CONTACT_ID NUMBER(10, 0), STATUS_ID NUMBER(10, 0) NOT NULL, COMPLETION_DATE TIMESTAMP(6) WITH TIME ZONE, TICKET_TRANSFER_HOST_ID NUMBER(10, 0), ORIGINAL_SERVICE_ID NUMBER(10, 0), REPATRIATE_HW NUMBER(1, 0) NOT NULL, CONSTRAINT DECOMMHOST_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.DECOMM_HOST.ID IS 'The primary key';
COMMENT ON COLUMN MSS.DECOMM_HOST.CREATION_DATE IS 'The time stamp when the request was created';
COMMENT ON COLUMN MSS.DECOMM_HOST.CREATION_CONTACT_ID IS 'The login id that was used to create the request';
COMMENT ON COLUMN MSS.DECOMM_HOST.HOST_ID IS 'The host to decommission. Null when the request is COMPLETED|FAILED|REJECTED';
COMMENT ON COLUMN MSS.DECOMM_HOST.DISPLAY_COMPANY IS 'Text for the company short that allows identification after all host information is gone. Used for display.';
COMMENT ON COLUMN MSS.DECOMM_HOST.DISPLAY_HOST IS 'Text for the host name that allows identification after all host information is gone. Used for display.';
COMMENT ON COLUMN MSS.DECOMM_HOST.APPROVAL_DATE IS 'The timestamp when the request was approved/rejected. Null when not yet approved/rejected.';
COMMENT ON COLUMN MSS.DECOMM_HOST.APPROVAL_CONTACT_ID IS 'The login id that was used to approve/decline the request. Null when not yet approved/rejected.';
COMMENT ON COLUMN MSS.DECOMM_HOST.COMPLETION_DATE IS 'Point in time when the entry reached its final state (COMPLETED, FAILED, REJECTED). Null when not yet reached.';
COMMENT ON COLUMN MSS.DECOMM_HOST.TICKET_TRANSFER_HOST_ID IS 'Host where the Tickers should be transferred to. May be null when no transfer is needed. Always null when the status is COMPLETED|FAILED|REJECTED.';
COMMENT ON COLUMN MSS.DECOMM_HOST.ORIGINAL_SERVICE_ID IS 'Service where the host was attached before the process started. Null if the status is FAILED, REJECTED or COMPLETED.';
COMMENT ON COLUMN MSS.DECOMM_HOST.REPATRIATE_HW IS 'True if hw should be repatriated. If false the hw is marked for disposal during decommissioning.';

CREATE TABLE MSS.DECOMM_STATUS (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE) NOT NULL, CONSTRAINT DECOMMSTATUS_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.DECOMM_STATUS.ID IS 'The primary key';

CREATE TABLE MSS.DELETED_HOST (ID NUMBER(10, 0) NOT NULL, DELETION_DATE TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, HOST_ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0) NOT NULL, SERVICE_TYPE_ID NUMBER(10, 0) NOT NULL, ADDRESS VARCHAR2(512 BYTE), CITY_ID NUMBER(10, 0), COMPANY_ID NUMBER(10, 0) NOT NULL, COMPANY_SHORT VARCHAR2(10 BYTE) NOT NULL, COMMENTS VARCHAR2(1024 BYTE), DESCRIPTION VARCHAR2(128 BYTE), HARDWARE_ID NUMBER(10, 0), CONSTRAINT DELETEDHOST_PK PRIMARY KEY (ID));

CREATE TABLE MSS.DNSSEC_ALGORITHM (ID NUMBER(10, 0) NOT NULL, DESCRIPTION VARCHAR2(256 BYTE) NOT NULL, MNEMONIC VARCHAR2(256 BYTE) NOT NULL, CONSTRAINT DNSSECALGORITHM_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.DNSSEC_ALGORITHM IS 'Describes Domain Name System Security (DNSSEC) Algorithm Numbers.
        See also:
        http://www.iana.org/assignments/dns-sec-alg-numbers/dns-sec-alg-numbers.xhtml';

CREATE TABLE MSS.DNSSEC_KEY (ID NUMBER(10, 0) NOT NULL, TAG NUMBER(6, 0) NOT NULL, KEY_TYPE_ID NUMBER(1, 0) NOT NULL, KEY_STATE_ID NUMBER(10, 0) NOT NULL, DNS_ZONE_ID NUMBER(10, 0), COMPANY_ID NUMBER(10, 0) NOT NULL, PUBLIC_KEY VARCHAR2(4000 BYTE) NOT NULL, GENERATE_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, PUBLISH_DATE TIMESTAMP(6) WITH TIME ZONE, ACTIVATE_DATE TIMESTAMP(6) WITH TIME ZONE, RETIRE_DATE TIMESTAMP(6) WITH TIME ZONE, REVOKE_DATE TIMESTAMP(6) WITH TIME ZONE, REMOVE_DATE TIMESTAMP(6) WITH TIME ZONE, DS_ACTIVATE_DATE TIMESTAMP(6) WITH TIME ZONE, ALGORITHM_ID NUMBER(10, 0) NOT NULL, CONSTRAINT DNSSECKEY_PK PRIMARY KEY (ID));

CREATE TABLE MSS.DNSSEC_KEY_DIGEST (ID NUMBER(10, 0) NOT NULL, DNSSEC_KEY_ID NUMBER(10, 0) NOT NULL, DNSSEC_KEY_DIGEST_TYPE_ID NUMBER(10, 0) NOT NULL, DIGEST VARCHAR2(1000 BYTE) NOT NULL, CONSTRAINT DNSSECKEYDIGEST_PK PRIMARY KEY (ID));

CREATE TABLE MSS.DNSSEC_KEY_DIGEST_TYPE (ID NUMBER(10, 0) NOT NULL, DESCRIPTION VARCHAR2(256 BYTE) NOT NULL, CONSTRAINT DNSSECKEYDIGESTTYPE_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.DNSSEC_KEY_DIGEST_TYPE IS 'Describes Delegation Signer (DS) Resource Record (RR) Type
        Digest Algorithms used for DNSSEC. See also:
        http://www.iana.org/assignments/ds-rr-types/ds-rr-types.xhtml';

CREATE TABLE MSS.DNSSEC_KEY_STATE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(12 BYTE) NOT NULL, CONSTRAINT DNSSECKEYSTATE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.DNSSEC_KEY_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(12 BYTE) NOT NULL, CONSTRAINT DNSSECKEYTYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.DNSSEC_PRIVATE_KEY (DNSSEC_KEY_ID NUMBER(10, 0) NOT NULL, PRIVATE_KEY VARCHAR2(4000 BYTE) NOT NULL, CONSTRAINT DNSSECPRIVATEKEY_PK PRIMARY KEY (DNSSEC_KEY_ID));

CREATE TABLE MSS.DNS_RECORD (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(2000 BYTE), TYPE VARCHAR2(10 BYTE) NOT NULL, DATA VARCHAR2(4000 BYTE) NOT NULL, TTL NUMBER(10, 0), DNS_ZONE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT DNSRECORD_PK PRIMARY KEY (ID));

CREATE TABLE MSS.DNS_SEARCH_DOMAIN_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, CONSTRAINT DNSSEARCHDOMAINTYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.DNS_ZONE (ID NUMBER(10, 0) NOT NULL, DOMAIN VARCHAR2(1024 BYTE) NOT NULL, DNS_ZONE_GROUP_ID NUMBER(10, 0) NOT NULL, SOA_ADMIN_EMAIL VARCHAR2(50 BYTE), SOA_DEFAULT_TTL NUMBER(10, 0), SOA_EXPIRE NUMBER(10, 0), SOA_MINIMUM_TTL NUMBER(10, 0), SOA_PRIMARY_NAMESERVER VARCHAR2(2000 BYTE), SOA_REFRESH NUMBER(10, 0), SOA_RETRY NUMBER(10, 0), DIRTY NUMBER(1, 0) DEFAULT 0 NOT NULL, SERIAL_NO NUMBER(10, 0), DNSSEC NUMBER(1, 0), DNSSEC_NSEC3_SALT VARCHAR2(257 BYTE), ZONEFILE_CHECKSUM VARCHAR2(130 BYTE), ZONEFILE_SIGNED VARCHAR2(32767 BYTE), CONSTRAINT DNSZONE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.DNS_ZONE.DNSSEC IS 'Indicates if DNSSEC is enabled for this zone. 0 means DNSSEC is disabled, 1 means DNSSEC is enabled. If NULL, the corresponding field of the DNS zone group is to be considered.';

CREATE TABLE MSS.DNS_ZONE_GROUP (ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, SOA_ADMIN_EMAIL VARCHAR2(50 BYTE) NOT NULL, SOA_DEFAULT_TTL NUMBER(10, 0) NOT NULL, SOA_EXPIRE NUMBER(10, 0) NOT NULL, SOA_MINIMUM_TTL NUMBER(10, 0) NOT NULL, SOA_PRIMARY_NAMESERVER VARCHAR2(2000 BYTE) NOT NULL, SOA_REFRESH NUMBER(10, 0) NOT NULL, SOA_RETRY NUMBER(10, 0) NOT NULL, DNSSEC NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT DNSZONEGROUP_PK PRIMARY KEY (ID));

CREATE TABLE MSS.EXCLUSIVE_IP (ID NUMBER(10, 0) NOT NULL, INTERNAL_ID VARCHAR2(63 BYTE) NOT NULL, CLOUD_REGION_INSTANCE_ID NUMBER(10, 0), SERVICE_ID NUMBER(10, 0), NAME VARCHAR2(128 BYTE) NOT NULL, INTERNAL_IPV4 NUMBER(10, 0), EXTERNAL_IPV4 NUMBER(10, 0), CONSTRAINT EXCLUSIVE_IP_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.EXCLUSIVE_IP IS 'An exclusive IP is available in a single cloud region.
In can be assigned to at most one service.
The service must be a cloud swg.';
COMMENT ON COLUMN MSS.EXCLUSIVE_IP.INTERNAL_ID IS 'DNS label compliant ID, used by the cloud swg helm chart.';
COMMENT ON COLUMN MSS.EXCLUSIVE_IP.CLOUD_REGION_INSTANCE_ID IS 'The cloud region where the external IP has been onboarded (BYOIP).';
COMMENT ON COLUMN MSS.EXCLUSIVE_IP.SERVICE_ID IS 'Service that this public IP is attached to.';
COMMENT ON COLUMN MSS.EXCLUSIVE_IP.NAME IS 'Human reabled name to identify the IP object.';

CREATE TABLE MSS.FIELD_MAPPING (ID NUMBER(10, 0) NOT NULL, OBJECT_TYPE_ID NUMBER(10, 0) NOT NULL, JAVA_FIELD_NAME VARCHAR2(128 BYTE) NOT NULL, FIELD_MAPPING_TYPE_ID NUMBER(10, 0) NOT NULL, COLUMN_NAME VARCHAR2(32 BYTE), REF_TABLE VARCHAR2(65 BYTE), REF_COLUMN VARCHAR2(32 BYTE), ELEMENT_COLUMN VARCHAR2(32 BYTE), LINK_TABLE VARCHAR2(65 BYTE), CONSTRAINT FIELDMAPPING_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.FIELD_MAPPING IS 'stores java/sql field mapping information (filled by the mapping2table script. IDs are NOT guaranteed to stay the same for a given field name.
these objects/rows are not to be referenced by others.)';
COMMENT ON COLUMN MSS.FIELD_MAPPING.OBJECT_TYPE_ID IS 'the object type where this field belongs to';
COMMENT ON COLUMN MSS.FIELD_MAPPING.JAVA_FIELD_NAME IS 'the java field name';
COMMENT ON COLUMN MSS.FIELD_MAPPING.FIELD_MAPPING_TYPE_ID IS 'mapping type (value, one-many, etc.)';
COMMENT ON COLUMN MSS.FIELD_MAPPING.COLUMN_NAME IS 'the database column name in case of simple values or one-to-one mappings (for one-one, the column contains an ID)';
COMMENT ON COLUMN MSS.FIELD_MAPPING.REF_TABLE IS 'the referenced table in case of one-one, one-many and many-many mappings (for many-many, this ist not the link-table, but the table where the link table points to)';
COMMENT ON COLUMN MSS.FIELD_MAPPING.REF_COLUMN IS 'the "back-reference" column name in REF_TABLE for one-many and many-many mappings';
COMMENT ON COLUMN MSS.FIELD_MAPPING.ELEMENT_COLUMN IS 'the "forward-reference" column name in many-many link tables, the column which points to the element table';
COMMENT ON COLUMN MSS.FIELD_MAPPING.LINK_TABLE IS 'the link-table for many-many mappings';

CREATE TABLE MSS.FIELD_MAPPING_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, SHORT VARCHAR2(32 BYTE) NOT NULL, CONSTRAINT FIELDMAPPINGTYPE_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.FIELD_MAPPING_TYPE IS 'value table for field mapping types.';
COMMENT ON COLUMN MSS.FIELD_MAPPING_TYPE.NAME IS 'descriptive, human-readable name';
COMMENT ON COLUMN MSS.FIELD_MAPPING_TYPE.SHORT IS 'short mapping type name exactly like in package.mapping; value, one-one, one-many, many-many';

CREATE TABLE MSS.GEO_LOCATION_IP (ID NUMBER(10, 0) NOT NULL, INTERNAL_ID VARCHAR2(63 BYTE) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, CLOUD_REGION_INSTANCE_ID NUMBER(10, 0), COUNTRY_ID NUMBER(10, 0) NOT NULL, SUBDIVISION_CODE VARCHAR2(6 BYTE), CITY VARCHAR2(32 BYTE), PRIORITY NUMBER(10, 0) NOT NULL, INTERNAL_IPV4 NUMBER(10, 0), EXTERNAL_IPV4 NUMBER(10, 0), CONSTRAINT GEO_LOCATION_IP_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.GEO_LOCATION_IP IS 'A geo location IP represents an egress IP that has a geofeed entry.
Traffic sent to a cloud swg available at the internal IP can egress to the internet with the external IP.
The country, subdivions, city correspond to the geofeed entry for the external IP, NOT the cloud region location.';
COMMENT ON COLUMN MSS.GEO_LOCATION_IP.INTERNAL_ID IS 'DNS label compliant ID, used by the cloud swg helm chart.';
COMMENT ON COLUMN MSS.GEO_LOCATION_IP.NAME IS 'Human reabled name to identify the IP object.';
COMMENT ON COLUMN MSS.GEO_LOCATION_IP.CLOUD_REGION_INSTANCE_ID IS 'The cloud region where the external IP has been onboarded (BYOIP).';
COMMENT ON COLUMN MSS.GEO_LOCATION_IP.PRIORITY IS 'If multiple IPs match a user''s location, the priority is used to decide which one to use. Higher number -> higher priority.';

CREATE TABLE MSS.HARDWARE_LC_LOCATION (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), CONSTRAINT HARDWARELCLOCATION_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.HARDWARE_LC_LOCATION IS 'Hardware Lifecyle location';

CREATE TABLE MSS.HARDWARE_LC_STATE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), CONSTRAINT HARDWARELCSTATE_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.HARDWARE_LC_STATE IS 'Hardware Lifecyle state';

CREATE TABLE MSS.HARDWARE_LC_TRANSIT_INFO (ID NUMBER(10, 0) NOT NULL, URL VARCHAR2(1024 BYTE), COMMENTS VARCHAR2(1024 BYTE), CONSTRAINT HARDWARELCTRANSITINFO_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.HARDWARE_LC_TRANSIT_INFO IS 'Hardware Lifecyle transit info';

CREATE TABLE MSS.HARDWARE_LC_TRANSIT_STATE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), CONSTRAINT HARDWARELCTRANSITSTATE_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.HARDWARE_LC_TRANSIT_STATE IS 'Hardware Lifecyle transit state';

CREATE TABLE MSS.HARDWARE_LICENSE (ID NUMBER(10, 0) NOT NULL, HARDWARE_ID NUMBER(10, 0) NOT NULL, HARDWARE_LICENSE_TYPE_ID NUMBER(10, 0) NOT NULL, START_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, END_DATE TIMESTAMP(6) WITH TIME ZONE, ADDITIONAL_INFO VARCHAR2(1024 BYTE), CONSTRAINT HARDWARELICENSE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.HARDWARE_LICENSE_REQUIREMENT (ID NUMBER(10, 0) NOT NULL, HARDWARE_TYPE_ID NUMBER(10, 0) NOT NULL, HARDWARE_LICENSE_TYPE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT HARDWARELICENSEREQUIREMENT_PK PRIMARY KEY (ID));

CREATE TABLE MSS.HARDWARE_LICENSE_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE) NOT NULL, CONSTRAINT HARDWARELICENSETYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.HARDWARE_USAGE_RULE (ID NUMBER(10, 0) NOT NULL, HARDWARE_TYPE_ID NUMBER(10, 0) NOT NULL, SERVICE_TYPE_ID NUMBER(10, 0) NOT NULL, SERVICE_LEVEL_ID NUMBER(10, 0), COMMENTS VARCHAR2(2000 BYTE), CONSTRAINT HARDWAREUSAGERULE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.HOST_GROUP2HOST_BACKUP (HOST_GROUP_ID NUMBER(10, 0) NOT NULL, HOST_ID NUMBER(10, 0) NOT NULL);

CREATE TABLE MSS.HOST_GROUP2HOST_GROUP_BACKUP (PARENT_ID NUMBER(10, 0) NOT NULL, CHILD_ID NUMBER(10, 0) NOT NULL);

CREATE TABLE MSS.HOST_GROUP_BACKUP (ID NUMBER(10, 0) NOT NULL, VERSION NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE), COMPANY_ID NUMBER(10, 0), NEGATE NUMBER(1, 0) NOT NULL, AUTOMATIC NUMBER(1, 0) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), COMMENTS VARCHAR2(1024 BYTE));

CREATE TABLE MSS.HOST_SECRET (HOST_ID NUMBER(10, 0) NOT NULL, IPSEC_HOST_KEY VARCHAR2(4000 BYTE), SSH_HOST_DSA_KEY VARCHAR2(4000 BYTE), OPENVPN_CLIENT_KEY VARCHAR2(4000 BYTE), LOGFORWARDING_KEY VARCHAR2(32767 BYTE), SSH_HOST_RSA_KEY VARCHAR2(32767 BYTE), SSH_HOST_ED25519_KEY VARCHAR2(32767 BYTE), OPENVPN_SERVER_KEY VARCHAR2(32767 BYTE), CONSTRAINT HOSTSECRET_PK PRIMARY KEY (HOST_ID));

CREATE TABLE MSS.INSTALLATION_PROJECT (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(150 BYTE) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, CUSTOMER_CONTACT_ID NUMBER(10, 0) NOT NULL, OSAG_CONTACT_ID NUMBER(10, 0) NOT NULL, STATUS_COMMENT VARCHAR2(1024 BYTE), COMPLETED NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT INSTALLATIONPROJECT_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT.COMPANY_ID IS 'Reference to the customer company for this project.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT.CUSTOMER_CONTACT_ID IS 'Reference to the responsible project lead on the customer side.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT.OSAG_CONTACT_ID IS 'Reference to the responsible project lead on OSAG side.';
COMMENT ON COLUMN MSS.INSTALLATION_PROJECT.COMPLETED IS 'Denotes the completion of the project.';

CREATE TABLE MSS.INTERCONTINENTAL_LATENCY (DST_CONTINENT_ID NUMBER(10, 0) NOT NULL, REQUIRED_LATENCY NUMBER(10, 0) NOT NULL, SRC_CONTINENT_ID NUMBER(10, 0) NOT NULL);

CREATE TABLE MSS.INTERFACE_ADDRESS (ID NUMBER(10, 0) NOT NULL, INTERFACE_ID NUMBER(10, 0) NOT NULL, IPV6_ADDRESS_ID NUMBER(10, 0) NOT NULL, IPV6_PREFIX_ID NUMBER(10, 0) NOT NULL, MGMTACCESS NUMBER(1, 0) DEFAULT 0 NOT NULL, OSPF_DONT_PROPAGATE NUMBER(1, 0) DEFAULT 0 NOT NULL, VRRP NUMBER(1, 0) DEFAULT 0 NOT NULL, VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, CONSTRAINT INTERFACEADDRESS_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.INTERFACE_ADDRESS.ID IS 'The primary key';
COMMENT ON COLUMN MSS.INTERFACE_ADDRESS.INTERFACE_ID IS 'Reference to the interface';
COMMENT ON COLUMN MSS.INTERFACE_ADDRESS.IPV6_ADDRESS_ID IS 'Reference to the IPv6 address';
COMMENT ON COLUMN MSS.INTERFACE_ADDRESS.IPV6_PREFIX_ID IS 'Reference to the IPV6 prefix the address is in';
COMMENT ON COLUMN MSS.INTERFACE_ADDRESS.MGMTACCESS IS 'Flag whether the address is used for mgmt access';
COMMENT ON COLUMN MSS.INTERFACE_ADDRESS.OSPF_DONT_PROPAGATE IS 'Flag whether to propagate the attached prefix over OSPF or not';
COMMENT ON COLUMN MSS.INTERFACE_ADDRESS.VRRP IS 'Flag whether the address is used as VRRP address';

CREATE TABLE MSS.INTERFACE_DYNAMIC_IP_STATE (ID NUMBER(10, 0) NOT NULL, IFACE_ID NUMBER(10, 0) NOT NULL, PUBLIC_IP_ADDRESS NUMBER(10, 0), MTU NUMBER(10, 0), CHANGE_TIMESTAMP TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT INTERFACEDYNAMICIPSTATE_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.INTERFACE_DYNAMIC_IP_STATE IS 'Host side configuration of dynamic IPv4 interfaces';
COMMENT ON COLUMN MSS.INTERFACE_DYNAMIC_IP_STATE.PUBLIC_IP_ADDRESS IS 'Public Router IP obtained by the reflector service';
COMMENT ON COLUMN MSS.INTERFACE_DYNAMIC_IP_STATE.MTU IS 'The MTU reported by the DHCP options';

CREATE TABLE MSS.INTERFACE_RIP_MODE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, DESCRIPTION VARCHAR2(512 BYTE), CONSTRAINT INTERFACERIPMODE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.INTERFACE_SPEED (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, DESCRIPTION VARCHAR2(512 BYTE), CONSTRAINT INTERFACESPEED_PK PRIMARY KEY (ID));

CREATE TABLE MSS.IPV6_STATIC_ROUTE (ID NUMBER(10, 0) NOT NULL, PREFIX_ID NUMBER(10, 0) NOT NULL, OUTGOING_INTERFACE_ID NUMBER(10, 0), NEXTHOP_ADDRESS_ID NUMBER(10, 0) NOT NULL, ROUTE_OWNER_HOST_ID NUMBER(10, 0) NOT NULL, OSPF_DONT_PROPAGATE_ROUTE NUMBER(1, 0) DEFAULT 0 NOT NULL, COMMENTS VARCHAR2(1000 BYTE), PRIORITY NUMBER(3, 0) DEFAULT 1 NOT NULL, CONSTRAINT IPV6STATICROUTE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.IPV6_STATIC_ROUTE.ID IS 'The primary key';
COMMENT ON COLUMN MSS.IPV6_STATIC_ROUTE.PREFIX_ID IS 'Reference to the prefix that should be routed';
COMMENT ON COLUMN MSS.IPV6_STATIC_ROUTE.OUTGOING_INTERFACE_ID IS 'Reference to the outgoing interface, only mandatory for link local targetted routes';
COMMENT ON COLUMN MSS.IPV6_STATIC_ROUTE.NEXTHOP_ADDRESS_ID IS 'Reference to the IPv6 address of the nexthop/gateway';
COMMENT ON COLUMN MSS.IPV6_STATIC_ROUTE.ROUTE_OWNER_HOST_ID IS 'Reference to the host that owns this route entry';
COMMENT ON COLUMN MSS.IPV6_STATIC_ROUTE.COMMENTS IS 'Optional comment for a route entry';
COMMENT ON COLUMN MSS.IPV6_STATIC_ROUTE.PRIORITY IS 'The priority for default route switching. The lower the number the higher the priority for default routes. The lowest possible value is 1. Must be 1 for all non-default routes.';

