CREATE TABLE MSS.LOGFWD_DAR_SECRET (ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, PUBLIC_KEY VARCHAR2(32767 BYTE) NOT NULL, PRIVATE_KEY VARCHAR2(32767 BYTE), ACTIVATION_DATE TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT LOGFWDDARSECRET_PK PRIMARY KEY (ID));

