CREATE TABLE MSS.NEWS_ENTRY_2_LOGIN_TYPE (ID NUMBER(10, 0) NOT NULL, TYPE VARCHAR2(20 BYTE), CONSTRAINT NEWSENTRY2LOGINTYPE_PK PRIMARY KEY (ID));

