CREATE TABLE MSS.NEWS_ENTRY_IMAGE (ID NUMBER(22, 0) NOT NULL, NAME VARCHAR2(30 BYTE) NOT NULL, REFERENCE VARCHAR2(100 BYTE) NOT NULL, CONSTRAINT NEWSENTRYIMAGE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.NEWS_ENTRY_STATUS (ID NUMBER(22, 0) NOT NULL, NAME VARCHAR2(30 BYTE) NOT NULL, CONSTRAINT NEWSENTRYSTATUS_PK PRIMARY KEY (ID));

CREATE TABLE MSS.OPENVPN_INTERFACE (ID NUMBER(10, 0) NOT NULL, HOST_ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(16 BYTE) NOT NULL, IP_ADDRESS NUMBER(10, 0) NOT NULL, NETWORK_ID NUMBER(10, 0) NOT NULL, MGMTACCESS NUMBER(1, 0) NOT NULL, TIMESTAMP_UPDATE_UNIX_US NUMBER DEFAULT 0, CONSTRAINT OPENVPNINTERFACE_PK PRIMARY KEY (ID));
COMMENT ON TABLE MSS.OPENVPN_INTERFACE IS 'Interfaces of the OpenVPN management environment';
COMMENT ON COLUMN MSS.OPENVPN_INTERFACE.ID IS 'Primary key';
COMMENT ON COLUMN MSS.OPENVPN_INTERFACE.HOST_ID IS 'The host, to which the interface belongs';
COMMENT ON COLUMN MSS.OPENVPN_INTERFACE.NAME IS 'Name of the interface, currently it has to be like ''mvpnX'' (checked by a constraint)';
COMMENT ON COLUMN MSS.OPENVPN_INTERFACE.IP_ADDRESS IS 'The IP address of the interface';
COMMENT ON COLUMN MSS.OPENVPN_INTERFACE.NETWORK_ID IS 'The network directly attached to the interface. Note that the IP_ADDRESS has to lie within this network';
COMMENT ON COLUMN MSS.OPENVPN_INTERFACE.MGMTACCESS IS 'Flag whether or not this interface is used to manage the host.';
COMMENT ON COLUMN MSS.OPENVPN_INTERFACE.TIMESTAMP_UPDATE_UNIX_US IS 'Entry update UNIX timestamp in microseconds from the client-(dis)connect script on the OpenVPN server';

CREATE TABLE MSS.OPERATING_SYSTEM (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, RELEASE VARCHAR2(32 BYTE) NOT NULL, CONSTRAINT OPERATINGSYSTEM_PK PRIMARY KEY (ID));

