COMMENT ON COLUMN MSS.PING_IP_GROUP.NAME IS 'A descriptive name for this set of IP addresses';
COMMENT ON COLUMN MSS.PING_IP_GROUP.COMPANY_ID IS 'Reference to the company id';

CREATE TABLE MSS.PLATFORM_TYPE (ID NUMBER(10, 0) NOT NULL, INTERNAL_CODE VARCHAR2(32 BYTE), DESCRIPTION VARCHAR2(2000 BYTE), DBCOMMENT VARCHAR2(128 BYTE), DEPRECATED NUMBER(1, 0) DEFAULT 0 NOT NULL, DISPLAY_NAME VARCHAR2(32 BYTE), CONSTRAINT PLATFORMTYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.PROJECT_ITEM_STATUS (ID NUMBER(22, 0) NOT NULL, NAME VARCHAR2(30 BYTE) NOT NULL, CONSTRAINT PROJECTITEMSTATUS_PK PRIMARY KEY (ID));

CREATE TABLE MSS.REPORT (ID NUMBER(10, 0) NOT NULL, REPORT_TYPE_ID NUMBER(10, 0) NOT NULL, REPORT_SCHEDULE_ID NUMBER(10, 0) NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, CONTACT_ID NUMBER(10, 0), REQUESTED_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, COMPLETED_DATE TIMESTAMP(6) WITH TIME ZONE, REPORT_STATE_ID NUMBER(10, 0) NOT NULL, REPORT_START_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, REPORT_END_DATE TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT REPORT_PK PRIMARY KEY (ID));
COMMENT ON COLUMN MSS.REPORT.REQUESTED_DATE IS 'The date when the report was requested.';
COMMENT ON COLUMN MSS.REPORT.COMPLETED_DATE IS 'The date when the report was completed or aborted.';
COMMENT ON COLUMN MSS.REPORT.REPORT_START_DATE IS 'The starting date of the report.';
COMMENT ON COLUMN MSS.REPORT.REPORT_END_DATE IS 'The ending date of the report.';

CREATE TABLE MSS.REPORT_CONFIGURATION (ID NUMBER(10, 0) NOT NULL, REPORT_TYPE_ID NUMBER(10, 0) NOT NULL, REPORT_SCHEDULE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT REPORTCONFIGURATION_PK PRIMARY KEY (ID));

CREATE TABLE MSS.REPORT_SCHEDULE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(20 BYTE) NOT NULL, CONSTRAINT REPORTSCHEDULE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.REPORT_STATE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(20 BYTE) NOT NULL, DESCRIPTION VARCHAR2(400 BYTE) NOT NULL, CONSTRAINT REPORTSTATE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.REPORT_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(100 BYTE) NOT NULL, DISPLAY_NAME VARCHAR2(1000 BYTE) NOT NULL, CONSTRAINT REPORTTYPE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.SERVICE2GEO_LOCATION_IP (ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0), ENABLED_GEO_LOCATION_IP_ID NUMBER(10, 0), CONSTRAINT SERVICE2GEO_LOCATION_IP_PK PRIMARY KEY (ID));
