An entry represents that the specified geolocation IP is enabled for the service.
The service must be cloud swg.';

CREATE TABLE MSS.SERVICE_COMPONENT2SERVICE (SERVICE_COMPONENT_ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT SERVICECOMPONENT2SERVICE_PK PRIMARY KEY (SERVICE_COMPONENT_ID, SERVICE_ID));

CREATE TABLE MSS.SERVICE_FEATURE_STATE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(64 BYTE) NOT NULL, DESCRIPTION VARCHAR2(100 BYTE) NOT NULL, CONSTRAINT SERVICEFEATURESTATE_PK PRIMARY KEY (ID));

CREATE TABLE MSS.SERVICE_LEVEL (ID NUMBER(10, 0) NOT NULL, SHORT VARCHAR2(8 BYTE) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, CONSTRAINT SERVICELEVEL_PK PRIMARY KEY (ID));

