CREATE TABLE MSS.UPLOAD_TYPE (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, DESCRIPTION VARCHAR2(1024 BYTE), CONSTRAINT UPLOADTYPE_PK PRIMARY KEY (ID));

