CREATE TABLE NIDS.ENTITY_TYPE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, CONSTRAINT ENTITYTYPE_PK PRIMARY KEY (ID));

