CREATE TABLE NIDS.FILTER_ACTION (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, CONSTRAINT FILTERACTION_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.INVESTIGATION (ID NUMBER(11, 0) NOT NULL, INVESTIGATION_STATUS_ID NUMBER(22, 0) NOT NULL, START_DATE TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, END_DATE TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, INVESTIGATION_FINDING_ID NUMBER(22, 0), COMPANY_ID NUMBER(22, 0) NOT NULL, CONTACT_ID NUMBER(22, 0) NOT NULL, ENTITY_TYPE_ID NUMBER(11, 0) NOT NULL, ENTITY VARCHAR2(255 BYTE) NOT NULL, ENTITY_NAMESPACE VARCHAR2(255 BYTE) NOT NULL, CONSTRAINT INVESTIGATION_PK PRIMARY KEY (ID));
COMMENT ON TABLE NIDS.INVESTIGATION IS 'NIDS investigation';
COMMENT ON COLUMN NIDS.INVESTIGATION.START_DATE IS 'Timestamp when this investigation was opened';
COMMENT ON COLUMN NIDS.INVESTIGATION.END_DATE IS 'Timestamp when this investigation was opened';

CREATE TABLE NIDS.INVESTIGATION_ENTRY (ID NUMBER(11, 0) NOT NULL, EVENT_DATE TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, CONTACT_ID NUMBER(22, 0), INVESTIGATION_ID NUMBER(22, 0) NOT NULL, COMMENTS VARCHAR2(1024 BYTE), CONSTRAINT INVESTIGATIONENTRY_PK PRIMARY KEY (ID));
COMMENT ON TABLE NIDS.INVESTIGATION_ENTRY IS 'NIDS investigation entry';

CREATE TABLE NIDS.INVESTIGATION_FINDING (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, CONSTRAINT INVESTIGATIONFINDING_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.INVESTIGATION_STATUS (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, CONSTRAINT INVESTIGATIONSTATUS_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.KS_ENFORCEMENT (ID NUMBER(22, 0) NOT NULL, INVESTIGATION_ID NUMBER(22, 0) NOT NULL, START_DATE TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, END_DATE TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, ACTIVE NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT KSENFORCEMENT_PK PRIMARY KEY (ID));
COMMENT ON TABLE NIDS.KS_ENFORCEMENT IS 'Kill switch enforcement';
COMMENT ON COLUMN NIDS.KS_ENFORCEMENT.START_DATE IS 'Timestamp when this kill switch enforcement was activated';
COMMENT ON COLUMN NIDS.KS_ENFORCEMENT.END_DATE IS 'Timestamp when this kill switch enforcement is disabled';
COMMENT ON COLUMN NIDS.KS_ENFORCEMENT.ACTIVE IS 'Boolean describing whether the enforcement is currently active';

CREATE TABLE NIDS.KS_ENFORCEMENT_SCOPE (ID NUMBER(22, 0) NOT NULL, KS_ENFORCEMENT_ID NUMBER(22, 0) NOT NULL, KS_SCOPE_ID NUMBER(11, 0) NOT NULL, KS_SCOPE_TYPE_ID NUMBER(11, 0) NOT NULL, CONSTRAINT KSENFORCEMENTSCOPE_PK PRIMARY KEY (ID));
COMMENT ON TABLE NIDS.KS_ENFORCEMENT_SCOPE IS 'Kill switch enforcement scope';

CREATE TABLE NIDS.KS_SCOPE_TYPE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, CONSTRAINT KSSCOPETYPE_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.MDR_FILTER_ACTION (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, CONSTRAINT MDRFILTERACTION_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.MDR_FILTER_RULE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE), ENTITY_GROUP_ID NUMBER(11, 0) NOT NULL, ENTITY_NEGATE NUMBER(1, 0) DEFAULT 0 NOT NULL, MDR_SIGNATURE_GROUP_ID NUMBER(11, 0) NOT NULL, DISABLED NUMBER(1, 0) DEFAULT 0 NOT NULL, COMMENTS VARCHAR2(1024 BYTE), COMPANY_ID NUMBER(11, 0), MDR_FILTER_ACTION_ID NUMBER(11, 0) NOT NULL, CONSTRAINT MDRFILTERRULE_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.MDR_SIGNATURE (ID NUMBER(11, 0) NOT NULL, SENTINEL_ID VARCHAR2(255 BYTE) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, COMPANY_ID NUMBER(11, 0), XDR_TYPE_ID NUMBER(11, 0), CONSTRAINT MDRSIGNATURE_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.MDR_SIGNATURE_GROUP (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE), COMPANY_ID NUMBER(11, 0), AUTOMATIC NUMBER(1, 0) DEFAULT 0 NOT NULL, CONSTRAINT MDRSIGNATUREGROUP_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.MDR_SIGNATURE_GROUP_MEMBER (ID NUMBER(11, 0) NOT NULL, MDR_SIGNATURE_GROUP_ID NUMBER(11, 0) NOT NULL, MDR_MEMBER_SIGNATURE_GROUP_ID NUMBER(11, 0), MDR_SIGNATURE_ID NUMBER(11, 0), MDR_SIG_GROUP_MEMBER_TYPE NUMBER(11, 0) NOT NULL, CONSTRAINT MDRSIGNATUREGROUPMEMBER_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.MDR_SIG_GROUP_MEMBER_TYPE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, CONSTRAINT MDRSIGGROUPMEMBERTYPE_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.NIDS_DEVICE (ID NUMBER(11, 0) NOT NULL, DEVICE VARCHAR2(255 BYTE) NOT NULL, COMPANY_ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE), COMMENTS VARCHAR2(1024 BYTE), CONSTRAINT NIDSDEVICE_PK PRIMARY KEY (ID));
COMMENT ON TABLE NIDS.NIDS_DEVICE IS 'A device';

CREATE TABLE NIDS.NIDS_ENTITY_TYPE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, CONSTRAINT NIDSENTITYTYPE_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.NIDS_FILE (ID NUMBER(11, 0) NOT NULL, NIDS_FILE VARCHAR2(1024 BYTE) NOT NULL, COMPANY_ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE), COMMENTS VARCHAR2(1024 BYTE), CONSTRAINT NIDSFILE_PK PRIMARY KEY (ID));
COMMENT ON TABLE NIDS.NIDS_FILE IS 'A NIDS file';
COMMENT ON COLUMN NIDS.NIDS_FILE.NIDS_FILE IS 'Can contain a hash, a filename or (parts of) a path';

CREATE TABLE NIDS.NIDS_IPV6_ADDRESS (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE), COMPANY_ID NUMBER(11, 0), ADDRESS_1 NUMBER(20, 0) NOT NULL, ADDRESS_2 NUMBER(20, 0) NOT NULL, COMMENTS VARCHAR2(1024 BYTE), CONSTRAINT NIDSIPV6ADDRESS_PK PRIMARY KEY (ID));
COMMENT ON COLUMN NIDS.NIDS_IPV6_ADDRESS.NAME IS 'An optional name for the IPv6 address';
COMMENT ON COLUMN NIDS.NIDS_IPV6_ADDRESS.COMPANY_ID IS 'A reference to the company this address belongs to. If null, the address is shared among all companies.';
COMMENT ON COLUMN NIDS.NIDS_IPV6_ADDRESS.ADDRESS_1 IS 'The most significant 64 bits of the address.';
COMMENT ON COLUMN NIDS.NIDS_IPV6_ADDRESS.ADDRESS_2 IS 'The least significant 64 bits of the address.';
COMMENT ON COLUMN NIDS.NIDS_IPV6_ADDRESS.COMMENTS IS 'An optional comment to the address.';

CREATE TABLE NIDS.NIDS_IPV6_PREFIX (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE), COMPANY_ID NUMBER(11, 0), ADDRESS_1 NUMBER(20, 0) NOT NULL, ADDRESS_2 NUMBER(20, 0) NOT NULL, MASK NUMBER(3, 0) NOT NULL, COMMENTS VARCHAR2(1024 BYTE), CONSTRAINT NIDSIPV6PREFIX_PK PRIMARY KEY (ID));
COMMENT ON COLUMN NIDS.NIDS_IPV6_PREFIX.ID IS 'The primary key';
COMMENT ON COLUMN NIDS.NIDS_IPV6_PREFIX.NAME IS 'An optional name for the IPv6 prefix';
COMMENT ON COLUMN NIDS.NIDS_IPV6_PREFIX.COMPANY_ID IS 'A reference to the company this prefix belongs to. If null, the prefix is shared among all companies.';
COMMENT ON COLUMN NIDS.NIDS_IPV6_PREFIX.ADDRESS_1 IS 'The higher 64bit of the prefix';
COMMENT ON COLUMN NIDS.NIDS_IPV6_PREFIX.ADDRESS_2 IS 'The lower 64bit of the prefix, usually 0';
COMMENT ON COLUMN NIDS.NIDS_IPV6_PREFIX.MASK IS 'The netmask of this prefix in CIDR notation.';
COMMENT ON COLUMN NIDS.NIDS_IPV6_PREFIX.COMMENTS IS 'An optional comment to the address.';

CREATE TABLE NIDS.NIDS_IP_ADDRESS (ID NUMBER(11, 0) NOT NULL, IP_ADDRESS NUMBER(10, 0) NOT NULL, NAME VARCHAR2(255 BYTE), COMPANY_ID NUMBER(11, 0), COMMENTS VARCHAR2(1024 BYTE), CONSTRAINT NIDSIPADDRESS_PK PRIMARY KEY (ID));
COMMENT ON TABLE NIDS.NIDS_IP_ADDRESS IS 'Simple IP addresses';

CREATE TABLE NIDS.NIDS_IP_NETWORK (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE), IP_ADDRESS NUMBER(10, 0) NOT NULL, NETMASK NUMBER(2, 0) NOT NULL, SCOPE_COMPANY_ID NUMBER(11, 0), COMMENTS VARCHAR2(1024 BYTE), CONSTRAINT NIDSIPNETWORK_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.NIDS_USER (ID NUMBER(11, 0) NOT NULL, USER_NAME VARCHAR2(255 BYTE) NOT NULL, COMPANY_ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE), COMMENTS VARCHAR2(1024 BYTE), CONSTRAINT NIDSUSER_PK PRIMARY KEY (ID));
COMMENT ON TABLE NIDS.NIDS_USER IS 'A NIDS user';

CREATE TABLE NIDS.POLICY_RULE (ID NUMBER(11, 0) NOT NULL, DESCRIPTION VARCHAR2(255 BYTE), PRECEDENCE NUMBER(11, 0) NOT NULL, DIRECTION_ID NUMBER(11, 0), SRC_AUTOMATIC_IP_GROUP_ID NUMBER(11, 0), DST_AUTOMATIC_IP_GROUP_ID NUMBER(11, 0), SIGNATURE_GROUP_ID NUMBER(11, 0), COMPANY_ID NUMBER(11, 0), SERVICE_ID NUMBER(11, 0), CONSTRAINT POLICY_RULE_PK PRIMARY KEY (ID));
COMMENT ON TABLE NIDS.POLICY_RULE IS 'NDR Policy Rules that define automated responses to network security events based on criteria like direction, source/destination, signatures, and organizational scope';
COMMENT ON COLUMN NIDS.POLICY_RULE.DESCRIPTION IS 'Optional string that describes why this rule exists';
COMMENT ON COLUMN NIDS.POLICY_RULE.PRECEDENCE IS 'Ordering of the rules. Per scope the rules are processed/checked in an order, lowest number for precedence is checked first';
COMMENT ON COLUMN NIDS.POLICY_RULE.DIRECTION_ID IS 'FK to table NIDS.DIRECTION. NULL means any direction';
COMMENT ON COLUMN NIDS.POLICY_RULE.SRC_AUTOMATIC_IP_GROUP_ID IS 'FK to table FW.IP_GROUP. NULL means any source. This IP Group will be an automatic IP group that is created (similar as for firewall rules) if a source is being added to a rule';
COMMENT ON COLUMN NIDS.POLICY_RULE.DST_AUTOMATIC_IP_GROUP_ID IS 'FK to table FW.IP_GROUP. NULL means any destination. This IP Group will be an automatic IP group that is created (similar as for firewall rules) if a destination is being added to a rule';
COMMENT ON COLUMN NIDS.POLICY_RULE.SIGNATURE_GROUP_ID IS 'FK to table NIDS.SIGNATURE_GROUP, the linked signature group has the automatic flag set (i.e. a new automatic signature group is created if a signature is selected as a filter). NULL means any signature';
COMMENT ON COLUMN NIDS.POLICY_RULE.COMPANY_ID IS 'FK to table STOP.COMPANY. Needs to be set when when scope is company or service';
COMMENT ON COLUMN NIDS.POLICY_RULE.SERVICE_ID IS 'FK to table MSS.SERVICE. Needs to be set when when scope is service';

CREATE TABLE NIDS.RULE2ACTION (RULE_ID NUMBER(11, 0) NOT NULL, ACTION_ID NUMBER(11, 0) NOT NULL, CONSTRAINT RULE2ACTION_PK PRIMARY KEY (RULE_ID, ACTION_ID));
COMMENT ON TABLE NIDS.RULE2ACTION IS 'Junction table that links NDR Policy Rules with one or more Actions';
COMMENT ON COLUMN NIDS.RULE2ACTION.RULE_ID IS 'FK to NIDS.POLICY_RULE, one rule can have multiple actions';
COMMENT ON COLUMN NIDS.RULE2ACTION.ACTION_ID IS 'FK to NIDS.ACTION, defines which action to execute';

CREATE TABLE NIDS.RULE2TICKET (RULE_ID NUMBER(11, 0) NOT NULL, TICKET_ID NUMBER(11, 0) NOT NULL, CONSTRAINT RULE2TICKET_PK PRIMARY KEY (RULE_ID, TICKET_ID));
COMMENT ON TABLE NIDS.RULE2TICKET IS 'Junction table that links NDR Policy Rules to tickets';
COMMENT ON COLUMN NIDS.RULE2TICKET.RULE_ID IS 'FK to NIDS.POLICY_RULE, one rule can create multiple tickets';
COMMENT ON COLUMN NIDS.RULE2TICKET.TICKET_ID IS 'FK to TT.TICKET, reference to the created ticket';

CREATE TABLE NIDS.SCOPE (ID NUMBER(11, 0) NOT NULL, COMPANY_ID NUMBER(11, 0), SERVICE_ID NUMBER(11, 0), CONSTRAINT SCOPE_PK PRIMARY KEY (ID));

