CREATE TABLE NIDS.SIGNATURE_GROUP (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE), AUTOMATIC NUMBER(1, 0) DEFAULT 0 NOT NULL, COMMENTS VARCHAR2(1024 BYTE), COMPANY_ID NUMBER(11, 0), CONSTRAINT SIGNATUREGROUP_PK PRIMARY KEY (ID));
COMMENT ON TABLE NIDS.SIGNATURE_GROUP IS 'group of signature objects';
COMMENT ON COLUMN NIDS.SIGNATURE_GROUP.AUTOMATIC IS 'The boolean property "automatic" defines whether this group has been automatically created or if it was created by a user.';

CREATE TABLE NIDS.SIGNATURE_GROUP_MEMBER (ID NUMBER(11, 0) NOT NULL, SIGNATURE_GROUP_ID NUMBER(11, 0) NOT NULL, MEMBER_TYPE_ID NUMBER(11, 0) NOT NULL, SIGNATURE_ID NUMBER(11, 0), DYNAMIC_SIGNATURE_GROUP_ID NUMBER(11, 0), MEMBER_SIGNATURE_GROUP_ID NUMBER(11, 0), CONSTRAINT SIGNATUREGROUPMEMBER_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.SIGNATURE_GROUP_MEMBER_TYPE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, CONSTRAINT SIGNATUREGROUPMEMBERTYPE_PK PRIMARY KEY (ID));

