CREATE TABLE NIDS.SIGNATURE_REFERENCE_TYPE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE), CONSTRAINT SIGNATUREREFERENCETYPE_PK PRIMARY KEY (ID));

CREATE TABLE NIDS.XDR_TYPE (ID NUMBER(11, 0) NOT NULL, NAME VARCHAR2(255 BYTE) NOT NULL, CONSTRAINT XDRTYPE_PK PRIMARY KEY (ID));

