CREATE TABLE PRX.CLOUDSWG_SERVICE2IDAC_SERVICE (ID NUMBER(10, 0) NOT NULL, CLOUDSWG_SERVICE_ID NUMBER(10, 0) NOT NULL, IDAC_SERVICE_ID NUMBER(10, 0) NOT NULL, CONSTRAINT CLOUDSWG_SERVICE2IDAC_SERVICE_PK PRIMARY KEY (ID));
COMMENT ON TABLE PRX.CLOUDSWG_SERVICE2IDAC_SERVICE IS 'Enforement point (IDAC) and cloud swg are separate services.
They must be linked for the cswg to be reachable.';

CREATE TABLE PRX.MSCAS_APP_BLOCKUNSANCTIONED (ID NUMBER(10, 0) NOT NULL, ITEM_VALUE VARCHAR2(1000 BYTE) NOT NULL, CONSTRAINT MSCASAPPBLOCKUNSANCTIONED_PK PRIMARY KEY (ID));

