CREATE TABLE UAI.APP (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, COMPANY_ID NUMBER(10, 0), DESCRIPTION VARCHAR2(512 BYTE), VENDOR VARCHAR2(128 BYTE), ENABLED NUMBER(1, 0) DEFAULT 1 NOT NULL, WEBSITE VARCHAR2(256 BYTE), ICON VARCHAR2(256 BYTE), INCLUDE_APP_ID NUMBER(10, 0), TAGS VARCHAR2(512 BYTE), SELECTOR_QUICKID_ID NUMBER(10, 0), CREATE_USER VARCHAR2(128 BYTE), CREATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, UPDATE_USER VARCHAR2(128 BYTE), UPDATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, VERSION NUMBER(10, 0) DEFAULT 0 NOT NULL, CONSTRAINT PK_APP PRIMARY KEY (ID));
