CREATE TABLE UAI.APP_GROUP (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(128 BYTE) NOT NULL, COMPANY_ID NUMBER(10, 0), DESCRIPTION VARCHAR2(512 BYTE), TAGS VARCHAR2(512 BYTE), CREATE_USER VARCHAR2(128 BYTE), CREATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, UPDATE_USER VARCHAR2(128 BYTE), UPDATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, CONSTRAINT PK_APP_GROUP PRIMARY KEY (ID));
COMMENT ON TABLE UAI.APP_GROUP IS 'Unified Application Groups';
COMMENT ON COLUMN UAI.APP_GROUP.COMPANY_ID IS 'null for shared groups';
COMMENT ON COLUMN UAI.APP_GROUP.TAGS IS 'Space separated list of tags';
COMMENT ON COLUMN UAI.APP_GROUP.CREATE_USER IS 'Zitadel ID or k8s service account';
COMMENT ON COLUMN UAI.APP_GROUP.UPDATE_USER IS 'Zitadel ID or k8s service account';

