COMMENT ON TABLE UAI.PROPERTY IS 'Properties Masterdata';
COMMENT ON COLUMN UAI.PROPERTY.NAME IS 'Property name';
COMMENT ON COLUMN UAI.PROPERTY.REGEX IS 'Regex to validate property values';

CREATE TABLE UAI.SELECTOR (ID NUMBER(10, 0) NOT NULL, APP_ID NUMBER(10, 0) NOT NULL, TRAFFIC_CLASS_ID NUMBER(10, 0) NOT NULL, DST_IP_GROUP_ID NUMBER(10, 0), DST_SVC_GROUP_ID NUMBER(10, 0), CREATE_USER VARCHAR2(128 BYTE), CREATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, UPDATE_USER VARCHAR2(128 BYTE), UPDATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, CONSTRAINT PK_SELECTOR PRIMARY KEY (ID));
COMMENT ON TABLE UAI.SELECTOR IS 'Entity-based Selectors';
COMMENT ON COLUMN UAI.SELECTOR.DST_IP_GROUP_ID IS 'Automatic IP Group';
COMMENT ON COLUMN UAI.SELECTOR.DST_SVC_GROUP_ID IS 'Automatic Service Group';

CREATE TABLE UAI.SELECTOR_QUICKID (ID NUMBER(10, 0) NOT NULL, QUICKID_ID NUMBER(10, 0), TRAFFIC_CLASS_ID NUMBER(10, 0), CREATE_USER VARCHAR2(128 BYTE), CREATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, UPDATE_USER VARCHAR2(128 BYTE), UPDATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, CONSTRAINT PK_SELECTOR_QUICKID PRIMARY KEY (ID));
