CREATE TABLE UAI.SELECTOR_TOS (ID NUMBER(10, 0) NOT NULL, SELECTOR_ID NUMBER(10, 0) NOT NULL, MASK NUMBER(3, 0) NOT NULL, VALUE NUMBER(3, 0) NOT NULL, COMMENTS VARCHAR2(512 BYTE), CREATE_USER VARCHAR2(128 BYTE), CREATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, UPDATE_USER VARCHAR2(128 BYTE), UPDATED TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP, CONSTRAINT PK_SELECTORTOS PRIMARY KEY (ID));
