COMMENT ON TABLE UPOL.PROPERTY IS 'Policy properties masterdata';

CREATE TABLE VPN."#JDO_PROPERTIES" (KEY VARCHAR2(400 BYTE) NOT NULL, VALUE VARCHAR2(400 BYTE) DEFAULT 'none', CONSTRAINT JDO_PROPERTIES_PK PRIMARY KEY (KEY));

CREATE TABLE VPN.IPSEC_SECRET (ID NUMBER(10, 0) NOT NULL, INTERFACE_ID NUMBER(10, 0) NOT NULL, RSA_PRIVATE VARCHAR2(4000 BYTE), RSA_PUBLIC VARCHAR2(1024 BYTE), PEM_PRIVATE VARCHAR2(4000 BYTE), PEM_PUBLIC VARCHAR2(1024 BYTE), PEM_PRIVATE_REPLACEMENT VARCHAR2(4000 BYTE), PEM_PUBLIC_REPLACEMENT VARCHAR2(1024 BYTE), TS_REPLACEMENT NUMBER(10, 0), TS_KEY NUMBER(10, 0), CONSTRAINT IPSECSECRET_PK PRIMARY KEY (ID));

CREATE TABLE VPN.PARTNER_ACCESS_RANGE (ID NUMBER(10, 0) NOT NULL, PARTNER_STATIC_NET_ID NUMBER(10, 0) NOT NULL, RANGE_NETWORK_ADDRESS_1 NUMBER(20, 0), RANGE_NETWORK_ADDRESS_2 NUMBER(20, 0) NOT NULL, RANGE_NETWORK_MASK NUMBER(3, 0) NOT NULL, CONSTRAINT PARTNERACCESSRANGE_PK PRIMARY KEY (ID));
COMMENT ON COLUMN VPN.PARTNER_ACCESS_RANGE.RANGE_NETWORK_ADDRESS_1 IS 'The higher 64bit of the prefix in case of IPv6 or null in case of IPv4.';
COMMENT ON COLUMN VPN.PARTNER_ACCESS_RANGE.RANGE_NETWORK_ADDRESS_2 IS 'The lower 64bit of the prefix (IPv4/v6)';
COMMENT ON COLUMN VPN.PARTNER_ACCESS_RANGE.RANGE_NETWORK_MASK IS 'The netmask of this prefix in CIDR notation.';

CREATE TABLE VPN.PARTNER_CONTACT (ID NUMBER(10, 0) NOT NULL, PARTNER_PHASE1_ID NUMBER(10, 0) NOT NULL, CONTACT_NAME VARCHAR2(100 BYTE), CONTACT_EMAIL VARCHAR2(100 BYTE), CONTACT_PHONE VARCHAR2(100 BYTE), CUSTOMER_CONTACT_ID NUMBER(10, 0), CONSTRAINT PARTNERCONTACT_PK PRIMARY KEY (ID));

CREATE TABLE VPN.PARTNER_IFACE (ID NUMBER(10, 0) NOT NULL, PARTNER_PHASE1_ID NUMBER(10, 0) NOT NULL, IPV6_INTERFACE_ADDRESS_ID NUMBER(10, 0), IPV4_INTERFACE_ID NUMBER(10, 0), CONSTRAINT PARTNERIFACE_PK PRIMARY KEY (ID));

CREATE TABLE VPN.PARTNER_LOCATION (ID NUMBER(10, 0) NOT NULL, PARTNER_PHASE1_ID NUMBER(10, 0) NOT NULL, ADDRESS VARCHAR2(256 BYTE) NOT NULL, CONSTRAINT PARTNERLOCATION_PK PRIMARY KEY (ID));

CREATE TABLE VPN.PARTNER_MONITORING (ID NUMBER(10, 0) NOT NULL, PARTNER_PHASE2_ID NUMBER(10, 0) NOT NULL, MONITORING_IP_1 NUMBER(20, 0), MONITORING_IP_2 NUMBER(20, 0) NOT NULL, CONSTRAINT PARTNERMONITORING_PK PRIMARY KEY (ID));
COMMENT ON COLUMN VPN.PARTNER_MONITORING.MONITORING_IP_1 IS 'The higher 64bit of the prefix in case of IPv6 or null in case of IPv4.';
COMMENT ON COLUMN VPN.PARTNER_MONITORING.MONITORING_IP_2 IS 'The lower 64bit of the prefix (IPv4/v6)';

CREATE TABLE VPN.PARTNER_PHASE1 (ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0) NOT NULL, CUSTOMER_COMPANY_ID NUMBER(10, 0) NOT NULL, PARTNER_NAME VARCHAR2(100 BYTE), PARTNER_IP1 NUMBER(20, 0), PARTNER_IP2 NUMBER(20, 0) NOT NULL, PARTNER_MTU NUMBER(10, 0) NOT NULL, DEVICE VARCHAR2(128 BYTE), IKE_VERSION NUMBER(10, 0) NOT NULL, SHARED_SECRET VARCHAR2(100 BYTE) NOT NULL, SECURE_LEVEL VARCHAR2(100 BYTE), ENCRYPTION VARCHAR2(100 BYTE), HASH_ALGORITHM VARCHAR2(100 BYTE), DH_GROUP VARCHAR2(100 BYTE), LIFE NUMBER(10, 0), DPD_ACTION VARCHAR2(100 BYTE), DPD_DELAY NUMBER(10, 0), DPD_TIMEOUT NUMBER(10, 0), LOCAL_AUTH_ID VARCHAR2(100 BYTE), CONSTRAINT PARTNERPHASE1_PK PRIMARY KEY (ID));
COMMENT ON COLUMN VPN.PARTNER_PHASE1.PARTNER_IP1 IS 'The most significant 64 bits of the IPv6 address. Not set in case of an IPv4 address.';
COMMENT ON COLUMN VPN.PARTNER_PHASE1.PARTNER_IP2 IS 'The least significant 64 bits of the IPv4/v6 address.';
COMMENT ON COLUMN VPN.PARTNER_PHASE1.LOCAL_AUTH_ID IS 'IKE identity to use for authentication round of local end of the tunnel. Can be an IP address, a fully-qualified domain name, an email address or a Distinguished Name.';

CREATE TABLE VPN.PARTNER_PHASE2 (ID NUMBER(10, 0) NOT NULL, PARTNER_PHASE1_ID NUMBER(10, 0) NOT NULL, PHASE2_NAME VARCHAR2(100 BYTE), LOCAL_NETWORK_ADDRESS_1 NUMBER(20, 0), LOCAL_NETWORK_ADDRESS_2 NUMBER(20, 0) NOT NULL, LOCAL_NETWORK_MASK NUMBER(3, 0) NOT NULL, PARTNER_NETWORK_ADDRESS_1 NUMBER(20, 0), PARTNER_NETWORK_ADDRESS_2 NUMBER(20, 0) NOT NULL, PARTNER_NETWORK_MASK NUMBER(3, 0) NOT NULL, INTERN_NETWORK_ADDRESS_1 NUMBER(20, 0), INTERN_NETWORK_ADDRESS_2 NUMBER(20, 0) NOT NULL, INTERN_NETWORK_MASK NUMBER(3, 0) NOT NULL, NAT_IP1 NUMBER(20, 0), NAT_IP2 NUMBER(20, 0), LOCAL_PING_IP1 NUMBER(20, 0), LOCAL_PING_IP2 NUMBER(20, 0), DIRECTION VARCHAR2(100 BYTE) NOT NULL, SECURE_LEVEL VARCHAR2(100 BYTE), ENCRYPTION VARCHAR2(100 BYTE), HASH_ALGORITHM VARCHAR2(100 BYTE), PFS_GROUP VARCHAR2(100 BYTE), LIFE NUMBER(10, 0), BYTES NUMBER(10, 0), REQUIRED_LATENCY NUMBER(10, 0) DEFAULT 200 NOT NULL, CONSTRAINT PARTNERPHASE2_PK PRIMARY KEY (ID));
COMMENT ON COLUMN VPN.PARTNER_PHASE2.LOCAL_NETWORK_ADDRESS_1 IS 'The higher 64bit of the prefix in case of IPv6 or null in case of IPv4.';
COMMENT ON COLUMN VPN.PARTNER_PHASE2.LOCAL_NETWORK_ADDRESS_2 IS 'The lower 64bit of the prefix (IPv4/v6)';
COMMENT ON COLUMN VPN.PARTNER_PHASE2.LOCAL_NETWORK_MASK IS 'The netmask of this prefix in CIDR notation.';
COMMENT ON COLUMN VPN.PARTNER_PHASE2.PARTNER_NETWORK_ADDRESS_1 IS 'The higher 64bit of the prefix in case of IPv6 or null in case of IPv4.';
COMMENT ON COLUMN VPN.PARTNER_PHASE2.PARTNER_NETWORK_ADDRESS_2 IS 'The lower 64bit of the prefix (IPv4/v6)';
COMMENT ON COLUMN VPN.PARTNER_PHASE2.PARTNER_NETWORK_MASK IS 'The netmask of this prefix in CIDR notation.';
COMMENT ON COLUMN VPN.PARTNER_PHASE2.INTERN_NETWORK_ADDRESS_1 IS 'The higher 64bit of the prefix in case of IPv6 or null in case of IPv4.';
COMMENT ON COLUMN VPN.PARTNER_PHASE2.INTERN_NETWORK_ADDRESS_2 IS 'The lower 64bit of the prefix (IPv4/v6)';
COMMENT ON COLUMN VPN.PARTNER_PHASE2.INTERN_NETWORK_MASK IS 'The netmask of this prefix in CIDR notation.';
COMMENT ON COLUMN VPN.PARTNER_PHASE2.NAT_IP1 IS 'The most significant 64 bits of the IPv6 address. Not set in case of an IPv4 address.';
COMMENT ON COLUMN VPN.PARTNER_PHASE2.NAT_IP2 IS 'The least significant 64 bits of the IPv4/v6 address.';
COMMENT ON COLUMN VPN.PARTNER_PHASE2.LOCAL_PING_IP1 IS 'The most significant 64 bits of the IPv6 local ping address. Not set in case of an IPv4 address.';
COMMENT ON COLUMN VPN.PARTNER_PHASE2.LOCAL_PING_IP2 IS 'The least significant 64 bits of the IPv4/v6 local ping address.';

CREATE TABLE VPN.PARTNER_STATIC_NET (ID NUMBER(10, 0) NOT NULL, SERVICE_ID NUMBER(10, 0) NOT NULL, LOCAL_NETWORK_ADDRESS_1 NUMBER(20, 0), LOCAL_NETWORK_ADDRESS_2 NUMBER(20, 0) NOT NULL, LOCAL_NETWORK_MASK NUMBER(3, 0) NOT NULL, CONSTRAINT PARTNERSTATICNET_PK PRIMARY KEY (ID));
COMMENT ON COLUMN VPN.PARTNER_STATIC_NET.LOCAL_NETWORK_ADDRESS_1 IS 'The higher 64bit of the prefix in case of IPv6 or null in case of IPv4.';
