CREATE TABLE VPN.TUNNEL_RATING (ID NUMBER(10, 0) NOT NULL, TUNNEL_ID NUMBER(10, 0) NOT NULL, TUNNEL_RATING_INTERVAL_ID NUMBER(10, 0) NOT NULL, TIMESTAMP NUMBER(10, 0) NOT NULL, RATING_RTT NUMBER(2, 0), RATING_LOSS NUMBER(2, 0), RATING_STABILITY NUMBER(2, 0), RATING_AVAILABILITY NUMBER(2, 0), RATING_TOTAL NUMBER(2, 0), REMARK VARCHAR2(4000 BYTE), RTT_MEDIAN NUMBER(10, 0), RTT_INTERVAL_MEDIAN NUMBER(10, 0), LOSS_MEAN NUMBER(10, 0), LOSS_MEAN_FRACTION NUMBER(10, 0), RTT_IQR NUMBER(10, 0), LOSS_IDR NUMBER(10, 0), REF_RTT_MEDIAN NUMBER(10, 0), REF_RTT_INTERVAL_MEDIAN NUMBER(10, 0), REF_LOSS_MEAN NUMBER(10, 0), REF_LOSS_MEAN_FRACTION NUMBER(10, 0), REF_SEARCH_RADIUS NUMBER(10, 0), REF_SIMILARITY VARCHAR2(4000 BYTE), REF_RTT_IQR NUMBER(10, 0), REF_LOSS_IDR NUMBER(10, 0), REF_COUNT NUMBER(10, 0), DOWN_EVENTS NUMBER(10, 0), DOWN_TIME NUMBER(10, 0), ACTIVE NUMBER(1, 0) DEFAULT 1 NOT NULL, IDLE NUMBER(1, 0) DEFAULT 0 NOT NULL, COMPANY_ID NUMBER(10, 0) NOT NULL, LOAD_IN_MEAN NUMBER(10, 0), LOAD_OUT_MEAN NUMBER(10, 0), LOAD_IN_INTERVAL_MEAN NUMBER(10, 0), LOAD_OUT_INTERVAL_MEAN NUMBER(10, 0), LOSS2ZERO_LOSS NUMBER(10, 0), REF_LOSS2ZERO_LOSS NUMBER(10, 0), CONSTRAINT TUNNELRATING_PK PRIMARY KEY (ID));

CREATE TABLE VPN.TUNNEL_RATING_INTERVAL (ID NUMBER(10, 0) NOT NULL, DURATION NUMBER(10, 0) NOT NULL, NAME VARCHAR2(1024 BYTE) NOT NULL, CONSTRAINT TUNNELRATINGINTERVAL_PK PRIMARY KEY (ID));

CREATE TABLE VPN.VPN (ID NUMBER(10, 0) NOT NULL, NAME VARCHAR2(32 BYTE) NOT NULL, NETWORK_ID NUMBER(10, 0) NOT NULL, AUTHOR VARCHAR2(64 BYTE), COMMENTS VARCHAR2(1024 BYTE), COMPANY_ID NUMBER(10, 0) NOT NULL, CONSTRAINT VPN_PK PRIMARY KEY (ID));

