CREATE OR REPLACE FORCE VIEW "MSS"."V_HOST_KEY_VALUE" ("HOST_ID", "KEY_NAME", "SCOPE", "OBJECT_ID", "STRING_VALUE") AS select distinct v.host_id,
       v.key_name as key_name,
       decode(v.n_scope,
              1, 'host',
              2, 'service',
              3, 'group',
              4, 'vpn',
              5, 'company',
              'default') as scope,
       v.object_id,
       v.string_value
from
  (select v.*,
      min(v.n_scope) over (partition by v.HOST_ID, v.key_name) as min_scope
    from mss.mv_value_host_default v) v
where v.min_scope = v.n_scope;

